Here are simple publish‑subscribe emitters in **TypeScript** and **Python**.

---

## TypeScript (Node.js)

```ts
// pubsub.ts --------------------------------------------------------------
type Listener<T> = (...args: T[]) => void;

export class PubSub {
  private handlers: Map<string, Listener<any>[]> = new Map();

  /** Subscribe to an event */
  on(event: string, listener: Listener<any>): () => void {
    const listeners = this.handlers.get(event) || [];
    listeners.push(listener);
    this.handlers.set(event, listeners);

    // Return a cleanup function
    return () => this.off(event, listener);
  }

  /** Remove a specific listener */
  off(event: string, listener: Listener<any>): boolean {
    const list = this.handlers.get(event);
    if (!list) return false;
    const idx = list.indexOf(listener);
    if (idx === -1) return false;
    list.splice(idx, 1);
    return true;
  }

  /** Publish an event with optional arguments */
  emit(event: string, ...args: any[]): void {
    const listeners = this.handlers.get(event)?.slice() || [];
    for (const listener of listeners) {
      listener(...args);
    }
  }
}
```

**Usage example**

```ts
import { PubSub } from './pubsub';

// Create an emitter instance
const pubsub = new PubSub();

// Subscribe to "message" events with a handler that logs the payload
const unsubscribe = pubsub.on('message', (msg: string) => {
  console.log(`Received message: ${msg}`);
});

// Publish messages
pubsub.emit('message', 'Hello, world!');
pubsub.emit('message', 'Another event');

// Clean up when done
unsubscribe();
```

---

## Python

```python
# pubsub.py --------------------------------------------------------------
from typing import Callable, Any


class PubSub:
    """Simple publish‑subscribe emitter."""

    def __init__(self):
        # Maps an event name to a list of listener callables.
        self._handlers: dict[str, list[Callable[..., None]]] = {}

    def on(self, event: str, listener: Callable[..., Any]) -> Callable[[], None]:
        """Subscribe to an event."""
        if event not in self._handlers:
            self._handlers[event] = []
        self._handlers[event].append(listener)

        # Return a cleanup function that removes the listener
        def remove():
            try:
                self._handlers[event].remove(listener)
            except ValueError:
                pass  # already removed

        return remove

    def off(self, event: str, listener: Callable[..., Any]) -> bool:
        """Remove a specific listener."""
        if event not in self._handlers:
            return False
        try:
            self._handlers[event].remove(listener)
            return True
        except ValueError:
            # Listener never registered for this event
            return False

    def emit(self, event: str, *args: Any) -> None:
        """Publish an event to all subscribed listeners."""
        if event not in self._handlers:
            return  # no listeners attached
        for listener in list(self._handlers[event]):   # copy while iterating
            listener(*args)
```

**Usage example**

```python
from pubsub import PubSub

# Create an emitter instance
pubsub = PubSub()

# Subscribe to "greeting" events
def greet(name: str):
    print(f"Hello, {name}!")

unsubscribe = pubsub.on("greeting", greet)

# Publish messages
pubsub.emit("greeting", "Alice")
pubsub.emit("greeting", "Bob")

# Clean up when finished
unsubscribe()
```

