// workerPool.ts -------------------------------------------------------------
import { Worker, isMainThread } from "worker_threads";

type Job = () => Promise<void>;

/**
 * Simple concurrent worker pool.
 *
 * @param jobs – array of async functions (jobs) to run.
 * @param workersCount – number of parallel workers (default: CPU cores).
 */
export function createWorkerPool<T extends Job>(
  jobs: T[],
  workersCount?: number,
): Promise<void> {
  // Default to the number of logical CPUs if not supplied
  const count = workersCount ?? require("os").cpus().length;

  // Queue holds unresolved promises (one per job)
  const queue: Promise<any>[] = [];

  for (const job of jobs) {
    queue.push(job());
  }

  // Create worker threads that each pull a job from the shared array
  const workers = new Array<Worker>(count);
  for (let i = 0; i < count; ++i) {
    if (!isMainThread) continue; // skip on main thread

    const w: Worker = new Worker(__filename, { workerData: null });

    w.on("message", () => {});               // we don't need a result
    w.on("error", (err) => console.error(err));
    w.on("exit", (_code, _signal) => {
      if (process.env.NODE_DEBUG?.includes("worker_threads")) {
        console.log(`Worker ${w.id} exited with code ${_code}`);
      }
    });

    // When a worker exits we launch the next job from the queue
    w.on("exit", () => {
      const next = jobs.shift();
      if (next) {
        const p = next().then(() => w.postMessage(null));
        workers[i] = new Worker(__filename, { workerData: null });
        workers[i].on("message", () => {});
        // … no result handling needed
        workers[i].on("error", console.error);
        workers[i].on("exit", () => {
          if (jobs.length > 0) {
            const p = jobs.shift()!().then(() =>
              workers[i]!.postMessage(null)
            );
            workers[i] = new Worker(__filename, { workerData: null });
          }
        });
      } else {
        // All jobs finished – tell the main thread we’re done
        process.send?.({ type: "done" });
      }
    });

    workers[i] = w;
  }

  // Wait for all workers to signal that they are idle (i.e. no more work)
  const [doneSignal] = await Promise.all(
    workers.map(() => new Promise<void>((resolve) => {
      const listener = () => {
        resolve();
