#!/usr/bin/env python3
import asyncio
from typing import Callable, List, Any


async def dummy_job(i: int) -> None:
    """Placeholder async job – replace with real work."""
    await asyncio.sleep(max(0.01, 0.2 * (i % 5) / 10))


class WorkerPool:
    """
    Simple concurrent worker pool.
    - jobs: list of coroutine functions to run.
    - workers_count: number of parallel workers (default = CPU cores).
    """

    def __init__(self,
                 jobs: List[Callable[..., asyncio.Future]],
                 workers_count: int | None = None):
        self.jobs = jobs
        self.workers_count = workers_count or 4   # default fallback

    async def _run_worker(self, idx: int) -> None:
        while True:
            try:
                job = next(self.jobs)
            except StopIteration:
                return  # no more work → exit worker loop

            await job()          # run the coroutine
            self.jobs.remove(job)   # ensure it won’t be scheduled again


    async def start_workers(self) -> None:
        workers = []
        for i in range(self.workers_count):
            w = asyncio.create_task(self._run_worker(i))
            workers.append(w)

        await asyncio.gather(*workers)


async def main():
    NUM_JOBS = 30
    jobs: List[Callable[..., asyncio.Future]] = [
        dummy_job for _ in range(NUM_JOBS)
    ]

    pool = WorkerPool(jobs, workers_count=6)   # run with 6 concurrent tasks
    await pool.start_workers()
    print("✅ All jobs completed")


if __name__ == "__main__":
    import sys
    asyncio.run(main())
```

**Key points**

* `jobs` is a list of **coroutines** (async functions).  
* The constructor accepts an optional `workers_count`; if omitted it defaults to 4.  
* `_run_worker()` repeatedly pulls the next job from the shared list and runs it. When the list empties, the worker exits via `return`.  
* All workers run concurrently with `asyncio.gather`, which waits for every worker to finish before proceeding.

