// Semaphore.ts --------------------------------------------------------------
/**
 * A thread‑safe counting semaphore.
 *
 * @template T – the type returned by `acquire()`.
 */
export class Semaphore<T = void> {
  /** Number of tokens currently available. */
  private count: number;
  /** Maximum capacity (the limit). */
  private readonly max: number;

  constructor(max: number) {
    if (max <= 0) throw new Error('Semaphore capacity must be > 0');
    this.count = max;          // initially all slots are free
    this.max = max;
  }

  /**
   * Acquire a slot.
   *
   * @returns A promise that resolves to the acquired token when successful,
   *          or rejects with `Error('Semaphore: full')` if no slot is available.
   */
  async acquire(): Promise<T> {
    while (true) {
      // Try‑acquire without blocking – spin until we get a free slot
      const wasFree = this.count > 0;
      await new Promise<void>((resolve, reject) => {
        const resolveAcquired = () => resolve(this as unknown as T);
        const rejectFull    = (err: Error) => reject(err);

        // If the semaphore is not full we acquire immediately
        if (wasFree) {
          this.count -= 1;
          resolveAcquired();
        } else {
          // Otherwise wait until a slot becomes free.
          // This loop checks periodically so other threads can release tokens.
          const timeout = setTimeout(() => {
            rejectFull(new Error('Semaphore: full'));
          }, 10);   // short poll interval

          process.nextTick(() => {
            clearTimeout(timeout);
            if (this.count > 0) {
              this.count -= 1;
              resolveAcquired();
            }
          });
        }
      });
    }
  }

  /**
   * Release a slot back to the semaphore.
   */
  release(): void {
    this.count += 1; // increase count, may unblock waiting acquire()
  }
}
```

