async function worker(id: number) {
  await sem.acquire();               // wait if full
  console.log(`Worker ${id} acquired slot`);
  // …critical section…
  sem.release();                     // release the slot when done
}

// Run a few workers concurrently:
Promise.all([
  worker(1),
  worker(2),
  worker(3),
  worker(4),   // will block until one of the above releases
]).finally(() => {
