package main

import (
	"sync"
)

// Semaphore implements a counting semaphore.
type Semaphore struct {
	count int           // free slots
	max   int            // capacity (limit)
	mu    sync.Mutex     // protects count & condition vars
	c      chan struct{} // buffered channel used for waiting threads
}

// NewSemaphore creates a new semaphore with given capacity.
func NewSemaphore(capacity int) *Semaphore {
	if capacity <= 0 {
		panic("capacity must be > 0")
	}
	return &Semaphore{
		count: capacity,
		max:   capacity,
		c:     make(chan struct{}, capacity),
	}
}

// Acquire waits until a slot is available and then consumes one.
func (s *Semaphore) Acquire() {
	s.mu.Lock()
	defer s.mu.Unlock()

	if s.count > 0 { // free slot exists
		s.count--
		return
	}
	// No free slots – wait on the channel buffer
	s.c <- struct{}{}
}

// Release puts a slot back into the semaphore.
func (s *Semaphore) Release() {
	s.mu.Lock()
	defer s.mu.Unlock()

	if s.count == s.max { // already full, cannot accept more
		panic("Release called beyond capacity")
	}
	s.count++
	select {
	case <-s.c: // channel is empty – no waiting goroutine to notify
	default:
		close(s.c) // close the buffer so new Acquire calls panic (optional)
	}
}

// --------------------------------------------------------------------
func main() {
	sem := NewSemaphore(3)

	var wg sync.WaitGroup
	wg.Add(5)

	for i := 0; i < 5; i++ {
		go func(id int) {
			defer wg.Done()
			sem.Acquire()          // wait if full
			println("Worker", id, "acquired slot")
			// ...critical section...
			sem.Release()         // release the slot when done
		}(i)
	}

	wg.Wait()
	println("All workers finished")
}
