// pipeline.ts
import { v4 as uuidv4 } from 'uuid';

type Item = {
  id: number;
  data: string;
};

function newItem(id: number, data: string): Item {
  return { id, data };
}

/* --------------------------------------------------------------
   Stage A – Producer (writes to a shared channel)
   ------------------------------------------------------------ */
let incomingChannel: Array<Item> | undefined; // simple in‑memory buffer for demo
const batchSize = 10;

function producer(): void {
  for (let i = 1; i <= batchSize; i++) {
    const item = newItem(i, `payload-${i}`);
    console.log(`[A] Produced →`, item);
    incomingChannel?.push(item); // push into shared buffer
  }
}

/* --------------------------------------------------------------
   Stage B – Transformer (reads from the same channel)
   ------------------------------------------------------------ */
function transformer(): void {
  while (incomingChannel && incomingChannel.length > 0) {
    const item = incomingChannel.shift() as Item;
    console.log(`[B] Transforming →`, item);
    // Example: double the ID and append a suffix
    const transformed = newItem(item.id * 2, `${item.data} (transformed)`);
    outgoingChannel.push(transformed); // push to next channel
  }
}

/* --------------------------------------------------------------
   Stage C – Consumer (reads from the final channel)
   ------------------------------------------------------------ */
const outgoingChannel: Array<Item> = [];

function consumer(): void {
  while (outgoingChannel.length > 0) {
    const item = outgoingChannel.shift() as Item;
    console.log(`[C] Consumed →`, item);
  }
}

/* --------------------------------------------------------------
   Main driver
   ------------------------------------------------------------ */
(async () => {
  // Initialise the shared buffer for Stage A → B
  incomingChannel = [];

  // Run each stage in its own “goroutine”‑like async function.
  await Promise.all([
    new Promise<void>((resolve) => {
      // Simulate parallel execution (no true goroutines, just concurrency)
      setTimeout(() => producer(), Math.random() * 200);
    }),
    new Promise<void>((resolve) => {
      setTimeout(() => transformer(), Math.random() * 300);
    }),
    new Promise<void>((resolve) => {
      setTimeout(() => consumer(), Math.random() * 400);
    }),
  ]);

  console.log('All stages finished.');
})();
```

### How the TypeScript pipeline mirrors Go  

| Concept | Go (`chan`) | TS (in‑memory buffer + async coordination) |
|---------|-------------|--------------------------------------------|
| **Producer** | `outc <- item` | `producer()` pushes items into a shared array (`incomingChannel`). |
| **Transformer** | `item := <-inc` then forward | Loop over the same buffer, transform each entry and push to `outgoingChannel`. |
| **Consumer**   | `item := <-outc` | While loop reads from `outgoingChannel` and prints. |

*Because JavaScript/TypeScript lacks true channels, we emulate them with a shared mutable array (`incomingChannel`) that both the producer and transformer read/write concurrently.*  

