Below are three self‑contained implementations of **Floyd’s Cycle‑Finding Algorithm** (the “tortoise‑and‑hare” method) that detect whether a singly‑linked list contains a cycle.

---

## 1️⃣ TypeScript  

```ts
// Definition for singly-linked list node.
class ListNode<T> {
    val: T;
    next: ListNode<T> | null;

    constructor(val?: T, next?: ListNode<T>) {
        this.val = val ?? undefined;
        this.next = next ?? null;
    }
}

/**
 * Returns true if the linked list contains a cycle,
 * otherwise false. Uses Floyd’s Tortoise‑and‑Hare algorithm.
 *
 * Time  : O(n)
 * Space : O(1)
 */
function hasCycle<T>(head: ListNode<T> | null): boolean {
    // Edge case – empty list or single node (no possible cycle)
    if (!head || !head.next) return false;

    let slow = head;          // moves one step at a time
    let fast = head.next;     // moves two steps at a time

    while (fast && fast.next) {
        if (slow === fast) {               // meeting point → cycle detected
            return true;
        }
        slow = slow!.next;                 // 1 hop for slow
        fast = fast!.next!.next;           // 2 hops for fast
    }

    // When loop exits, either fast reached end or hit a null next.
    return false;
}

// -------------------------------------------------------------------
// Example usage (TypeScript / Node)
if (require.main === module) {
    const node5 = new ListNode(5);
    const node4 = new ListNode(4, node5);
    const node3 = new ListNode(3, node4);
    // create a cycle: 5 -> 2
    node5.next = node3;               // link tail back to middle

    console.log(hasCycle(node3));     // → true
}
```

