package main

// Definition for singly-linked list node.
type ListNode struct {
	Val  int
	Next *ListNode
}

/**
 * Returns true if the linked list contains a cycle,
 * otherwise false. Implements Floyd’s Tortoise‑and‑Hare algorithm.
 *
 * Time  : O(n)
 * Space : O(1)
 */
func hasCycle(head *ListNode) bool {
	if head == nil || head.Next == nil {
		return false
	}

	slow, fast := head, head.Next

	for fast != nil && fast.Next != nil {
		if slow == fast { // meeting point → cycle detected
			return true
		}
		slow = slow.Next           // 1 hop for slow
		fast = fast.Next.Next      // 2 hops for fast
	}

	return false
}

// -------------------------------------------------------------------
// Example usage (main)
func main() {
	// Build a list: 3 -> 2 -> 0 -> -4, with a cycle back to node at index 1 (-4 → 2)
	nodeA := &ListNode{Val: 3}
	nodeB := &ListNode{Val: 2, Next: nodeA}   // head points to nodeA (index 1)
	nodeC := &ListNode{Val: 0}
	nodeD := &ListNode{Val: -4}

	// Connect tail (-4) back to create a cycle
	nodeD.Next = nodeB

	if hasCycle(nodeA) {
		println("Cycle detected")
	} else {
		println("No cycle")
	}
}
```

