import WebSocket from 'ws';

/**
 * Simple WebSocket client that:
 * • connects to a server,
 * • sends a message,
 * • prints every incoming response.
 */
async function runClient() {
  // -----------------------------------------------------------------
  // Configuration – change these values for your own endpoint
  const WSS_URL = 'wss://echo.websocket.org';   // Echo service (good for testing)
  const SEND_MESSAGE = '{"type":"ping","seq":1}';

  try {
    // Create a new WebSocket instance
    const ws = new WebSocket(WSS_URL);

    console.log(`🔗 Connecting to ${WSS_URL}`);
    ws.on('open', () => {
      console.log('✅ Connected – sending message…');
      ws.send(SEND_MESSAGE);
    });

    // Handle incoming messages (responses)
    ws.on('message', (data: string) => {
      console.log(`📥 Received response:`);
      console.log(data.trim());
    });

    // Optional: clean‑up listeners & close on SIGINT
    const cleanup = () => {
      console.log('\n⚠️  Closing WebSocket…');
      ws.close();
    };
    process.on('SIGINT', cleanup);
    process.on('beforeExit', cleanup);

  } catch (err) {
    // Unexpected error – log and exit
    console.error('❌ WebSocket error:', err);
  }
}

// Run the client when executed directly
if (require.main === module) {
  runClient();
}
