// file: redis-demo.ts

import { createClient, Redis } from "ioredis";

/**
 * Connect to Redis, set a key with TTL, then get it back.
 *
 * @param host   Redis hostname or URL (default: localhost)
 * @param port   Redis port (default: 6379)
 */
async function redisDemo(host = "127.0.0.1", port = 6379) {
  // Create a client – ioredis supports TLS, password auth, sentinel etc.
  const client = createClient({ host, port });

  try {
    await client.connect();

    console.log("✅ Connected to Redis");

    // -----------------------------------------------------------------
    // SET key with TTL (seconds)
    // -----------------------------------------------------------------
    const key = "demoKey";
    const value = "Hello from TypeScript!";
    const ttlSeconds = 30;          // set a 30‑second expiration

    await client.set(key, value);
    await client.expire(key, ttlSeconds);

    console.log(`🔑 Set "${key}" → ${value} (TTL: ${ttlSeconds}s)`);

    // -----------------------------------------------------------------
    // GET the same key
    // -----------------------------------------------------------------
    const retrieved = await client.get(key);
    if (retrieved) {
      console.log(`✅ Retrieved value:`, retrieved);
    } else {
      console.warn("⚠️  Key not found after setting TTL");
    }

  } catch (err) {
    console.error("❌ Redis error:", err);
  } finally {
    // Always disconnect to free resources
    await client.quit();
  }
}

// Run the demo when executed directly
if (require.main === module) {
  redisDemo().catch(console.error);
}
