)

func redisDemo(ctx context.Context, host string, port int,
	key string, value string, ttlSeconds int) {

	client := redis.NewClient(&redis.Options{
		Addr:     fmt.Sprintf("%s:%d", host, port),
		PoolSize: 10,
	})

	err := client.Ping(ctx).Err()
	if err != nil {
		log.Fatalf("❌ Redis connection error: %v", err)
	}
	fmt.Println("✅ Connected to Redis")

	// -----------------------------------------------------------------
	// SET key with TTL (seconds)
	// -----------------------------------------------------------------
	err = client.Set(ctx, key, value, time.Duration(ttlSeconds)*time.Second).Err()
	if err != nil {
		log.Fatalf("❌ Set failed: %v", err)
	}
	fmt.Printf("🔑 Set \"%s\" → %q (TTL: %d)s\n", key, value, ttlSeconds)

	// Simulate TTL expiration
	time.Sleep(time.Duration(ttlSeconds+1) * time.Second)

	// -----------------------------------------------------------------
	// GET the same key
	// -----------------------------------------------------------------
	val := client.Get(ctx, key)
	if val.Err() != nil {
		fmt.Println("⚠️  Key not found after TTL expired")
		return
	}

	retrievedValue, _ := val.Result()
	fmt.Printf("✅ Retrieved value: %s\n", retrievedValue)
}

func main() {
	ctx := context.Background()

	host := "127.0.0.1"
	port := 6379
	key := "demoKeyGo"
	value := "Hello from Go!"
	ttlSeconds := 30

	redisDemo(ctx, host, port, key, value, ttlSeconds)
}
