// circuitBreaker.ts ---------------------------------------------------------
/**
 * A simple in‑memory circuit breaker.
 *
 * • `failureThreshold` – number of consecutive failures before opening the circuit.
 * • `resetTimeoutMs`   – how long (in ms) to stay open after opening.
 * • `maxConsecutiveSuccesses` – optional safety guard: once this many successes are seen
 *                               while the breaker is closed, it will immediately accept a call,
 *                               preventing an instant “re‑open” spike.
 *
 * The breaker exposes two public methods:
 *   - `call(fn)`          → runs the supplied function; returns its result or throws.
 *   - `isOpen(): boolean`→ true when the circuit is OPEN (rejects all calls).
 */
export class CircuitBreaker {
  private failures: number = 0;
  private lastFailureTime?: Date;
  private resetTimeoutMs: number;
  private maxConsecutiveSuccesses?: number; // optional safety guard
  private consecutiveSuccesses = 0;

  constructor({
    failureThreshold,
    resetTimeoutMs,
    maxConsecutiveSuccesses = undefined, // defaults to disabled
  }: {
    failureThreshold: number;
    resetTimeoutMs: number;
    maxConsecutiveSuccesses?: number; // optional
  }) {
    this.failureThreshold = failureThreshold;
    this.resetTimeoutMs = resetTimeoutMs;
    if (maxConsecutiveSuccesses !== undefined) {
      this.maxConsecutiveSuccesses = maxConsecutiveSuccesses;
    }
  }

  /** Returns true when the breaker is OPEN – i.e. all calls are rejected */
  public isOpen(): boolean {
    // Circuit stays open while:
    //   - resetTimeout has not elapsed, OR
    //   - we have not yet seen enough successes to “close” it (if guard enabled)
    if (!this.maxConsecutiveSuccesses) return this.lastFailureTime && Date.now() < this.lastFailureTime.getTime()
      + this.resetTimeoutMs;
    const now = Date.now();
    if (this.lastFailureTime && now - this.lastFailureTime.getTime() >= this.resetTimeoutMs) {
      // timeout elapsed → start counting successes
      let successSinceReset =
        now -
        (this.lastFailureTime ? this.lastFailureTime.getTime() : 0);
      // Count only consecutive successes after reset:
      if (successSinceReset > 0) {
        const sinceLastSuccess = now - (this.lastFailureTime?.getTime() ?? now);
        // If the gap between last failure and current call is larger than any previous success streak,
        // we treat it as a fresh streak starting from this call.
        // For simplicity, just keep the counter updated each time we succeed:
        this.consecutiveSuccesses++;
      } else {
        this.consecutiveSuccesses = 1;
      }
      return this.consecutiveSuccesses < this.maxConsecutiveSuccesses;
    }
    return false; // closed
  }

  /**
   * Attempts to run `fn`. If it succeeds, resets the failure counter and returns its result.
   * On error:
   *   - if still CLOSED → throw / re‑throw (or wrap in a custom error).
   *   - if OPEN → do NOT increment failures; simply return an error wrapper.
   */
  public call<T>(fn: () => T): T {
    // Guard against calling while already open and no success guard
    if (this.isOpen()) {
      throw new Error('Circuit is OPEN – all calls are rejected');
    }

    try {
      const result = fn();
      // Success → reset counters
      this.resetSuccessCounters();
      return result;
    } catch (err) {
      // Failure handling -------------------------------------------------
      this.recordFailure();

      if (this.isOpen()) {
        // Already open: we ignore failures and just keep the circuit closed.
        throw err; // or wrap in a custom CircuitError, etc.
      }

      // Still CLOSED → increment failure count
      this.failures += 1;
      const now = new Date();
      this.lastFailureTime = now;

      if (this.failures >= this.failureThreshold) {
        console.warn(
          `[CircuitBreaker] Failure threshold (${this.failureThreshold}) reached – opening circuit for ${this.resetTimeoutMs} ms`
        );
        // Circuit is OPEN; optionally you could store the timestamp of opening.
      }

      // If we have a success guard, check if enough successes have accumulated
      if (this.maxConsecutiveSuccesses && this.consecutiveSuccesses >= this.maxConsecutiveSuccesses) {
        console.log(
          `[CircuitBreaker] Success streak reached ${this.maxConsecutiveSuccesses} – closing circuit`
        );
        // Immediately close the breaker so calls can resume.
        this.resetSuccessCounters();
