# circuit_breaker.py ---------------------------------------------------------
import time
from datetime import datetime, timedelta

class CircuitBreaker:
    """
    Simple in‑memory circuit breaker.

    Parameters
    ----------
    failure_threshold : int
        Number of consecutive failures before opening the circuit.
    reset_timeout_seconds : int or float
        How long (in seconds) to stay open after opening.
    max_consecutive_successes : Optional[int]
        If set, once this many successes are seen while closed,
        the breaker automatically closes itself – useful for preventing
        an immediate “re‑open” spike.

    Usage pattern:
        cb = CircuitBreaker(failure_threshold=5, reset_timeout_seconds=30)
        try:
            result = cb.call(lambda: expensive_operation())
        except Exception as e:
            # handle failure or re‑raise
    """

    def __init__(
        self,
        *,
        failure_threshold: int = 5,
        reset_timeout_seconds: float = 30.0,
        max_consecutive_successes: int | None = None,
    ):
        self.failure_threshold = failure_threshold
        self.reset_timeout_seconds = reset_timeout_seconds

        # optional guard – counts successes after the circuit opens.
        if max_consecutive_successes is not None:
            self.max_consecutive_successes = max_consecutive_successes
        else:
            self.max_consecutive_successes = None

        self._closed = True               # internal state flag
        self._failure_count = 0           # consecutive failures since last success
        self._last_failure_ts: datetime | None = None
        self._success_streak = 0          # used only when max_consecutive_successes is set

    def call(self, fn):
        """
        Attempt to run `fn`. Returns its result on success; raises any exception otherwise.
        If the breaker is OPEN it immediately raises a custom error (or you can wrap in your own).
        """
        if self._is_open():
            raise RuntimeError("Circuit is OPEN – all calls are rejected")

        try:
            result = fn()
            # ---- Success -------------------------------------------------
            self._reset_success_streak()          # clear streak counter
            return result
        except Exception as exc:                 # ---- Failure -----------------
            self._record_failure()

            if self._is_open():
                # Already open – stay closed; optionally you could raise a custom error.
                raise RuntimeError("Circuit is OPEN") from exc

            # Still CLOSED → bump failure counter
            self._failure_count += 1
            self._last_failure_ts = datetime.now()

            # Check if we have hit the threshold to open the circuit
            if self._failure_count >= self.failure_threshold:
                print(
                    f"[CircuitBreaker] Failure threshold ({self.failure_threshold}) reached – opening circuit for {self.reset_timeout_seconds}s"
                )
                self._closed = False          # OPEN state

            # Optional success‑streak guard (only enabled)
            if (
                self.max_consecutive_successes is not None
                and self._success_streak >= self.max_consecutive_successes
            ):
                print(
                    f"[CircuitBreaker] Success streak ({self.max_consecutive_successes}) reached – closing circuit"
                )
                self._reset()                 # close immediately

            raise exc                         # re‑raise or convert to custom error as needed

    def _is_open(self) -> bool:
        """Returns True when the breaker is OPEN."""
        if not self._closed:
            now = datetime.now()
            timeout_exceeded = (self._last_failure_ts
                                and now >= self._last_failure_ts + timedelta(seconds=self.reset_timeout_seconds))
                # If reset window passed, start counting successes.
                success_since_reset = (
                    now - (self._last_failure_ts if self._last_failure_ts else datetime.min)
                ).total_seconds()
                # When the timeout is over we begin accumulating successes:
                return not timeout_exceeded or self._success_streak < self.max_consecutive_successes
        return True  # default: closed

    def _reset(self):
        """Close the breaker immediately (after reset window)."""
        self._closed = True
        self._failure_count = 0
        self._last_failure_ts = None
        self._success_streak = 0

    def _record_failure(self):
        now = datetime.now()
        self._last_failure_ts = now
        # Optional: store timestamp for later analysis.
