// bloom-filter.ts ---------------------------------------------------------

/**
 * A simple, configurable Bloom filter.
 *
 * @template T - The type of items stored in the filter (must be string‑ish).
 */
export class BloomFilter<T> {
    /** Number of bits in the underlying bit array. */
    private readonly size: number;
    /** Number of hash functions used. */
    private readonly k: number;

    /** Bit array – each entry is a single byte so we can set/clear individual bits cheaply. */
    private readonly bits: Uint8Array;

    /**
     * @param expectedItems  Expected maximum cardinality (used to compute optimal `k`).
     * @param fpRate         Desired false‑positive probability (e.g., 0.01 for 1%).
     */
    constructor(
        public readonly expectedItems: number,
        private readonly fpRate: number = 0.01, // default ≈ 1%
    ) {
        // Optimal k given p and m is:
        //   k = - (m / n) * ln(p)
        // where n = expectedItems.
        const optimalK = Math.ceil(-Math.log(fpRate) * (expectedItems / 0.6931471805599453));
        this.size    = BloomFilter._bitsNeeded(expectedItems, fpRate);
        this.k       = optimalK;
        this.bits    = new Uint8Array(this.size); // all zero bits initially
    }

    /** Add an item to the filter. */
    add(item: T): void {
        const hashes = BloomFilter.hashAll(item, this.k);
        for (const h of hashes) {
            const idx = h % this.size;
            this.bits[idx] |= 1; // set bit to 1
        }
    }

    /** Test membership. Returns true if *maybe* present, false otherwise. */
    has(item: T): boolean {
        const hashes = BloomFilter.hashAll(item, this.k);
        for (const h of hashes) {
            const idx = h % this.size;
            if ((this.bits[idx] & 1) === 0) return false; // bit not set → definitely absent
        }
        return true; // all bits were seen as set
    }

    /** Serialize the filter to a JSON‑friendly object (size + base64‑encoded bits). */
    toJSON(): { size: number; k: number; bitsBase64: string } {
        const b64 = Buffer.from(this.bits.buffer, 'binary').toString('base64');
        return { size: this.size, k: this.k, bitsBase64: b64 };
    }

    /** Re‑create a filter from its JSON representation. */
    static fromJSON(json: { size: number; k: number; bitsBase64: string }): BloomFilter<any> {
        const bits = Buffer.from(Buffer.from(json.bitsBase64, 'base64'), 'base64').buffer;
        return new BloomFilter<any>(json.size, json.k, new Uint8Array(bits));
    }

    /** Private helper – compute optimal m (bits) for given n and p. */
    private static _bitsNeeded(n: number, p: number): number {
        // m = -n * ln(p) / (ln(2)^2)
        return Math.ceil(-n * Math.log(p) / (Math.log(2) ** 2));
    }

    /** Private helper – generate k independent hash values for an item. */
    private static hashAll(item: T, numHashes: number): Int32Array {
        const hashes = new Int32Array(numHashes);
        // Use Murmur3‑compatible 32‑bit mixing (simple but fast)
        const seed = 0x811c9dc5;
        for (let i = 0; i < numHashes; ++i) {
            let h = MurmurHash3.hash(item, seed + i * 31);
            // Ensure positive and within range [0, size‑1]
            hashes[i] = ((h >>> 0) % this.size);
        }
        return hashes;
    }

    /** Simple Murmur3 implementation (32‑bit). */
    private static hash(s: T, seed: number): number {
        const str = String(s);
        let h   = seed;
        for (const c of str) {
            h ^= c.charCodeAt(0);
            h *= 16777619; // prime
        }
        return ((h >>> 0) & 0xffffffff); // force unsigned 32‑bit
    }
}

