  ## 2️⃣ Python implementation  
  
  ```python
  # bloom_filter.py ---------------------------------------------------------
  
  import math
  import json
  from typing import Any
  
  try:
      import murmur3   # pip install murmur3
  except ImportError:
      # Fallback pure‑Python Murmur3 (slower) – only for demonstration.
      def murmur3_hash(s: str, seed: int = 0) -> int:
          h = seed
          for c in s.encode('utf-8'):
              h ^= ord(c)
              h *= 16777619
          return ((h >> 0) & 0xffffffff)
  
  def _bits_needed(n: int, p: float) -> int:
      """Return optimal number of bits (m)."""
      # m = -n * ln(p) / (ln2^2)
      return math.ceil(-n * math.log(p) / (math.log(2) ** 2))
  
  def _hashes(item: Any, k: int, size: int) -> list[int]:
      """Generate `k` independent hash values in [0, size)."""
      hashes = []
      for i in range(k):
          h = murmur3_hash(str(item), seed=31 + i * 31)
          # Murmur returns signed; force unsigned and mod size
          idx = ((h >> 0) % (2**32)) % size
          hashes.append(idx)
      return hashes
  
  class BloomFilter:
      """
      A configurable Bloom filter.
  
      Parameters
      ----------
      expected_items : int
          Anticipated maximum number of elements.
      fp_rate : float, optional
          Desired false‑positive probability (default 0.01 → ~1%).
      """
  
      def __init__(self, expected_items: int, fp_rate: float = 0.01):
          self.size: int = _bits_needed(expected_items, fp_rate)
          self.k: int = math.ceil(-math.log(fp_rate) * (expected_items / 0.6931471805599453))
          # Use a bytearray for cheap bit ops; each byte holds one bit.
          self.bits: bytearray = bytearray(self.size)
  
      def add(self, item: Any) -> None:
          """Insert an element."""
          for h in _hashes(item, self.k, self.size):
              idx = h % self.size
              # Set the least‑significant bit to 1 (true)
              self.bits[idx] |= 1
  
      def has(self, item: Any) -> bool:
          """Test membership. Returns True if *maybe* present."""
          for h in _hashes(item, self.k, self.size):
              idx = h % self.size
              if not (self.bits[idx] & 1):   # bit == 0 → definitely absent
                  return False
          return True
  
      def to_json(self) -> dict:
          """Serialize filter for storage."""
          b64_bits = base64.b64encode(self.bits).decode('utf-8')
          return {
              "size": self.size,
              "k": self.k,
              "bitsBase64": b64_bits
          }
  
      @classmethod
      def from_json(cls, data: dict) -> 'BloomFilter':
          """Recreate a filter from its JSON representation."""
          bits = base64.b64decode(data["bitsBase64"])
          return cls(data["size"], data["k"], bytearray(bits))
  
  # ----------------------------------------------------------------------
  # Example usage -----------------------------------------------------------
  
  if __name__ == "__main__":
      import base64
      # Create a filter that tolerates ~0.1 % false positives for 100 000 items.
      bf = BloomFilter(expected_items=100_000, fp_rate=0.001)
  
      for word in ["apple", "banana", "orange"]:
          bf.add(word)
  
      print("exists 'apple'   →", bf.has("apple"))   # True
      print("exists 'grape'  →", bf.has("grape"))   # False (maybe)
  
      # Persist / share the filter:
      data = bf.to_json()
      with open("filter.json", "w") as f:
          json.dump(data, f, indent=2)
  ```
  
