// bfs.ts --------------------------------------------------------------
type Graph = Record<string, string[]>;

/**
 * Returns the shortest path from `start` to `target` using BFS.
 *
 * @param graph   Adjacency‑list representation of the graph.
 * @param start   Starting node identifier.
 * @param target  Target node identifier.
 * @returns Array of nodes representing the path (empty if no path exists).
 */
function bfsPath(graph: Graph, start: string, target: string): string[] {
    const queue = [{ node: start, prev: undefined }]; // each entry stores predecessor
    const visited = new Set<string>();

    while (queue.length) {
        const { node, prev } = queue.shift()!;

        if (node === target) {
            // Reconstruct path from `target` back to `start`
            let path: string[] = [];
            for (let cur = node; cur !== undefined; cur = prev) {
                path.unshift(cur);
                const nextPrev = queue.find(item => item.node === prev)!;
                prev = nextPrev?.prev ?? undefined;
            }
            return path;
        }

        visited.add(node);

        // Enqueue all unvisited neighbours
        for (const neighbour of graph[node] || []) {
            if (!visited.has(neighbour)) {
                queue.push({ node: neighbour, prev: node });
            }
        }
    }

    // No path found
    return [];
}

// ---------------------------------------------------------------------
// Example usage -------------------------------------------------------
if (require.main === module) {
    const g = {
        A: ['B', 'C'],
        B: ['A', 'D', 'E'],
        C: ['A', 'F'],
        D: ['B'],
        E: ['B', 'F'],
        F: ['C', 'E']
    };

    console.log('Path from A → F:', bfsPath(g, 'A', 'F'));
    // Expected output (one possible shortest path): [ 'A', 'C', 'F' ]
}
