// bfs.go --------------------------------------------------------------
package main

import (
	"fmt"
	"container/list"
)

type Graph map[string][]string

func BFSPath(graph Graph, start string, target string) []string {
	queue := list.New()
	type entry struct{ node string; prev *entry }
	q := make([]entry, 0, len(graph))
	startEntry := &entry{node: start}
	if graph[start] != nil {
		for _, nei := range graph[start] {
			q = append(q, entry{nei, startEntry})
		}
	} else {
		return []string{} // node not present
	}

	queue.PushBack(startEntry)

	visited := make(map[string]bool)
	for qLen := queue.Len(); qLen > 0; qLen = queue.Len() {
		cur := queue.Remove(queue.Front()).(*entry)
		if cur.node == target {
			// Reconstruct path backwards
			path := []string{}
			for e := cur; e != nil; e = e.prev {
				path = append([]string{e.node}, path...)
			}
			return path
		}

		visited[cur.node] = true

		for _, nei := range graph[cur.node] {
			if !visited[nei] {
				queue.PushBack(&entry{node: nei, prev: cur})
			}
		}
	}

	return []string{} // no path found
}

func main() {
	g := map[string][]string{
		"A": {"B", "C"},
		"B": {"A", "D", "E"},
		"C": {"A", "F"},
		"D": {"B"},
		"E": {"B", "F"},
		"F": {"C", "E"},
	}

	path := BFSPath(g, "A", "F")
	fmt.Printf("Path from A → F: %v\n", path) // e.g. [A C F]
}
