## TypeScript (ES6+)

```ts
/**
 * Topological sort using Kahn's algorithm.
 *
 * @template T - type of node identifiers (e.g., string, number)
 * @param {Map<T, Set<T>>} graph  Adjacency list: key = source node,
 *                                value = set of destination nodes it points to.
 * @returns {T[]}                A topologically sorted order if the graph is a DAG;
 *                                throws an Error otherwise (cycle detected).
 */
export function topoSort<T>(graph: Map<T, Set<T>>): T[] {
  // 1️⃣ Compute indegrees
  const indegree = new Map<T, number>();
  for (const [node] of graph) {
    indegree.set(node, 0);
  }
  for (const adjSet of graph.values()) {
    for (const dest of adjSet) {
      indegree.set(dest, (indegree.get(dest) ?? 0) + 1);
    }
  }

  // Collect all nodes with zero incoming edges
  const queue = new Array<T>();
  for (const [node] of indegree.entries()) {
    if (indegree.get(node)! === 0) {
      queue.push(node);
    }
  }

  const result: T[] = [];

  while (queue.length > 0) {
    const node = queue.shift()!;
    result.push(node);

    // Decrement neighbours' indegrees
    for (const neighbour of graph.get(node) ?? []) {
      const cur = indegree.get(neighbour)!;
      if (cur === 1) {               // exactly one incoming edge left → enqueue when it hits 0
        queue.push(neighbour);
      }
      indegree.set(neighbour, cur - 1);
    }
  }

  // If we didn't process all nodes, there is a cycle.
  if (result.length !== graph.size) {
    throw new Error('Cycle detected – topological sort not possible.');
  }

  return result;
}

