    for adj_set in graph.values():
        for v in adj_set:
            indegree[v] = indegree.get(v, 0) + 1

    # Enqueue all nodes with zero incoming edges
    queue = deque([u for u, deg in indegree.items() if deg == 0])
    result: List[T] = []

    while queue:
        node = queue.popleft()
        result.append(node)

        # Decrement neighbours' indegrees
        for neighbour in graph.get(node, []):
            indegree[neighbour] -= 1
            if indegree[neighbour] == 0:
                queue.append(neighbour)

    if len(result) != len(graph):
        raise ValueError("Cycle detected – topological sort not possible.")
    
    return result


