// TopologicalSort returns a slice representing a topological ordering of the DAG.
// If the input contains a cycle, it panics with an error message.
func TopologicalSort(graph map[string]map[string]bool) []string {
	indeg := make(map[string]int)
	for u := range graph {
		indeg[u] = 0
	}
	for u, adj := range graph {
		for v := range adj {
			indeg[v]++
		}
	}

	q := []string{}
	for node, deg := range indeg {
		if deg == 0 {
			q = append(q, node)
		}
	}

	var result []string
	for len(q) > 0 {
		u := q[0]
		q = q[1:]
		result = append(result, u)

		for v := range graph[u] { // iterate over neighbours of u
			indeg[v]--
			if indeg[v] == 0 {
				q = append(q, v)
			}
		}
	}

	if len(result) != len(graph) {
		panic("Cycle detected – topological sort not possible")
	}
	return result
}

