## 1️⃣ TypeScript (Node.js / Browser)

```ts
// MessageQueue.ts ---------------------------------------------------------
export class MessageQueue<T> {
    private readonly items: T[] = [];
    // A single mutex protects both enqueue & dequeue operations.
    private readonly lock = new Lock();   // simple spin‑lock implementation

    /** Add an item to the back of the queue. */
    public enqueue(item: T): void {
        this.lock.runExclusive(() => {
            this.items.push(item);
        });
    }

    /**
     * Remove and return the front item.
     * Throws if the queue is empty.
     */
    public dequeue(): T {
        const result = this.peek();
        if (result === undefined) {
            throw new Error('Cannot dequeue from an empty queue');
        }
        this.lock.runExclusive(() => {
            // shift removes the first element – O(n) but acceptable for a simple demo
            return this.items.shift() as T;
        });
    }

    /** Return the front item without removing it. */
    public peek(): T | undefined {
        const result = this.lock.runExclusive(() => {
            return this.items[0];
        });
        // runExclusive returns `undefined` if lock is held by another thread,
        // but because we always acquire the lock before returning, we can safely
        // read items[0] directly.
        return this.items[0];
    }
}

/**
 * Very lightweight spin‑lock for demonstration purposes.
 * In production you’d use a proper synchronization primitive (e.g. `Mutex` from `ts-mutex`).
 */
class Lock {
    private locked = false;

    /** Acquire the lock; throws if already held. */
    public runExclusive<R>(fn: () => R): R | undefined {
        if (this.locked) {
            // spin until it becomes free
            while (this.locked);
        }
        this.locked = true;
        try {
            return fn();
        } finally {
            this.locked = false;
        }
    }
}
```

