  class Lock {
      private locked = false;
  
      /** Acquire the lock; throws if already held. */
      public runExclusive<R>(fn: () => R): R | undefined {
          if (this.locked) {
              // spin until it becomes free
              while (this.locked);
          }
          this.locked = true;
          try {
              return fn();
          } finally {
              this.locked = false;
          }
      }
