// PriorityQueue.ts ---------------------------------------------------------
class MinHeap<T> {
    private heap: T[] = [];

    /** Push an item onto the queue */
    push(item: T): void {
        this.heap.push(item);
        this._siftUp(this.heap.length - 1);
    }

    /** Pop and return the smallest item (root) */
    pop(): T | undefined {
        if (this.heap.length === 0) return undefined;

        // Move last element to root and then fix heap property
        const min = this.heap[0];
        const end   = this.heap.pop();

        if (this.heap.length > 0) {
            this.heap[0] = end!;
            this._siftDown(0);
        }
        return min;
    }

    /** Helper: bubble up after a push */
    private _siftUp(idx: number): void {
        while (idx > 0) {
            const parent = Math.floor((idx - 1) / 2);
            if (this.heap[parent] <= this.heap[idx]) break; // already in place
            [this.heap[parent], this.heap[idx]] = [
                this.heap[idx],
                this.heap[parent]
            ];
            idx = parent;
        }
    }

    /** Helper: bubble down after a pop */
    private _siftDown(idx: number): void {
        const size = this.heap.length;
        while (true) {
            let left  = 2 * idx + 1;
            let right = 2 * idx + 2;
            let smallest = idx;

            if (left < size && this.heap[left] < this.heap[smallest])
                smallest = left;
            if (right < size && this.heap[right] < this.heap[smallest])
                smallest = right;

            if (smallest === idx) break; // heap property satisfied
            [this.heap[idx], this.heap[smallest]] = [
                this.heap[smallest],
                this.heap[idx]
            ];
            idx = smallest;
        }
    }

    /** Peek at the root without removing it */
    peek(): T | undefined {
        return this.heap[0];
    }
}

