// Item is any comparable value.
type Item interface{}

// MinHeap holds Items and satisfies heap.Interface for a min‑heap.
type MinHeap []Item

func (h MinHeap) Len() int            { return len(h) }
func (h MinHeap) Less(i, j int) bool  { return h[i] < h[j] } // less = smaller → max‑heap
func (h MinHeap) Swap(i, j int)       { h[i], h[j] = h[j], h[i] }

// Push adds an item to the heap.
func (h *MinHeap) Push(x interface{}) {
	*h = append(*h, x.(Item))
}

// Pop removes and returns the smallest item.
func (h *MinHeap) Pop() interface{} {
	old := *h
	n := len(old)
	x := old[n-1]
	*h = old[0 : n-1]
	return x
}

// Peek returns the smallest item without removing it.
func (h MinHeap) Peek() Item { return h[0] }

