use std::cmp::Ordering;

// A generic min‑heap stored in a Vec.
struct MinHeap<T: Ord> {
    heap: Vec<T>,
}

impl<T: Ord> MinHeap<T> {
    fn new() -> Self { Self { heap: vec![] } }

    // Push an item onto the queue.
    fn push(&mut self, item: T) {
        self.heap.push(item);
        self._sift_up(self.heap.len() - 1);
    }

    // Pop and return the smallest item (root).
    fn pop(&mut self) -> Option<T> {
        if self.heap.is_empty() { None }
        else {
            let min = self.heap[0];
            let last = self.heap.pop();
            match last {
                Some(x) => {
                    if !self.heap.is_empty() {
                        self.heap[0] = x;
                        self._sift_down(0);
                    }
                    Some(min)
                }
                None => panic!("pop from empty heap"),
            }
        }
    }

    // Peek at the root without removing it.
    fn peek(&self) -> Option<&T> { self.heap.first() }

    // ----- internal helpers ------------------------------------------------
    fn _sift_up(&mut self, mut idx: usize) {
        while idx > 0 {
            let parent = (idx - 1) / 2;
            if self.heap[parent] <= self.heap[idx] {
                break; // already in place
            }
            self.heap.swap(idx, parent);
            idx = parent;
        }
    }

    fn _sift_down(&mut self, mut idx: usize) {
        let len = self.heap.len();
        while 2 * idx + 1 < len {
            let left = 2 * idx + 1;
            let right = 2 * idx + 2;
            let smallest = if right < len && self.heap[right] < self.heap[left] {
                right
            } else {
                left
            };
            if self.heap[smallest] >= self.heap[idx] {
                break; // heap property satisfied
            }
            self.heap.swap(idx, smallest);
            idx = smallest;
        }
    }
}

