      /** Helper: bubble down after a pop */
      private _siftDown(idx: number): void {
          const size = this.heap.length;
          while (true) {
              let left  = 2 * idx + 1;
              let right = 2 * idx + 2;
              let smallest = idx;
  
              if (left < size && this.heap[left] < this.heap[smallest])
                  smallest = left;
              if (right < size && this.heap[right] < this.heap[smallest])
                  smallest = right;
  
              if (smallest === idx) break; // heap property satisfied
              [this.heap[idx], this.heap[smallest]] = [
                  this.heap[smallest],
                  this.heap[idx]
              ];
              idx = smallest;
          }
      }
  
      /** Peek at the root without removing it */
      peek(): T | undefined {
          return this.heap[0];
      }
  }
  
