## 1️⃣ TypeScript (Node.js)

```ts
// src/taskScheduler.ts
import { setIntervalAsync } from "set-interval-async";

/**
 * Registers a callback to be executed periodically.
 *
 * @param name   – Identifier for this task (helps with stopping).
 * @param intervalMs – How often the callback should run, in milliseconds.
 * @param cb      – The function to call each period.
 */
export async function schedule(
  name: string,
  intervalMs: number,
  cb: () => Promise<void> | void
) {
  // Use setIntervalAsync from npm (handles clean cancellation)
  const id = await setIntervalAsync(cb, { interval: intervalMs });
  console.log(`✅ Scheduled "${name}" → runs every ${intervalMs} ms`);
}

/**
 * Stops all scheduled tasks.
 */
export async function stopAll() {
  await Promise.allSettled(tasks.values());
  tasks.clear();
  console.log("🛑 All scheduled tasks stopped.");
}
```

