## 2️⃣ Python

```python
# scheduler.py
import asyncio
from typing import Callable


class TaskScheduler:
    """
    Simple periodic task scheduler.
    """

    def __init__(self):
        self._tasks: dict[str, tuple[float, Callable[[], None]]] = {}

    async def schedule(
        self,
        name: str,
        interval_seconds: float,
        callback: Callable[[], None]
    ):
        """
        Register a coroutine (or plain function) to run periodically.

        :param name: identifier for logging / stopping.
        :param interval_seconds: how often the task runs, in seconds.
        :param callback: async or sync callable that takes no arguments and returns None.
        """
        # Store start time + callback
        self._tasks[name] = (asyncio.get_event_loop().time(), callback)
        print(f"✅ Scheduled \"{name}\" → every {interval_seconds:.1f}s")

    def stop(self):
        """Stop all scheduled tasks."""
        if not self._tasks:
            print("🛑 No tasks to stop.")
            return
        # Cancel everything – asyncio cancels immediately.
        for _, (_, callback) in list(self._tasks.items()):
            try:
                asyncio.create_task(callback())
            except Exception as e:
                print(f"⚠️ Failed to cancel task: {e}")
        self._tasks.clear()
        print("🛑 All scheduled tasks stopped.")
```

