## 3️⃣ Go

```go
// scheduler.go
package main

import (
	"context"
	"fmt"
	"log"
	"sync"
	"time"
)

type Task struct {
	Name   string
	Delay  time.Duration // interval between runs (seconds)
	Callback func()
}

// Scheduler holds registered tasks.
type Scheduler struct {
	tasks map[string]*Task
	mu    sync.Mutex
	wg    *sync.WaitGroup
	ctx   context.Context
	cancel context.CancelFunc
}

func NewScheduler() *Scheduler {
	return &Scheduler{
		tasks: make(map[string]*Task),
		wg:    &sync.WaitGroup{},
	}
}

// Schedule registers a periodic task.
func (s *Scheduler) Schedule(name string, interval time.Duration, cb func()) {
	s.mu.Lock()
	defer s.mu.Unlock()

	if _, exists := s.tasks[name]; exists {
		log.Fatalf("task %q already registered", name)
	}
	task := &Task{
		Name:   name,
		Delay:  interval,
		Callback: func() { go cb() },
	}
	s.tasks[name] = task
	fmt.Printf("✅ Scheduled \"%s\" → every %v\n", name, interval)
}

// Start begins all scheduled tasks.
func (s *Scheduler) Start(ctx context.Context) error {
	s.mu.Lock()
	tasks := make([]*Task, 0, len(s.tasks))
	for _, t := range s.tasks {
		t.wg.Add(1)
		go func(t *Task) {
			defer t.wg.Done()
			timer := time.NewTicker(t.Delay)
			defer timer.Stop()

			for {
				select {
				case <-timer.C:
					t.Callback()
				case <-s.ctx.Done():
					return
				}
			}
		}(t)
	}

	s.tasks = make(map[string]*Task) // clear map to avoid double‑add on Stop()
	s.mu.Unlock()

	s.ctx, s.cancel = context.WithCancel(context.Background())
	return nil
}

// Stop stops all scheduled tasks.
func (s *Scheduler) Stop() {
	s.mu.Lock()
	for _, t := range s.tasks {
		t.wg.Wait() // wait for each goroutine to finish its current tick
	}
	s.tasks = make(map[string]*Task)
	s.cancel()
	fmt.Println("🛑 All scheduled tasks stopped.")
}

func main() {

	// Example callbacks -------------------------------------------------
	myTask1 := func() {
		log.Printf("[GO] Task 1 ran at %s", time.Now().Format(time.RFC1123))
	}
	myTask2 := func() {
		log.Printf("[GO] Task 2 ran at %s", time.Now().Format(time.RFC1123))
	}

	sch := NewScheduler()
	err := sch.Schedule("first-task", 2*time.Second, myTask1)
	if err != nil { log.Fatal(err) }
	err = sch.Schedule("second-task", 5*time.Second, myTask2)
	if err != nil { log.Fatal(err) }

	// Start the scheduler ------------------------------------------------
	ctx, cancel := context.WithCancel(context.Background())
	defer cancel()
	if err := sch.Start(ctx); err != nil {
		log.Fatalf("failed to start scheduler: %v", err)
	}

	// Keep program alive while tasks run (Ctrl+C will trigger Stop)
	select {} // placeholder – actual stopping handled via Cancel
}
```

**How it works**

* Each registered callback is launched in its own goroutine.
* A ticker (`time.NewTicker`) drives the loop; when the timer fires, the stored function runs inside a `select` that also listens for a cancellation signal.
* The scheduler stores tasks in a map and later clears them during `Stop()`. All goroutines are waited on with their `sync.WaitGroup`.
* Stopping is performed by calling `context.CancelFunc`, which immediately stops new ticker ticks; existing ones finish their current iteration before exiting.

