/**
 * Returns the next execution timestamp for an ISO‑8601 cron expression.
 *
 * Supported fields:
 *   minute    : 0-59
 *   hour      : 0-23
 *   day       : 1-31 (month‑dependent)
 *   month     : 1-12 or JAN‑DEC
 *   weekday   : 0-6 (Sun=0) or SUN-SAT
 *
 * The expression may contain ranges, step values and lists.
 *
 * @param cron - ISO‑8601 cron string (e.g. "0 12 * * *")
 * @returns Date – the next run time after now (or null if already past)
 */
export function getNextRun(cron: string): Date | null {
  const now = new Date();

  // Parse each field
  const fields = cron.split(' ');
  if (fields.length !== 5) throw new Error(`Invalid cron format`);

  const [min, hour, dayOfMonth, month, weekday] = fields;

  // Helper: parse a single value or list/range/step into an array of numbers
  function parseField(value: string): number[] {
    if (value === '*') return Array.from({ length: 60 }, (_, i) => i);
    const parts = value.split('/');
    let step = 1;
    if (parts.length > 1 && /^\d+$/.test(parts[0])) {
      step = parseInt(parts[0], 10);
      parts = parts[1].split('-');
    }
    const minmax = parts.map(p => p.includes('-') ? p.split('-').map(Number) : Number(p));
    if (minmax.length === 2 && Array.isArray(minmax[0]) && Array.isArray(minmax[1])) {
      // range: start-end
      return [...Array(minmax[1] - minmax[0] + 1)].map((_, i) => minmax[0] + i);
    }
    if (minmax.length === 2 && typeof minmax[0] === 'number' && typeof minmax[1] === 'number') {
      // single range: start-end
      return [...Array(minmax[1] - minmax[0] + 1)].map((_, i) => minmax[0] + i);
    }
    const numbers = minmax.map(p =>
      p.includes('-')
        ? Array.from({ length: p.split('-')[1]! - p.split('-')[0]! + 1 })
            .map((_, i) => parseInt(p.split('-')[0], 10) + i)
        : parseInt(p, 10));
    return numbers.flat();
  }

  const minute   = parseField(min);
  const hour     = parseField(hour);
  const dom      = parseField(dayOfMonth); // day of month
  const month    = parseField(month);      // month (1‑12)
  const weekday  = parseField(weekday);    // weekday

  /** Convert a parsed array into the next valid value >= now */
  function nextValid(valueArr: number[], current: Date): number {
    let idx = valueArr.indexOf(current.getMinutes());
    if (idx === -1) return Number.MAX_SAFE_INTEGER; // never matches
    for (let i = idx + 1; i < valueArr.length; ++i) {
      const v = valueArr[i];
      if (v > current.getHours()) continue;
      if (valueArr.indexOf(v) !== i) continue; // duplicate entries not allowed in cron spec
      return v;
    }
    for (let i = 0; i < valueArr.length; ++i) {
      const v = valueArr[i];
      if (v > current.getHours()) break;
