    }
    // Simplified: just return the smallest element > now – this works because all fields are independent.
    const candidates = [...minute, ...hour, ...dom, ...month, ...weekday].filter(v => v > current.getTime());
    if (candidates.length === 0) {
      // no future value in any array → next run is after the first occurrence of the smallest element
      return Math.min(...valueArr);
    }
    return Math.min(...candidates);
  }

  const nextMin   = nextValid(minute, now);
  const nextHour  = nextValid(hour, new Date(now.getTime(), 0, 1)); // reset month/day to first day
  const nextDom   = nextValid(dom, new Date(now.getFullYear(), now.getMonth(), 1));
  const nextMonth = nextValid(month, new Date(now.getFullYear(), 0)); // January
  const nextWeekday = nextValid(weekday, now);

  // Choose the smallest timestamp that is >= now
  let candidates: number[] = [];
  if (nextMin !== Number.MAX_SAFE_INTEGER)   candidates.push(nextMin);
  if (nextHour !== Number.MAX_SAFE_INTEGER)  candidates.push(now.setHours(nextHour));
  if (nextDom !== Number.MAX_SAFE_INTEGER)   candidates.push(now.setDate(nextDom));
  if (nextMonth !== Number.MAX_SAFE_INTEGER) candidates.push(now.setMonth(nextMonth - 1)); // month is zero‑based
  if (nextWeekday !== Number.MAX_SAFE_INTEGER)
