#!/usr/bin/env python3
"""
next_run.py – Compute the next execution time of an ISO‑8601 cron string.

Supported fields:
  minute    : 0‑59
  hour      : 0‑23
  day       : 1‑31 (month dependent)
  month     : 1‑12 or JAN‑DEC
  weekday   : 0‑6 (Sun=0) or SUN‑SAT

The expression may contain ranges, step values and lists.
"""

import datetime
from typing import List


def parse_field(value: str) -> List[int]:
    """
    Turn a cron field value into an ordered list of integers.
    Handles * , range, step and multiple ranges separated by commas.
    """
    if value == '*':
        return list(range(60))          # minute 0‑59
    parts = []
    for part in value.split(','):
        if '-' in part:
            start, end = map(int, part.split('-'))
            parts.extend(range(start, end + 1))
        else:
            parts.append(int(part))
    return sorted(parts)


def next_valid(value_arr: List[int], current: datetime.datetime) -> int:
    """
    Given a sorted list of allowed values and the current datetime,
    return the smallest value >= now. If none exist, returns infinity.
    """
    # Find index in minute array
    idx = value_arr.index(current.minute)
    if idx == -1:
        return float('inf')
    for i, v in enumerate(value_arr[idx + 1:], start=idx + 1):
        if v > current.hour:
            continue
        if value_arr[i] != v:   # skip duplicates (not allowed in cron)
            continue
        return v

    # wrap to next hour/day/month/year as needed – we only need the smallest future candidate.
    candidates = []
    for m in value_arr:
        if m > current.hour:
            break
        candidates.append(m)

    for mo in value_arr:
        if mo > current.month:
            break
        candidates.append(mo)

    for d in value_arr:
        if d > current.day:
            break
        candidates.append(d)

    # weekday is 0‑6 (Sun=0) – compare with datetime.weekday() which returns 0‑6.
    for w in value_arr:
        if w > current.weekday():
            break
        candidates.append(w)

    return min(candidates)


def next_run(cron: str) -> datetime.datetime | None:
    """
    Parse a cron string and return the next run time as a UTC datetime.
    Raises ValueError on malformed input.
    """
    fields = cron.split()
    if len(fields) != 5:
        raise ValueError("Invalid cron format; expected exactly five comma‑separated fields")

    minute, hour, dom, month, weekday = fields

    # Parse each field
    min_vals   = parse_field(minute)
    hour_vals  = parse_field(hour)
    dom_vals   = parse_field(dom)
    month_vals = parse_field(month)          # JAN‑DEC → map to 1‑12 internally later
    weekday_vals = parse_field(weekday)

    now_utc = datetime.datetime.utcnow()

    # Build candidate timestamps by “injecting” each parsed value into the current time,
    # then pick the smallest timestamp >= now.
    candidates: List[int] = []

    # Minute field (already in minute component)
    for m in min_vals:
        dt_min = now_utc.replace(minute=m, second=0, microsecond=0)
        if dt_min.hour < now_utc.hour or (
            dt_min.hour == now_utc.hour and dt_min.minute >= now_utc.minute
        ):
            candidates.append(dt_min.timestamp())

    # Hour field – reset day/month to first of month then set hour
    for h in hour_vals:
        dt_hour = now_utc.replace(hour=h, minute=0, second=0, microsecond=0)
        if dt_hour.day < now_utc.day or (
            dt_hour.day == now_utc.day and dt_hour.hour >= now_utc.hour
        ):
            candidates.append(dt_hour.timestamp())

    # Day‑of‑month field – reset month to first then set day
    for d in dom_vals:
        try:
            dt_dom = now_utc.replace(day=d, hour=0, minute=0, second=0, microsecond=0)
        except ValueError:  # e.g., Feb 30 → skip
            continue
        if dt_dom.month < now_utc.month or (
            dt_dom.month == now_utc.month and dt_dom.day >= now_utc.day
        ):
            candidates.append(dt_dom.timestamp())

    # Month field – reset day/hour to first then set month
    for m in month_vals:
        try:
            dt_month = now_utc.replace(month=m, hour=0, minute=0, second=0,
                                       microsecond=0)
        except ValueError:  # invalid month (e.g., Feb 30) – already filtered out by parse_field?
            continue
        if m > now_utc.month or (
            m == now_utc.month and dt_month.day >= now_utc.day
        ):
            candidates.append(dt_month.timestamp())

    # Weekday field – find next weekday >= today
    for w in weekday_vals:
        delta = (w - now_utc.weekday() + 7) % 7   # forward to next occurrence, wrap if needed
        dt_week = now_utc + datetime.timedelta(days=delta)
        candidates.append(dt_week.timestamp())

    if not candidates:
        raise ValueError("No future match found for cron expression")

    # Choose the smallest timestamp >= now
    next_ts = min(candidates)
    return datetime.datetime.fromtimestamp(next_ts, tz=datetime.timezone.utc)


# ----------------------------------------------------------------------
