/**
 * Diff two JSON values.
 *
 * @param oldVal – The “old” value (object, array or primitive)
 * @param newVal – The “new” value (same type as oldVal)
 * @returns {added: Set<string>, removed: Set<string>,
 *          modified: Map<string,string>}   // key → new value
 */
function jsonDiff(oldVal: any, newVal: any): {
  added: Set<string>;
  removed: Set<string>;
  modified: Map<string, string>;
} {
  const added = new Set<string>();
  const removed = new Set<string>();
  const modified = new Map<string, string>();

  // Helper that recurses into objects / arrays
  function walk(path: string[], o: any, n: any): void {
    if (o === undefined || n === undefined) return; // nothing to diff

    // If both are plain objects → recurse
    if (
      typeof o === 'object' &&
      o !== null &&
      typeof n === 'object' &&
      n !== null
    ) {
      const keysO = Object.keys(o);
      const keysN = Object.keys(n);

      for (const k of new Set([...keysO, ...keysN])) {
        const newPath = [...path, k].join('.');
        walk(path.concat(k), o?.[k], n?.[k]);
      }
    } else if (
      Array.isArray(o) &&
      Array.isArray(n) &&
      o.length === n.length
    ) {
      // Compare arrays element‑by‑element (order matters)
      for (let i = 0; i < o.length; i++) {
        const newPath = [...path, String(i)].join('.');
        walk(path.concat(i), o[i], n[i]);
      }
    } else {
      // Primitive or mismatched types → treat as modification
      if (o !== n) modified.set(path.join('.'), JSON.stringify(n));
      // If both are equal but not identical references, we still consider it a diff?
      // Here we only flag real value changes.
    }
  }

  walk([], oldVal, newVal);

  return {
    added: new Set([...added].map(k => k.split('.').pop()!)), // strip path
    removed: new Set([...removed]),
    modified,
  };
}

