from typing import Any, Dict, List, Set, Tuple

def json_diff(old: Any, new: Any) -> Tuple[Set[str], Set[str], Dict[str, str]]:
    """
    Diff two JSON‑compatible values (dicts/lists/primitives).

    Returns:
        added   – keys present only in `new`
        removed – keys present only in `old`
        modified– key → value from `new` for changed fields
    """
    added = set()
    removed = set()
    modified: Dict[str, str] = {}

    def walk(path: List[str], o: Any, n: Any) -> None:
        # Nothing to diff if either side is undefined (should not happen)
        if o is None or n is None:
            return

        # Both dicts → recurse into each key
        if isinstance(o, dict) and isinstance(n, dict):
            keys = set(o.keys()) | set(n.keys())
            for k in keys:
                walk(path + [k], o.get(k), n.get(k))
        # Both lists (ordered) → compare element‑by‑element
        elif isinstance(o, list) and isinstance(n, list) and len(o) == len(n):
            for i, (a, b) in enumerate(zip(o, n)):
                walk(path + [str(i)], a, b)
        else:
            # Primitive or type mismatch → treat as modification if values differ
            if o != n:
                modified['.'.join(path)] = str(n)

    walk([], old, new)

    added = {k.split('.')[-1] for k in added}
    removed = {k.split('.')[-1] for k in removed}

    return added, removed, modified


