// ------------------------------------------------------------
// TreeNode type – you can replace this with your own definition.
type TreeNode<T = number> = {
  val: T;
  left?: TreeNode<T>;
  right?: TreeNode<T>;
};

/**
 * Serialize a binary tree into a compact string.
 *
 * Example (for the tree:
 *        1
 *      /   \
 *     2     3
 *          /
 *         4)
 *
 * → "1,2,#,#,3,4,#,#,#"
 */
function serialize(root: TreeNode | null): string {
  if (!root) return '#';
  
  const parts = [String(root.val)];
  // left subtree
  parts.push(serialize(root.left));
  // right subtree
  parts.push(serialize(root.right));

  return parts.join(',');
}

/**
 * Deserialize a comma‑separated string back into the original tree.
 */
function deserialize(data: string): TreeNode | null {
  const values = data.split(',').reverse(); // easier to pop from end

  function build(): TreeNode | null {
    if (values.length === 0) return null;
    const valStr = values.pop()!;
    if (valStr === '#') return null;

    const node: TreeNode = { val: Number(valStr), left: null, right: null };
    // note the order – right first because we pop from end
    node.right = build();
    node.left  = build();

    return node;
  }

  return build();
}

// ------------------------------------------------------------
```

**How it works**

* **serialize**: Walks pre‑order (`node → left → right`). A `null` child is represented by the sentinel `'#'`.  
* **deserialize**: Reverses the token list (so we can pop from the end) and recursively rebuilds nodes. The same sentinel guarantees correct reconstruction even for deep or unbalanced trees.

