# TreeNode definition – adapt if you already have a custom type.
class TreeNode:
    __slots__ = ('val', 'left', 'right')
    def __init__(self, val: int):
        self.val = val
        self.left = None
        self.right = None

def serialize(root: TreeNode | None) -> str:
    """Pre‑order traversal with '#' for null nodes."""
    if not root:
        return '#'
    
    vals = [str(root.val)]
    vals.append(serialize(root.left))
    vals.append(serialize(root.right))
    return ','.join(vals)

def deserialize(data: str):
    """Rebuild tree from the comma‑separated string produced by serialize."""
    tokens = iter(data.split(','))

    def build() -> TreeNode | None:
        val = next(tokens)
        if val == '#':
            return None
        node = TreeNode(int(val))
        node.left  = build()
        node.right = build()
        return node

    return build()

