  ```ts
  // rle.ts --------------------------------------------------------------
  /**
   * Run‑length encode an ASCII string.
   *
   * Example:
   *   compress("AAAABBBCCDAA") → "4A3B2C1D2A"
   */
  export function compress(input: string): string {
    if (!input) return "";
  
    let result = "";
    let count = 1;
    const last = input[0];
  
    for (let i = 1; i < input.length; ++i) {
      if (input[i] === last) {
        ++count;
      } else {
        // Append the count and the character
        result += `${count}${last}`;
        last = input[i];
        count = 1;
      }
    }
  
    // Flush the final run
    result += `${count}${last}`;
  
    return result;
  }
  
  /**
   * Run‑length decode a string produced by `compress`.
   *
   * Example:
   *   decompress("4A3B2C1D2A") → "AAAABBBCCDAA"
   */
  export function decompress(encoded: string): string {
    if (!encoded) return "";
  
    let result = "";
    let countStr = "";
  
    for (let i = 0; i < encoded.length; ) {
      // Read the numeric part
      while (i < encoded.length && /\d/.test(encoded[i])) {
        countStr += encoded[i];
        ++i;
      }
  
      const count = parseInt(countStr, 10) || 1;
  
      // The next character is the literal value
      if (i < encoded.length) {
        result += encoded[i].repeat(count);
        ++i;               // skip the literal char
      } else {
        throw new Error("Invalid RLE string – missing literal after count");
      }
  
      // Reset counters for next run
      countStr = "";
    }
    return result;
  }
  
  // --------------------------------------------------------------
  if (require.main === module) {
    const [cmd, ...args] = process.argv.slice(2);
    if (!cmd || !["compress", "decompress"].includes(cmd)) {
      console.error("Usage: node rle.ts <compress|decompress> <string>");
