  """
  Run‑length encoding (compress / decompress) in pure Python.
  """
  
  def compress(text: str) -> str:
      """Return the run-length encoded version of `text`."""
      if not text:
          return ""
      result = []
      count = 1
      last = text[0]
  
      for ch in text[1:]:
          if ch == last:
              count += 1
          else:
              result.append(f"{count}{last}")
              last = ch
              count = 1
      # flush the final run
      result.append(f"{count}{last}")
  
      return "".join(result)
  
  
  def decompress(encoded: str) -> str:
      """Return the original string from a run‑length encoded string."""
      if not encoded:
          return ""
      result = []
      i = 0
  
      while i < len(encoded):
          # consume all digits → count
          cnt_str = ""
          while i < len(encoded) and encoded[i].isdigit():
              cnt_str += encoded[i]
              i += 1
          count = int(cnt_str) if cnt_str else 1
  
          # next character is the literal value
          if i >= len(encoded):
              raise ValueError("Invalid RLE string – missing literal after count")
          literal = encoded[i]
          result.append(literal * count)
          i += 1   # skip the literal char
  
      return "".join(result)
  
  
