  // compress returns the run-length encoded string.
  func compress(input string) string {
  	if input == "" {
  		return ""
  	}
  	var buf []byte
  	count := 1
  	last := input[0]
  
  	for _, ch := range input[1:] {
  		if ch == last {
  			count++
  		} else {
  			buf = append(buf, strconv.Itoa(count)...)
  			buf = append(buf, last)
  			last = ch
  			count = 1
  		}
  	}
  	buf = append(buf, strconv.Itoa(count)...)
  	buf = append(buf, last)
  
  	return string(buf)
  }
  
  // decompress returns the original text from a run-length encoded string.
  func decompress(encoded string) (string, error) {
  	if encoded == "" {
  		return "", nil
  	}
  	var buf []byte
  	i := 0
  
  	for i < len(encoded) {
  		// read digits → count
  		cntStr := ""
  		for i < len(encoded) && encoded[i] >= '0' && encoded[i] <= '9' {
  			cntStr += string(encoded[i])
  			i++
  		}
  		if cntStr == "" {
  			return "", fmt.Errorf("invalid RLE: missing count")
  		}
  		count, err := strconv.Atoi(cntStr)
  		if err != nil {
  			return "", err
  		}
  
  		if i >= len(encoded) {
  			return "", fmt.Errorf("invalid RLE: missing literal after count")
  		}
  		literal := string(encoded[i])
  		buf = append(buf, bytes.Repeat([]byte(literal), count)...)
  
  		i++           // skip the literal char
  	}
  
  	return string(buf), nil
  }
  
