  // src/main.rs ---------------------------------------------------------
  use std::env;
  use std::error::Error;
  
  fn compress(input: &str) -> String {
      if input.is_empty() { return String::new(); }
      let mut buf = Vec::new();
      let (mut count, mut last_char) = (1, input.chars().next().unwrap());
  
      for ch in input.chars().skip(1) {
          if ch == last_char {
              count += 1;
          } else {
              write!(&mut buf, "{}{}", count, last_char).expect("format error");
              last_char = ch;
              count = 1;
          }
      }
      write!(&mut buf, "{}{}", count, last_char).expect("format error");
  
      String::from_utf8(buf).unwrap()
  }
  
  fn decompress(encoded: &str) -> Result<String, Box<dyn Error>> {
      if encoded.is_empty() { return Ok(String::new()); }
  
      let mut result = Vec::new();
      let mut i = 0;
  
      while i < encoded.len() {
          // consume all digits → count
          let mut cnt_str = String::new();
          while i < encoded.len() && encoded[i].is_ascii_digit() {
              cnt_str.push(encoded[i]);
              i += 1;
          }
          if cnt_str.is_empty() {
              return Err("invalid RLE: missing count".into());
          }
          let count: usize = cnt_str.parse().map_err(|e| e)?;
          // next character is the literal value
          if i >= encoded.len() {
              return Err("invalid RLE: missing literal after count".into());
          }
          let lit = encoded[i..=i].to_string();
          result.extend(std::iter::repeat(lit).take(count));
          i += 1; // skip literal char
      }
  
      Ok(String::from_utf8(result)?)
  }
  
  fn main() {
      if env::args().len() != 3 {
          eprintln!("Usage: {} <compress|decompress> <string>", env::args().next().unwrap());
          std::process::exit(1);
