// pkce.ts -------------------------------------------------------------
import { randomBytes } from "crypto";

/**
 * Generate a strong code verifier and its Base64‑URL challenge.
 *
 * @returns {verifier: string, challenge: string}
 */
export function generatePKCE(): { verifier: string; challenge: string } {
  // 1️⃣ Code Verifier – at least 43 characters (≈256 bits) for best security
  const verifier = randomBytes(32).toString("base64url");   // ~44 chars, URL‑safe

  // 2️⃣ Code Challenge (SHA‑256 → Base64URL)
  const challenge = Buffer.from(verifier, "utf8")
    .slice()                     // copy to avoid mutating original buffer
    .sha256()
    .toString("base64url");

  return { verifier, challenge };
}

/**
 * Verify that the server’s returned verifier matches what we stored.
 *
 * @param providedVerifier – value sent back by the authorization endpoint
 */
export function verifyPKCE(verifier: string, providedVerifier: string): boolean {
  // PKCE requires exact match (case‑sensitive)
  return verifier === providedVerifier;
}

