import os, base64, hashlib

def generate_pkce() -> tuple[str, str]:
    """
    Generate a strong code verifier and its Base64‑URL challenge.
    Returns: (verifier, challenge)
    """
    # 1️⃣ Code Verifier – at least 43 characters (~256 bits) for best security
    verifier = base64.urlsafe_b64encode(os.urandom(32)).decode('utf-8').rstrip('=')

    # 2️⃣ Code Challenge (SHA‑256 → Base64URL)
    sha256_hash = hashlib.sha256(verifier.encode()).digest()
    challenge = base64.urlsafe_b64encode(sha256_hash).decode('utf-8').rstrip("=")
    return verifier, challenge

def verify_pkce(verifier: str, provided_verifier: str) -> bool:
    """
    PKCE requires exact match (case‑sensitive).
    """
    return verifier == provided_verifier


