package main

import (
	"crypto/rand"
	"encoding/base64"
	"fmt"
	"hash/sha256"
)

// generatePKCE returns a code verifier and its Base64URL challenge.
func generatePKCE() (verifier, challenge string, err error) {
	const verifierLen = 32 // 256 bits → ~44 chars URL‑safe
	b := make([]byte, verifierLen)
	_, err = rand.Read(b)
	if err != nil {
		return "", "", fmt.Errorf("random bytes: %w", err)
	}
	verifier = base64.RawURLEncoding.EncodeToString(b)

	// SHA256 → Base64URL challenge (same as other languages)
	h := sha256.Sum256([]byte(verifier))
	challenge = base64.URLEncoding.EncodeToString(h[:])
	return verifier, challenge, nil
}

// verifyPKCE checks exact equality – PKCE requires no tolerance for case or padding.
func verifyPKCE(verifier string, providedVerifier string) bool {
	return verifier == providedVerifier
}

