## 1️⃣ TypeScript (Express / Koa style)

```ts
// rateLimit.ts ---------------------------------------------------------
import { Request, Response, NextFunction } from 'express';

/**
 * Options for the middleware.
 */
export interface RateLimitOptions {
  /** Maximum allowed requests per IP within a window. */
  maxRequests: number;
  /** Window length in milliseconds (e.g., 60_000 = 1 minute). */
  windowMs: number;
}

/**
 * Middleware that limits each IP address to `maxRequests` calls
 * inside the given time‑window.
 *
 * @param opts   Options object.
 * @returns      Express/Koa style middleware function.
 */
export const rateLimitMiddleware = (opts: RateLimitOptions) => (
  req: Request,
  res: Response,
  next: NextFunction
): void => {
  const ip = req.ip; // <-- works in most Node frameworks; replace with X-Forwarded‑For if needed

  // In‑memory store – key = IP, value = array of timestamps (ms)
  const storage = rateLimitMiddleware._storage as Map<string, number>;

  // Initialise the bucket for this IP
  if (!storage.has(ip)) {
    storage.set(ip, []);
  }

  const timestamps = storage.get(ip)!;
  // Remove old entries that are outside the window
  timestamps.splice(
    0,
    timestamps.findIndex((t) => t + opts.windowMs < Date.now()) + 1
  );

  if (timestamps.length >= opts.maxRequests) {
    res.status(429).json({ error: 'Too Many Requests', message: `Rate limit exceeded for ${ip}` });
    return;
  }

  // Allow the request to continue
  timestamps.push(Date.now());
  next();
};

// Initialise static storage once – works in any Express app.
rateLimitMiddleware._storage = new Map<string, number>();
```

**How to use**

```ts
import express from 'express';
import { rateLimitMiddleware } from './rateLimit';

const app = express();

app.use(rateLimitMiddleware({ maxRequests: 100, windowMs: 60_000 }));

// Example route
app.get('/', (req, res) => {
  res.send('Hello world');
});

app.listen(3000, () => console.log('Server listening on :3000'));
```

*If you prefer Koa:* replace `next()` with `await ctx.next();` and use `ctx.ip` instead of `req.ip`.

