## 2️⃣ Python (Flask)

```python
# rate_limit.py ---------------------------------------------------------
from flask import Flask, request, jsonify, g
import time

class RateLimit:
    def __init__(self, max_requests: int = 100, window_ms: int = 60_000):
        self.max_requests = max_requests
        self.window_ms = window_ms          # sliding‑window length in ms
        self._storage = {}                  # ip → list of timestamps

    def _get_bucket(self, ip: str) -> list[float]:
        bucket = self._storage.get(ip)
        if not bucket:
            bucket = []
            self._storage[ip] = bucket
        return bucket

    def allow(self, ip: str) -> bool:
        """Return True if request is allowed."""
        now = time.time()
        bucket = self._get_bucket(ip)

        # purge old timestamps outside the window
        while bucket and (now - bucket[0]) > self.window_ms / 1000.0:
            bucket.pop(0)

        if len(bucket) >= self.max_requests:
            return False

        bucket.append(now)
        return True


# --------------------------------------------------------------
app = Flask(__name__)
rate_limit_middleware = RateLimit(max_requests=100, window_ms=60_000)


@app.before_request
def before():
    ip = request.remote_addr or 'unknown'
    if not rate_limit_middleware.allow(ip):
        return jsonify(error="Too Many Requests"), 429


# --------------------------------------------------------------
@app.route('/')
def hello():
    return "Hello world"


if __name__ == '__main__':
    app.run(port=5000)
```

**Key points**

* `before_request` runs **once per request**, before any view function.
* The middleware stores timestamps in a global dictionary (`RateLimit._storage`).  
  For production you’d replace this with Redis, Memcached, or another distributed cache.

