// rate_limit.go ---------------------------------------------------------
package main

import (
	"net/http"
	"sync"
	"time"

	"github.com/gorilla/mux" // optional mux for cleaner routing; can be omitted
)

type RateLimitOptions struct {
	MaxRequests int    `json:"max_requests"`
	WindowMs    int64  `json:"window_ms"` // milliseconds
}

// In‑memory store: ip → slice of timestamps (time.Time)
var (
	rateLimitMu sync.Mutex
	buckets     = make(map[string][]time.Time) // IP -> []time.Time
)

func init() {
	// nothing to init for this simple example; just keep the map in memory.
}

// allowIP returns true if request is allowed, otherwise false and a 429 response writer.
func allowIP(r *http.Request) (bool, http.ResponseWriter) {
	ip := r.RemoteAddr // simplest – replace with X-Forwarded‑For if needed
	rateLimitMu.Lock()
	defer rateLimitMu.Unlock()

	bucket := buckets[ip]
	now := time.Now().UnixNano() / 1_000_000 // ms

	// prune old entries outside the window
	for len(bucket) > 0 && now-bucket[0] >= rateLimitOptions.WindowMs {
		bucket = bucket[1:]
	}

	if len(bucket) >= rateLimitOptions.MaxRequests {
		return false, nil // caller will handle 429
	}
	bucket = append(bucket, now)

	rateLimitMu.Unlock()
	return true, nil
}

// Example handler that uses the middleware.
func helloHandler(w http.ResponseWriter, r *http.Request) {
	w.Write([]byte("Hello world"))
}

func main() {
	options := RateLimitOptions{
		MaxRequests: 100,
		WindowMs:    60_000,
	}
	http.HandleFunc("/", func(w http.ResponseWriter, r *http.Request) {
		ok, w := allowIP(r)
		if !ok {
			w.Header().Set("Content-Type", "application/json")
			w.WriteHeader(http.StatusTooManyRequests)
			json.NewEncoder(w).Encode(map[string]string{
				"error":    "Rate limit exceeded",
				"message":  "Please try again later.",
			})
			return
		}
		helloHandler(w, r) // continue to the real handler
	})

	http.ListenAndServe(":8080", nil)
}
```

**How it works**

* The global `buckets` map holds a slice of timestamps per IP.
* Before each request we **prune** entries older than the configured window and then either allow or reject based on length.
* Because Go’s standard library doesn’t ship with Redis, this in‑memory store is fine for quick demos but you’d swap it out (e.g., `github.com/go-redis/redis/v8`) in production.

