  func allowIP(r *http.Request) (bool, http.ResponseWriter) {
  	ip := r.RemoteAddr // simplest – replace with X-Forwarded‑For if needed
  	rateLimitMu.Lock()
  	defer rateLimitMu.Unlock()
  
  	bucket := buckets[ip]
