    const secret = randomBytes(cfg.secretLength);
    // Convert to a hex / base64 representation that is URL‑safe.
    const rawSecret = secret.toString("hex"); // you could also use Base64

    // 2️⃣ Compute checksum – simple CRC16‑CCITT (0xFFFF initial, polynomial 0xA001)
    const crc = computeCrc16(rawSecret);
    // Format the checksum as two uppercase hex digits.
    const checksum = crc.toString(16).padStart(4, "0").toUpperCase();

    // 3️⃣ Assemble key: prefix + "-" separator (optional but readable) + checksum
    return `${cfg.prefix}-${checksum}`;
}

/**
