    const secretHex = parts[1]; // we only need the part after the dash

    // Re‑compute checksum on the *secret* hex string and compare.
    const computedCrc = computeCrc16(secretHex);
    const expectedChecksum = parts[0].slice(5).padStart(4, "0").toUpperCase(); // just in case
    return computedCrc === expectedChecksum;
}

/**
 * Helper: CRC‑16‑CCITT (no initial/final XOR) – fast and deterministic.
 */
function computeCrc16(data: string): number {
    let crc = 0xFFFF;               // initial value
    const poly = 0xA001;

    for (let i = 0; i < data.length; ++i) {
