#!/usr/bin/env python3
"""
apiKeyGenerator.py
Generate a cryptographically‑secure API key with configurable prefix and checksum.
"""

import os
import re
from typing import Tuple, Literal

# --------------------------------------------------------------------------


class ApiKeyConfig:
    """
    Configuration for the generated API key.

    secret_length: number of random bytes → entropy (e.g., 8 = ~256 bits)
    prefix: ASCII string that will be prepended to the final key.
            Must contain only letters/digits/hyphen/underscore etc. as desired.
    """

    def __init__(self, secret_length: int = 8, prefix: str = "dev"):
        self.secret_length = secret_length
        self.prefix = prefix


# --------------------------------------------------------------------------


def generate_api_key(cfg: ApiKeyConfig) -> str:
    """
    Generate a new API key.

    Returns:
        Full key string like "dev-ABCD1234"
    """

    # 1️⃣ Random bytes (cryptographically secure)
    secret_bytes = os.urandom(cfg.secret_length)

    # Convert to hex – URL‑safe, deterministic length.
    secret_hex = secret_bytes.hex()          # e.g. "a3f5c2e9b4..."

    # ------------------------------------------------------------------
    # 2️⃣ Compute checksum (CRC16-CCITT)
    def crc16_ccitt(data: str) -> int:
        """Simple CRC‑16‑CCITT without XOR‑initial/final."""
        poly = 0x1021
        crc = 0xFFFF
        for ch in data:
            val = ord(ch) << 12          # shift high bits in
            crc ^= val
            for _ in range(8):
                if crc & 0x8000:
                    crc = ((crc << 1) ^ poly)
                else:
                    crc <<= 1
        return crc & 0xFFFF

    checksum_int = crc16_ccitt(secret_hex)
    # Format as uppercase hex with leading zeros (4 chars total).
    checksum_str = f"{checksum_int:04X}"

    # ------------------------------------------------------------------
    # 3️⃣ Assemble key: prefix + "-" separator + checksum
    full_key = f"{cfg.prefix}-{checksum_str}"
    return full_key


def validate_api_key(api_key: str, cfg: ApiKeyConfig) -> bool:
    """
    Validate a previously generated API key.

    Returns True only if the format matches `<prefix>-<4‑hex-checksum>`
    and the checksum computed from the secret part equals the stored one.
    """

    # Regex pattern – case‑insensitive prefix, dash, exactly 4 hex chars.
    pattern = re.compile(rf"^{re.escape(cfg.prefix)}-[0-9A-Fa-f]{{4}}$")
    if not pattern.match(api_key):
        return False

    secret_hex = api_key.split("-", 1)[1]
    # Re‑compute checksum on the *secret* part only.
    computed_checksum_int = crc16_ccitt(secret_hex)
    expected_checksum_str = f"{computed_checksum_int:04X}"
    stored_checksum_str = re.search(rf"-([0-9A-Fa-f]{{4}})$", api_key)?.group(1) or ""
    return checksum_str == stored_checksum_str


# --------------------------------------------------------------------------


if __name__ == "__main__":
    # Quick demo – run as a script.
    cfg = ApiKeyConfig(secret_length=8, prefix="dev")
    key = generate_api_key(cfg)
    print("Generated API Key:", key)

    # Validate a few examples:
    test_keys = [
        f"{cfg.prefix}-{checksum}" for checksum in (
            f"{crc16_ccitt(f'{cfg.prefix}-xxxx') & 0xFFFF:04X}"
            for _ in range(5)   # generate random secret + checksum
        )
    ]
    print("\nValidation results:")
    for k in test_keys:
        print(k, "→", validate_api_key(k, cfg))
