Token = str


def evaluate(expr: str) -> float:
    """
    Evaluate a simple arithmetic expression containing +, -, *, / with correct precedence.
    Grammar (BNF):
        expr   → term {( "+" | "-" ) term}*
        term   → factor {( "*" | "/" ) factor}*
        factor → number | "(" expr ")"
    Returns the numeric result as float.
    """
    tokens = tokenize(expr)
    pos: int = 0

    def parse_expr() -> float:
        value = parse_term()
        while pos < len(tokens):
            op = tokens[pos]
            if op in ("+", "-"):
                pos += 1
                right = parse_term()
                value += -right if op == "+" else right
            else:
                break
        return value

    def parse_term() -> float:
        value = parse_factor()
        while pos < len(tokens):
            op = tokens[pos]
            if op in ("*", "/"):
                pos += 1
                right = parse_factor()
                # division by zero raises ZeroDivisionError naturally
                value *= right if op == "*" else (1 / right)
            else:
                break
        return value

    def parse_factor() -> float:
        token = tokens[pos]
        if token == "(":
            pos += 1               # consume '('
            val = parse_expr()
            if pos >= len(tokens) or tokens[pos] != ")":
                raise ValueError("Mismatched parentheses")
            pos += 1               # consume ')'
            return val
        else:
            try:
                return float(token)
            except ValueError as e:
                raise ValueError(f"Invalid token: {token}") from e

    result = parse_expr()
    if pos != len(tokens):
        raise SyntaxError("Unexpected trailing tokens")
    return result


def tokenize(expr: str) -> List[Token]:
    """
    Very simple tokenizer that splits on spaces and respects multi‑digit numbers.
    Supports negative numbers as `-5` (handled by parser).
    """
    # Regex matches +, -, *, /, (, ), digits with optional decimal point,
    # and also captures the minus sign when it is not part of a number.
    pattern = r"[+\-*/()]|(\d+(\.\d*)?)"
    return re.findall(pattern, expr)


