package main

import (
	"fmt"
	"os"
	"regexp"
)

// ------------------------------------------------------------------
// Tokenizer ---------------------------------------------------------
func tokenize(expr string) []string {
	re := regexp.MustCompile(`[+\-*/()]|(\d+(\.\d*)?)`)
	return re.FindAllStringSubmatch(expr, -1)
}

// ------------------------------------------------------------------
// Parser -----------------------------------------------------------
type Expr struct{ tokens []string; pos int }

func (p *Expr) parseExpr() float64 {
	value := p.parseTerm()
	for {
		if p.pos >= len(p.tokens) {
			break
		}
		op := p.tokens[p.pos]
		p.pos++
		right := p.parseTerm()
		switch op {
		case "+":
			value += right
		case "-":
			value -= right
		default:
			panic("unexpected operator")
		}
	}
	return value
}

func (p *Expr) parseTerm() float64 {
	value := p.parseFactor()
	for {
		if p.pos >= len(p.tokens) {
			break
		}
		op := p.tokens[p.pos]
		p.pos++
		right := p.parseFactor()
		switch op {
		case "*":
			value *= right
		case "/":
			if right == 0 {
				panic("division by zero")
			}
			value /= right
		default:
			panic("unexpected operator")
		}
	}
	return value
}

func (p *Expr) parseFactor() float64 {
	token := p.tokens[p.pos]
	p.pos++
	if token == "(" {
		val := p.parseExpr()
		if p.pos >= len(p.tokens) || p.tokens[p.pos] != ")" {
			panic("mismatched parentheses")
		}
		p.pos++ // consume ')'
		return val
	}
	f, err := strconv.ParseFloat(token, 64)
	if err != nil {
		panic(fmt.Sprintf("invalid token %q", token))
	}
	return f
}

// ------------------------------------------------------------------
func evaluate(expr string) float64 {
	tokens := tokenize(expr)
	p := Expr{tokens: tokens, pos: 0}
	return p.parseExpr()
}

// ------------------------------------------------------------------
func main() {
	if len(os.Args) != 2 {
		fmt.Fprintf(os.Stderr, "Usage: %s \"2 + 3 * (4 - 1)\"\n", os.Args[0])
		os.Exit(1)
	}
	expr := os.Args[1]
	result := evaluate(expr)
	fmt.Printf("Result of \"%s\" → %.6g\n", expr, result)
}
