package main

import (
	"fmt"
	"regexp"
)

// render returns the input string with all "{{key}}" replaced by data[key].
func render(template string, data map[string]interface{}) string {
	re := regexp.MustCompile(`\{\{(\w+)\}\}`)
	return re.ReplaceAllStringFunc(template, func(match string) string {
		key := match[2 : len(match)-1] // strip {{}} and split
		value, ok := data[key]
		if !ok {
			panic(fmt.Sprintf("key %q not found in data", key))
		}
		return fmt.Sprint(value)
	})
}

func main() {
	tmpl := "Hello {{name}}, your score is {{score}}."
	values := map[string]interface{}{
		"name":   "Aura",
		"score":  95,
	}
	fmt.Println(render(tmpl, values))
}
