fn render(template: &str, data: &HashMap<String, String>) -> String {
    let re = regex::Regex::new(r"\{\{(\w+)\}\}").unwrap();
    re.replace_all(template, |caps: &regex::Captures| {
        let key = caps.get(1).map(|m| m.as_str()).unwrap_or("");
        data.get(key)
