/**
 * Convert a non‑negative integer to its English words representation.
 *
 * Supports numbers up to trillions (e.g. 1234567890123 → "one trillion two hundred thirty four billion five hundred sixty seven million eight hundred ninety thousand one hundred twenty three").
 *
 * @param num – the number to convert
 * @returns a string with the English word form, or an empty string for invalid input
 */
function numberToEnglish(num: number): string {
  if (num < 0) throw new Error('Only non‑negative integers are supported');

  // ---------- Helper strings ----------
  const units = ['', 'one', 'two', 'three', 'four', 'five', 'six', 'seven',
                'eight', 'nine'];
  const teens = ['ten','eleven','twelve','thirteen','fourteen','fifteen',
                 'sixteen','seventeen','eighteen','nineteen'];
  const tens = ['', '', 'twenty', 'thirty', 'forty', 'fifty',
                'sixty', 'seventy', 'eighty', 'ninety'];
  const scales = ['', 'thousand', 'million', 'billion', 'trillion'];

  // ---------- Helper to process a “chunk” of up to three digits ----------
  function helperThree(d: number): string {
    if (d === 0) return '';
    let out = '';

    const hundreds = Math.floor(d / 100);
    d %= 100;
    if (hundreds > 0) {
      out += units[hundreds] + ' hundred';
      if (d !== 0) out += ' ';
    }

    // Handle teens and normal tens/hundreds
    if (d >= 20) {
      const ten = Math.floor(d / 10);
      out += tens[ten];
      d %= 10;
      if (d > 0) out += '-' + units[d];   // e.g. twenty‑one
    } else if (d > 0 && d < 10) {
      out += units[d];
    }
    return out.trim();
  }

  // ---------- Main conversion ----------
  const n = Number(num);
  if (isNaN(n)) throw new Error('Invalid number');

  if (n === 0) return 'zero';

  let result = '';
  let i = 0;   // index into `scales`

  while (n > 0) {
    if (n % 1000 !== 0) {
      const threeDigitStr = helperThree(n % 1000);
      if (threeDigitStr) {
        result =
          threeDigitStr + ' ' + scales[i] +
          (result ? ` ${result}` : '');
      }
    }
    n = Math.floor(n / 1000);
    i++;
  }

  return result.trim();
}

/* ---- Example usage ---- */
if (require.main === module) {
  // Run a quick sanity‑check
  const tests: number[] = [0,1,10,11,12,20,21,99,
                           100,101,110,111,115,
                          1200,1234,9999,
                         1000000,1234567,
                        9876543210,
                       1234567890123];
  for (const t of tests) {
    console.log(`${t} → ${numberToEnglish(t)}`);
  }
}
```

