    """
    Convert a non‑negative integer to its English words representation.
    
    Supports numbers up to trillions (e.g. 1234567890123 → 
    "one trillion two hundred thirty four billion five hundred sixty seven million eight hundred ninety thousand one hundred twenty three").
    
    :param num: the number to convert
    :raises ValueError: if `num` is negative or not an integer
    :return: a string with the English word form, or empty string for invalid input
    """
    # ---------- Helper strings ----------
    units = ['', 'one', 'two', 'three', 'four', 'five',
             'six', 'seven', 'eight', 'nine']
    teens = ['ten','eleven','twelve','thirteen','fourteen','fifteen',
             'sixteen','seventeen','eighteen','nineteen']
    tens = ['', '', 'twenty', 'thirty', 'forty', 'fifty',
            'sixty', 'seventy', 'eighty', 'ninety']
    scales = ['', 'thousand', 'million', 'billion', 'trillion']

    # ---------- Helper for a three‑digit chunk ----------
    def helper_three(d: int) -> str:
        if d == 0:
            return ''
        out = ''

        hundreds = d // 100
        d %= 100
        if hundreds > 0:
            out += units[hundreds] + ' hundred'
            if d != 0:
                out += ' '
        # Tens and ones (including teens)
        if d >= 20:
            ten = d // 10
            out += tens[ten]
            d %= 10
            if d > 0:
                out += '-' + units[d]   # e.g. twenty‑one
        elif d > 0 and d < 10:
            out += units[d]
        return out.strip()

    # ---------- Main conversion ----------
    n = float(num)
    if not isinstance(n, (int, float)) or n != int(n):
        raise ValueError('Input must be an integer')
    if num < 0:
        raise ValueError('Only non‑negative integers are supported')

    result = ''
    i = 0
    while n > 0:
        chunk = int(n % 1000)
        if chunk:
            three_str = helper_three(chunk)
            result = (three_str + ' ' + scales[i] +
                      ('' if not result else ' ' + result))
        n //= 1000
        i += 1

    return result.strip() or 'zero'


