// ------------------------------------------------------------
// FuzzyStringSimilarity.ts
// ------------------------------------------------------------

/**
 * Returns a similarity score (0.0 … 1.0) for two input strings.
 *
 * The implementation uses the Levenshtein distance algorithm,
 * normalised so that an identical string yields 1.0 and completely
 * different strings yield 0.0.
 */
export function fuzzySimilarity(a: string, b: string): number {
    // ----- Helper: classic Levenshtein distance -----------------
    const levenshtein = (s: string, t: string): number => {
        const m = s.length;
        const n = t.length;

        if (m === 0) return n;
        if (n === 0) return m;

        // work on a matrix of size (m+1) × (n+1)
        const d: number[] = new Array(n + 1).fill(0);
        for (let i = 0; i <= n; ++i) d[i] = i;

        for (let i = 1; i <= m; ++i) {
            let prev = i - 1;
            d[0] = i;
            const c_i = s.charAt(i - 1);
            for (let j = 1; j <= n; ++j) {
                // cost is 0 when characters match, else 1
                const cost = s[j - 1] === t[j - 1] ? 0 : 1;
                const del   = d[j] + 1;          // deletion
                const ins   = d[j - 1] + 1;      // insertion
                const sub   = prev + (cost === 0 ? 0 : 1); // substitution

                d[j] = Math.min(del, ins, sub);
                prev = d[j];
            }
        }

        return d[n]; // distance between full strings
    };

    // ----- Normalise to [0,1] ---------------------------------
    const dist = levenshtein(a, b);
    const maxLen = Math.max(a.length, b.length);

    if (maxLen === 0) {
        // both empty → perfect match
        return 1.0;
    }

    return 1 - (dist / maxLen);   // lower distance ⇒ higher similarity
}

