    """
    Classic Wagner‑Fischer algorithm – returns the edit distance.
    """
    m, n = len(s), len(t)
    if m == 0:
        return n
    if n == 0:
        return m

    # initialise first row (distance from empty string)
    prev_row = list(range(n + 1))

    for i in range(1, m + 1):
        cur_row = [i]          # cost of deleting all chars up to i‑1
        c_i = s[i - 1]
        for j in range(1, n + 1):
            d_j_minus_1 = prev_row[j] + 1               # insertion
            del_j_minus_1 = cur_row[j - 1] + 1          # deletion
            cost = 0 if c_i == t[j - 1] else 1         # substitution
            sub_j_minus_1 = prev_row[j - 1] + (cost)    # substitution/match

            cur_row.append(min(d_j_minus_1, del_j_minus_1, sub_j_minus_1))
        prev_row = cur_row

    return prev_row[n]


