/**
 * Returns a similarity score (float64) in the range [0.0, 1.0].
 * Identical strings → 1.0; completely different → 0.0.
 *
 * The implementation uses Levenshtein distance normalised by
 * the length of the longer string.
 */
func fuzzySimilarity(a, b string) float64 {
	// ----- Helper: classic Levenshtein distance -----------------
	dist := levenshteinDistance(a, b)

	maxLen := len(a)
	if l := len(b); l > maxLen {
		maxLen = l
	}

	if maxLen == 0 {
		return 1.0 // both empty strings are identical
	}

	normDist := float64(dist) / float64(maxLen)
	return 1 - normDist // higher distance → lower similarity
}

// ----- Levenshtein distance (Wagner‑Fischer DP) ---------------
func levenshteinDistance(s, t string) int {
	m, n := len(s), len(t)
	if m == 0 {
		return n
	}
	if n == 0 {
		return m
	}

	prevRow := make([]int, n+1)
	for j := range prevRow {
		prevRow[j] = j
	}

	for i := 1; i <= m; i++ {
		curRow := []int{i} // cost of deleting first i chars from s
		ci := s[i-1]
		for j := 1; j <= n; j++ {
			djMinusOne := prevRow[j] + 1               // insertion
			delJMinusOne := curRow[j-1] + 1            // deletion
			subCost := 0
			if ci == t[j-1] {
				subCost = 0                                 // match / no substitution
			} else {
				subCost = 1
			}
			subJMinusOne := prevRow[j-1] + subCost        // substitution/match

			curRow = append(curRow, min(djMinusOne, delJMinusOne, subJMinusOne))
		}
		prevRow = curRow
	}

	return prevRow[n]
}

// ----- Helper to get minimum of three ints --------------------
func min(a, b, c int) int {
	if a <= b && a <= c {
		return a
	} else if b <= a && b <= c {
		return b
	}
	return c
}

// ------------------------------------------------------------
// Example usage (run with `go run fuzzy_match.go`)
// ------------------------------------------------------------
