	import "os"
	if len(os.Args) != 3 {
		fmt.Printf("Usage: %s <string1> <string2>\n", os.Args[0])
		os.Exit(1)
	}
	a, b := os.Args[1], os.Args[2]
	score := fuzzySimilarity(a, b)
	fmt.Printf("Similarity(%q, %q) = %.4f\n", a, b, score)
}
