## 1. TypeScript

```ts
// LightSwitch.ts ---------------------------------------------------------

type State = 'OFF' | 'ON';

class InvalidTransitionError extends Error {
    constructor(message: string) {
        super(message);
        this.name = 'InvalidTransitionError';
    }
}

/**
 * Simple deterministic state machine.
 *
 * - start() → "off"
 * - press(): if current === "off"  -> "on"
 *               else            -> throws InvalidTransitionError
 */
export class LightSwitch {
    private _state: State;

    constructor() {
        this._state = 'OFF';
    }

    get state(): State {
        return this._state;
    }

    /**
     * Simulate pressing the switch.
     *
     * @throws {InvalidTransitionError} when trying to go from OFF → OFF or
     *                                   ON → ON (invalid transitions).
     */
    press(): void {
        if (this._state === 'OFF') {
            this._state = 'ON';
        } else if (this._state === 'ON') {
            // From "on" we must return to "off"
            throw new InvalidTransitionError(
                `Cannot stay on. Expected transition OFF → ON, not ON → ON`
            );
        }
    }

    /**
     * Reset the machine back to its initial state.
     */
    reset(): void {
        this._state = 'OFF';
    }
}

// ----------------------------------------------------------------------
```

