```ts
// ---------------------------------------------------
// observer.ts – core interfaces & classes for the pattern
// ---------------------------------------------------
interface ISubject {
    /** Register an observer */
    subscribe(observer: IObservable): void;

    /** Remove a previously‑registered observer */
    unsubscribe(observer: IObservable): void;

    /** Notify all observers that something changed */
    notify(): void;
}

/** Simple observable implementation */
class Subject implements ISubject {
    private observers: IObservable[] = [];

    public subscribe(observer: IObservable): void {
        this.observers.push(observer);
    }

    public unsubscribe(observer: IObservable): void {
        const idx = this.observers.indexOf(observer);
        if (idx !== -1) {
            this.observers.splice(idx, 1);
        }
    }

    /** Call every observer with the supplied event data */
    public notify(data?: any): void {
        for (const obs of this.observers) {
            // The callback receives whatever payload we want to pass.
            obs.update(this, data ?? undefined);
        }
    }
}

// ---------------------------------------------------
// observers.ts – concrete observers
// ---------------------------------------------------

/** Observer interface that every subscriber must implement */
interface IObservable {
    /** Called when the subject notifies an observer */
    update(subject: ISubject, data?: any): void;
}

/**
 * Example observer #1 – logs to console.
 */
class LoggerObserver implements IObservable {
    public update(subject: ISubject, data?: any) {
        console.log(`[Logger] received ${subject.constructor.name}:`, data);
    }
}

/**
 * Example observer #2 – stores events in an array (useful for replay).
 */
class CollectorObserver implements IObservable {
    private events: Array<{ subjectName: string; payload?: any }> = [];

    public update(subject: ISubject, data?: any) {
        this.events.push({ subjectName: subject.constructor.name, payload: data });
    }

    /** Return the collected events for inspection */
    public getEvents() => this.events;
}

// ---------------------------------------------------
// demo.ts – usage example
// ---------------------------------------------------

import { Subject } from "./observer";

const subject = new Subject();

const logger = new LoggerObserver();
subject.subscribe(logger);

const collector = new CollectorObserver();
subject.subscribe(collector);

console.log("🔔 Notifying observers...");

subject.notify("Event A");   // → logs + stores in collector
subject.notify("Event B", { extra: "payload" });

// Show what the collector gathered:
console.log("\nCollector events:", collector.getEvents());
```

**What you see**

* `Subject` implements **ISubject** – it holds a list of observers and notifies them.
* Each observer implements **IObservable** – its sole method is `update`.
* The demo registers two concrete observers (`LoggerObserver`, `CollectorObserver`) and then triggers a notification that each receives.

