## 2️⃣ Python  

```python
# ---------------------------------------------------
# observer.py – core Observer pattern implementation in Python
# ---------------------------------------------------

from typing import List, Callable


class Subject:
    """
    The subject maintains a list of observers.
    It provides methods to register/unregister observers and to notify them.
    """

    def __init__(self):
        self._observers: List[Callable[[object], None]] = []

    def subscribe(self, observer) -> None:
        """Add an observer."""
        if observer not in self._observers:
            self._observers.append(observer)

    def unsubscribe(self, observer) -> None:
        """Remove a previously‑registered observer."""
        try:
            self._observers.remove(observer)
        except ValueError:
            pass  # Observer was never registered

    def notify(self, data=None) -> None:
        """
        Call every observer with the supplied payload.
        The callback receives the subject instance and an optional payload.
        """
        for obs in self._observers:
            obs(self, data)


# ---------------------------------------------------
# concrete observers
# ---------------------------------------------------

class LoggerObserver:
    def __call__(self, subject: Subject, data=None):
        print(f"[Logger] {subject.__class__.__name__} received: {data}")


class CollectorObserver:
    def __init__(self):
        self._events: List[dict] = []

    def __call__(self, subject: Subject, data=None):
        # Store a dict so we can inspect later.
        self._events.append({"subject": type(subject).__name__, "payload": data})

    @property
    def events(self) -> List[dict]:
        return self._events


# ---------------------------------------------------
# demo – usage example
# ---------------------------------------------------

if __name__ == "__main__":
    subject = Subject()

    logger = LoggerObserver()
    collector = CollectorObserver()

    # Register observers (order matters)
    subject.subscribe(logger)
    subject.subscribe(collector)

    print("🔔 Notifying all observers...")
    subject.notify("Event A")          # simple string payload
    subject.notify("Event B", {"extra": "payload"})  # richer payload

    print("\nCollector events:", collector.events)
```

**Key points**

* `Subject` holds a list `_observers` of callables.
* Subscribing/unsubscribing are explicit methods; the callback receives `(subject, data)`.
* Concrete observers implement the same callable signature (`__call__`) so they can be used interchangeably with any function or class that defines `def __call__(self, subject, *args)`.

