## 3️⃣ Go  

```go
// ---------------------------------------------------
// observer.go – Observer pattern in Go (no interfaces needed)
// ---------------------------------------------------

package main

import (
	"fmt"
)

// Subject is the central object that maintains observers.
type Subject struct {
	observers []Observer // slice of functions, no explicit interface required
}

// Observer defines a single callback type: it receives the subject and optional payload.
type Observer func(*Subject, ...interface{})

func (s *Subject) subscribe(o Observer) {
	s.observers = append(s.observers, o)
}

func (s *Subject) unsubscribe(o Observer) {
	for i, obs := range s.observers {
		if obs == o {
			s.observers = append(s.observers[:i], s.observers[i+1:]...)
			break
		}
	}
}

// Notify calls every observer with the subject and optional payload.
func (s *Subject) notify(payload ...interface{}) {
	for _, o := range s.observers {
		o(s, payload...)
	}
}

// ---------------------------------------------------
// concrete observers – simple functions that print or collect data
// ---------------------------------------------------

type LoggerObserver struct{}

func (*LoggerObserver) Update(*Subject, ...interface{}) {
	fmt.Println("[Logger] received notification")
}

type CollectorObserver struct {
	events [][]interface{} // store raw payloads for later inspection
}

func (c *CollectorObserver) Update(*Subject, payload ...interface{}) {
	c.events = append(c.events, payload)
}

// ---------------------------------------------------
// demo – usage example in main()
// ---------------------------------------------------

func main() {
	sub := Subject{}

	logger := LoggerObserver{}
	collector := CollectorObserver{}

	// Register observers
	sub.subscribe(logger.Update)
	sub.subscribe(collector.Update)

	fmt.Println("🔔 Notifying observers...")
	sub.notify("Event A")          // payload as slice of interfaces
	sub.notify("Event B", 42, true) // mixed types allowed

	// Show what collector gathered
	fmt("\nCollector events:\n")
	for _, ev := range collector.events {
		fmt.Printf("%+v\n", ev)
	}
}
```

**Why Go works without explicit interfaces**

* In Go you can pass a function directly as an observer. The compiler guarantees that the called function matches the signature `func(*Subject, ...interface{})`.
* No need for heavyweight interface definitions; just treat observers as functions.

