## 2️⃣ Python Implementation

```python
# ------------------------------------------------------------
# di_container.py – Minimal Dependency Injection Container
# ------------------------------------------------------------

from typing import Callable, Any, TypeVar, Generic

T = TypeVar('T')

class DIContainer:
    """
    A simple dependency injection container.
    Supports registering either a concrete value or a callable factory.
    """

    def __init__(self):
        # name -> provider (either T or Callable[[], T])
        self._registry: dict[str, Any] = {}

    def register(self, name: str, provider: Any) -> None:
        """
        Register a dependency.

        * `provider` can be any concrete value (int, str, list…) **or**
          a callable that returns an instance when invoked with no arguments.
        """
        self._registry[name] = provider

    def get(self, name: str) -> T:
        """
        Resolve the dependency by name and return it as type‑checked `T`.

        Raises ``KeyError`` if no provider is registered for the given name.
        The first call to a factory caches the result internally.
        """
        provider = self._registry.get(name)
        if provider is None:
            raise KeyError(f"No provider found for '{name}'")

        # Cache mechanism – use a sentinel object to detect uninitialized value.
        _UNINITIALIZED = object()

        def resolve():
            nonlocal cached
            if cached is _UNINITIALIZED:
                raw_provider = provider  # could be T or Callable[[], T]
                if callable(raw_provider):
                    # Factory: call once and store the result
                    cached = raw_provider()
                else:
                    # Primitive value – assign directly
                    cached = raw_provider
            return cached

        from functools import lru_cache   # simple manual cache (no external deps)
        @lru_cache(maxsize=1)  # one‑shot caching per call to get()
        def _cached_get():
            return resolve()

        return _cached_get()  # returns T or raises KeyError if missing


# ------------------------------------------------------------
# Example usage ------------------------------------------------
if __name__ == "__main__":
    container = DIContainer()

    # Primitive values (singletons)
    container.register("apiKey", "mySuperSecretKey123")

    # Callable factories – lazy-loaded, memoised
    container.register(
        "logger",
        lambda: {
            "info": lambda msg: print(f"[LOG] {msg}"),
            "warn": lambda msg: print(f"[WARN] {msg}")
        }
    )

    # Class instances (instantiated each request)
    class DatabaseConfig:
        def __init__(self, host: str, port: int):
            self.host = host
            self.port = port

    container.register("dbConfig", lambda: DatabaseConfig("localhost", 5432))

    # Resolve dependencies
    api_key = container.get(str)                     # "mySuperSecretKey123"
    logger_obj = container.get(lambda: {})["logger"]()   # dict with info/warn
    db_cfg = container.get(DatabaseConfig)

    print(api_key)
    logger_obj.info("Application started")
    print(f"DB config – host={db_cfg.host}, port={db_cfg.port}")
```

**Key points**

* **Lazy initialization + caching** – the first call to `get` evaluates the factory; subsequent calls return instantly.
* **Type‑safe resolution** – Python’s type hints (`T`) let you request a specific type, and the implementation returns exactly that (or raises if missing).
* **No external DI libraries required** – pure standard library usage.

