## 1️⃣ TypeScript Implementation

```ts
// ---------------------------------------------------
// 1️⃣ Product – the complex object we want to construct
// ---------------------------------------------------
class Car {
    private engine: Engine | undefined;
    private wheels: Wheel[] | undefined;

    // Private constructor so clients can only use Builder
    private constructor() {}

    static create(): CarBuilder {
        return new CarBuilder();
    }

    // Fluent getters (optional – just for illustration)
    getEngine(): Engine | undefined { return this.engine; }
    getWheels(): Wheel[] | undefined { return this.wheels; }
}

// ---------------------------------------------------
// 2️⃣ Builder interface
// ---------------------------------------------------
interface Builder {
    buildCar(): Car;
    // Each step is declared explicitly – no “partial” builds allowed.
    setEngine(engine: Engine): this;
    addWheels(wheelCount: number): this;
}

// ---------------------------------------------------
// 3️⃣ Concrete Builders (optional variants)
// ---------------------------------------------------
class LuxuryCarBuilder implements Builder {
    private car = new Car();

    buildCar(): Car { return this.car; }
    setEngine(engine: Engine): this { 
        this.car.engine = engine; 
        return this;
    }

    // In a real product you might have more steps:
    addWheels(wheelCount: number): this {
        if (!this.car.wheels) this.car.wheels = [];
        for (let i = 0; i < wheelCount; ++i) this.car.wheels.push(new Wheel());
        return this;
    }
}

class MiniCarBuilder implements Builder {
    private car = new Car();

    buildCar(): Car { return this.car; }
    setEngine(engine: Engine): this { 
        this.car.engine = engine; 
        return this;
    }

    addWheels(wheelCount: number): this {
        if (!this.car.wheels) this.car.wheels = [];
        for (let i = 0; i < wheelCount; ++i) this.car.wheels.push(new Wheel());
        return this;
    }
}

// ---------------------------------------------------
// 4️⃣ Director – orchestrates the build process
// ---------------------------------------------------
class CarDirector {
    private builder: Builder;

    constructor(builder: Builder) { 
        this.builder = builder; 
    }

    construct(): Car {
        // Step‑by‑step construction using the concrete Builder
        return this.builder.buildCar();
    }
}

/* ---- Helper classes (just for demo) ---- */
class Engine {}
class Wheel {}

// ---------------------------------------------------
// Example usage:
const director = new CarDirector(CarBuilder.create());
director.construct();   // <-- all steps are called via Director

console.log('Car built:', director.getEngine(), director.getWheels());
```

**What each step does**

| Step | What happens |
|------|--------------|
| **1️⃣ Product** | `Car` is the final object we want to build. It contains an optional `engine` and a list of `wheels`. |
| **2️⃣ Builder interface** | Declares every method (`setEngine`, `addWheels`) that must be called in order, guaranteeing a *complete* product after each call. |
| **3️⃣ Concrete Builders** | `LuxuryCarBuilder` and `MiniCarBuilder` implement the same steps but produce different variants (e.g., more wheels). This shows extensibility without changing Director logic. |
| **4️⃣ Director** | Takes any Builder instance, calls its methods in a prescribed order (`buildCar()` finally returns the assembled product). The client never knows about concrete builder internals – only that it follows the Builder API. |

