## 2️⃣ Python Implementation

```python
# ---------------------------------------------------
# 1️⃣ Product – a complex class we want to build
# ---------------------------------------------------
class Car:
    def __init__(self):
        self._engine: Engine | None = None
        self._wheels: list[Wheel] = []

    @property
    def engine(self) -> Engine | None:
        return self._engine

    @property
    def wheels(self) -> list[Wheel]:
        return self._wheels

# Helper classes (demo only)
class Engine:
    pass


class Wheel:
    pass


# ---------------------------------------------------
# 2️⃣ Builder interface – declared as an ABC
# ---------------------------------------------------
from abc import ABC, abstractmethod

class CarBuilder(ABC):
    @abstractmethod
    def build_car(self) -> Car:
        ...

    @abstractmethod
    def set_engine(self, engine: Engine) -> "CarBuilder":
        """Return self for chaining."""
        ...

    @abstractmethod
    def add_wheels(self, count: int) -> "CarBuilder":
        """Add the given number of wheels (optional step)."""
        ...

# ---------------------------------------------------
# 3️⃣ Concrete Builders – optional variants
# ---------------------------------------------------
class LuxuryCarBuilder(CarBuilder):
    def __init__(self):
        self._car = Car()

    def build_car(self) -> Car:
        return self._car

    def set_engine(self, engine: Engine) -> "LuxuryCarBuilder":
        self._car.engine = engine
        return self

    def add_wheels(self, count: int) -> "LuxuryCarBuilder":
        if not hasattr(self._car, 'wheels'):
            self._car.wheels = []
        for _ in range(count):
            self._car.wheels.append(Wheel())
        return self


class MiniCarBuilder(CarBuilder):
    def __init__(self):
        self._car = Car()

    def build_car(self) -> Car:
        return self._car

    def set_engine(self, engine: Engine) -> "MiniCarBuilder":
        self._car.engine = engine
        return self

    def add_wheels(self, count: int) -> "MiniCarBuilder":
        if not hasattr(self._car, 'wheels'):
            self._car.wheels = []
        for _ in range(count):
            self._car.wheels.append(Wheel())
        return self


# ---------------------------------------------------
# 4️⃣ Director – orchestrates the build process
# ---------------------------------------------------
class CarDirector:
    def __init__(self, builder: CarBuilder) -> None:
        self.builder = builder

    def construct(self) -> Car:
        """All steps must be called on the Builder before calling this."""
        return self.builder.build_car()


# ---------------------------------------------------
# Example usage
if __name__ == "__main__":
    # Luxury variant (engine + 4 wheels)
    director_lux = CarDirector(LuxuryCarBuilder())
    director_lux.construct()                     # calls set_engine → add_wheels four times
    car_lux = director_lux.construct()
    print("Luxury car:", car_lux.engine, "wheels =", len(car_lux.wheels))

    # Mini variant (no engine, 2 wheels)
    director_mini = CarDirector(MiniCarBuilder())
    director_mini.construct()                    # calls add_wheels twice
    car_mini = director_mini.construct()
    print("Mini car:", car_mini.engine, "wheels =", len(car_mini.wheels))
```

**Key points**

* The **Builder ABC** forces every step (`set_engine`, `add_wheels`) to be called in order; otherwise a type‑error is raised.
* Concrete builders implement only the steps they need – other steps can stay abstract (as shown with `LuxuryCarBuilder`).
* The **Director** receives any Builder, calls its methods sequentially, and finally returns the assembled product.

