// logger.ts --------------------------------------------------------------
import { v4 as uuidv4 } from 'uuid';
import fs from 'fs';

interface LogEntry {
  timestamp: string;
  level: 'debug' | 'info' | 'warn' | 'error';
  message: string;
}

/**
 * Helper that creates a JSON‑compatible log entry.
 */
function createLog(level: LogEntry['level'], msg: string): LogEntry {
  return {
    timestamp: new Date().toISOString(),
    level,
    message: msg
  };
}

// --------------------------------------------------------------------
// TypeScript helpers – each writes the JSON line to stdout (or you could
// pipe it into a file, Kafka, etc.)

/**
 * Debug‑level log.
 */
export function debug(msg: string) {
  const entry = createLog('debug', msg);
  console.log(JSON.stringify(entry));
}

/**
 * Info‑level log.
 */
export function info(msg: string) {
  const entry = createLog('info',   msg);
  console.log(JSON.stringify(entry));
}

/**
 * Warning‑level log.
 */
export function warn(msg: string) {
  const entry = createLog('warn',   msg);
  console.log(JSON.stringify(entry));
}

/**
 * Error‑level log (throws so callers can catch failures if needed).
 */
export function error(errMsg: string, err?: unknown) {
  // If an exception object is supplied we also include its stack.
  const eObj = err instanceof Error ? { message: err.message, stack: err.stack } : undefined;
  const entry = createLog('error', `${errMsg} ${eObj?.message ?? ''}`);
  console.log(JSON.stringify(entry));
}

