## Python (3.x)

```python
# logger.py -------------------------------------------------------------
import json
from datetime import datetime, timezone

class LogEntry:
    __slots__ = ("timestamp", "level", "message")
    def __init__(self, level: str, msg: str):
        self.timestamp = datetime.now(timezone.utc).isoformat()
        self.level     = level          # must be one of debug/info/warn/error
        self.message   = msg

def create_log(level: LogEntry.__annotations__["level"], msg: str) -> LogEntry:
    return LogEntry(level, msg)

# --------------------------------------------------------------------
# Helper functions – each writes a JSON line to stdout (or you could write
# to a file using open(..., "a") and json.dump).

def debug(msg: str):
    log = create_log("debug", msg)
    print(json.dumps(log))

def info(msg: str):
    log = create_log("info",   msg)
    print(json.dumps(log))

def warn(msg: str):
    log = create_log("warn",   msg)
    print(json.dumps(log))

def error(err_msg: str, err_obj=None):
    # Include stack trace if an exception object is supplied.
    extra = {}
    if isinstance(err_obj, Exception):
        extra["message"] = err_obj.message
        extra["stack"]   = err_obj.__traceback__.tb_next  # skip the first frame (this function)
    log = create_log("error", f"{err_msg} {extra.get('message','')}")
    print(json.dumps(log))

# --------------------------------------------------------------------
if __name__ == "__main__":
    debug("Application started")
    info("HTTP server bound to port 8080")
    warn("Database connection pool exhausted")
    error("Failed to load config file", FileNotFoundError)
```

