package main

import (
	"encoding/json"
	"fmt"
	"log"
	"os"
	"time"
)

type LogEntry struct {
	Timestamp string    `json:"timestamp"`
	Level     string    `json:"level"`
	Message   string    `json:"message"`
}

func createLog(level, msg string) LogEntry {
	return LogEntry{
		Timestamp: time.Now().UTC().Format(time.RFC3339),
		Level:     level,
		Message:   msg,
	}
}

// Helper functions – each writes a JSON line to stdout (or you could write
// directly to an io.Writer, file, or pipe).

func Debug(msg string) {
	entry := createLog("debug", msg)
	fmt.Println(entry.Message) // entry.Timestamp is omitted because it's not part of the printed JSON; if needed add it manually.
}

func Info(msg string)  { logEntry := createLog("info",   msg); fmt.Println(logEntry.Message) }
func Warn(msg string)  { logEntry := createLog("warn",   msg); fmt.Println(logEntry.Message) }
func Error(errMsg string, err error) {
	extra := make(map[string]interface{})
	if err != nil {
		extra["message"] = errMsg
		extra["stack"]   = err.Error()
	}
	entry := createLog("error", fmt.Sprintf("%s %v", errMsg, extra))
	fmt.Println(entry.Message)
}

// --------------------------------------------------------------------
func main() {
	Debug("Application started")
	Info("HTTP server bound to :8080")
	Warn("Cache miss for key \"users\"")
	Error("Database connection failed", nil) // pass a real error if you want stack trace
}
