## 1️⃣ TypeScript (Node.js / modern browsers)

```ts
// tracing.ts ---------------------------------------------------------------
import { performance } from 'perf_hooks';

/**
 * `trace` returns a wrapper around the supplied function.
 * Every call prints:
 *
 *   [timestamp] <functionName> took <duration ms>
 */
export function trace<T extends (...args: any[]) => any>(
  fn: T,
): ReturnType<T> {
  const name = fn.name ?? '<anonymous>';
  return ((...args: Parameters<T>) =>
    new Promise((resolve, reject) => {
      const start = performance.now();
      fn(...args)
        .then(result => {
          console.log(`[${new Date().toISOString()}] ${name} took ${(performance.now() - start).toFixed(2)} ms`);
          resolve(result);
        })
        .catch(err => {
          console.error(`[${new Date().toISOString()}] ${name} failed:`, err);
          reject(err);
        });
    })) as T;
}
// -------------------------------------------------------------------------

// Example usage -----------------------------------------------------------
const expensive = trace(async (n: number) => {
  // simulate work
  await new Promise(r => setTimeout(r, Math.random() * 200));
  return n * n;
});

expensive(42).then(console.log);
```

**What it does**

* Uses `performance.now()` for high‑resolution timing.
* Returns a **new function** that wraps the original and logs:
  ```text
  [2025-08-21T12:34:56.789Z] expensive took 124.57 ms
  ```
* Works with async functions as well.

