import time
from datetime import datetime

def trace(func):
    """Decorator that logs the execution time of `func`."""
    name = func.__name__

    def wrapper(*args, **kwargs):
        start = time.perf_counter()
        result = func(*args, **kwargs)
        elapsed_ms = (time.perf_counter() - start) * 1000
        print(f"[{datetime.now().isoformat()}] {name} took {elapsed_ms:.2f} ms")
        return result

    # Preserve original metadata (optional but nice)
    wrapper.__name__ = func.__name__
    wrapper.__doc__ = func.__doc__
    return wrapper

# -------------------------------------------------------------------------

@trace
def compute_factorial(n: int) -> int:
    """Simple CPU‑heavy example."""
    if n == 0:
        return 1
    else:
        return n * compute_factorial(n - 1)

if __name__ == "__main__":
    print(compute_factorial(20))
```

**What it does**

* `time.perf_counter()` → high‑resolution timer.
* Prints a timestamped log line with the elapsed milliseconds.
* Works for both synchronous and async functions (see next language).

