  // trace is a function that returns a wrapped version of any func.
  func trace(fn interface{}) func(args ...interface{}) (result interface{}, err error) {
  	name := runtime.FuncForPC(reflect.ValueOf(fn).Pointer()).Name()
  
  	return func(args ...interface{}) (result interface{}, err error) {
  		start := time.Now()
  		defer func() { log.Printf("[%.6s] %s took %.2f ms", time.Now().Format("2006-01-02T15:04:05.000Z"), name, float64(time.Since(start))/time.Millisecond) }()
  		result, err = fn(args...)
  		return
  	}
  }
  
