// healthCheck.ts ---------------------------------------------------------
import express from 'express';
import { promisify } from 'util';

const app = express();
const PORT = process.env.PORT ?? 3000;

// Mock dependency status objects – replace with real checks in production.
interface DependencyStatus {
  name: string;
  healthy: boolean;
}

const dependencies: Record<string, DependencyStatus> = {
  db: { name: 'Database', healthy: true },
  cache: { name: 'Cache (Redis)', healthy: false }, // example of a failure
  queue: { name: 'Message Queue', healthy: true },
};

// Helper to format JSON response nicely.
const jsonRes = (body: any) => {
  app.get('/healthz', async (_req, res) => {
    const now = new Date().toISOString();
    // Build the health payload
    const payload = {
      status: dependencies.db.healthy ? 'UP' : 'DOWN',
      timestamp: now,
      dependencies: Object.fromEntries(
        Object.entries(dependencies).map(([name, info]) => [
          name,
          { ...info, healthy: info.healthy },
        ])
      ),
    };
    res.set('Content-Type', 'application/json');
    res.status(200).json(payload);
  });

  // Optional health‑check endpoint for external monitors
  app.get('/status', (_req, res) => {
    const payload = {
      status: dependencies.db.healthy ? 'UP' : 'DOWN',
      timestamp: new Date().toISOString(),
      dependencies: Object.fromEntries(
        Object.entries(dependencies).map(([name, info]) => [
          name,
          { ...info, healthy: info.healthy },
        ])
      ),
    };
    res.set('Content-Type', 'application/json');
    res.status(200).json(payload);
  });
});

app.listen(PORT, () => {
  console.log(`🟢 Health check service listening on http://localhost:${PORT}`);
});
```

