```ts
// monitor.ts
import { execSync } from 'child_process';
import * as os from 'os';

/**
 * Thresholds – adjust to your needs.
 */
const CPU_THRESHOLD   = 80; // % (exceeds this, alert)
const MEM_THRESHOLD   = 85; // % of total RAM used

/**
 * Helper: run a shell command and return its stdout trimmed.
 */
function exec(cmd: string): string {
  const result = execSync(cmd).toString().trim();
  if (!result) throw new Error(`Command "${cmd}" failed`);
  return result;
}

/**
 * Get CPU usage % (Linux/macOS only – uses `top -bn1`).
 * For Windows you could use `wmic cpu get LoadPercentage`.
 */
function getCpuUsage(): number {
  // Example: "text" output from top:
  const out = exec('top -bn1 | head -n5');
  // Look for a line that contains "%Cpu(s)" – the second column is CPU%
  const re = /.*\s+(\d+)%[CS]\s+/;
  const m = out.match(re);
  return m ? parseFloat(m[1]) : NaN;
}

/**
 * Get RAM usage % (Linux/macOS only – uses `free -m`).
 */
function getMemUsage(): number {
  // Example output: "total used free shared buffers cached"
  const out = exec('free -m | awk \'NR==2{printf "%.0f", $3*100/$2 }\'');
  return parseFloat(out);
}

/**
 * Main monitoring loop – runs forever, prints alert when thresholds are crossed.
 */
function monitor() {
  while (true) {
    const cpuPct = getCpuUsage();
    const memPct = getMemUsage();

    console.log(`🔎 CPU: ${cpuPct.toFixed(1)}% | MEM: ${memPct.toFixed(1)}%`);

    if (cpuPct > CPU_THRESHOLD || memPct > MEM_THRESHOLD) {
      console.warn(
        `⚠️ ALERT – CPU=${cpuPct}% exceeds ${CPU_THRESHOLD}%, or RAM=${memPct}% exceeds ${MEM_THRESHOLD}%`
      );
      // You could replace the `console.warn` with an email, Slack webhook,
      // systemd alert, etc. as needed.
    }

    // Sleep a short interval (seconds) – tune for how often you want checks.
    setTimeout(1000); // 1‑second delay; increase to once per minute if desired
  }
}

// Run the monitor when executed directly.
if (require.main === module) {
  try {
    monitor();
  } catch (e: any) {
    console.error('Error:', e.message);
  }
}
