```python
#!/usr/bin/env python3
"""
monitor.py – simple CPU & RAM usage monitor.
"""

import os
import subprocess
from typing import Tuple

# ------------------- Configurable thresholds -------------------
CPU_THRESHOLD   = 80.0   # percent (exceeds → alert)
MEM_THRESHOLD   = 85.0   # percent of total RAM used (exceeds → alert)

def run(cmd: str) -> str:
    """Run shell command and return trimmed stdout."""
    out = subprocess.check_output(cmd, stderr=subprocess.STDOUT).decode().strip()
    if not out:
        raise RuntimeError(f"Command '{cmd}' returned empty output")
    return out

# -----------------------------------------------------------

def get_cpu_usage_percent() -> float:
    """
    Returns CPU usage % (Linux/macOS only).
    Uses `top -bn1 | awk` – similar to the Node.js version.
    """
    top_out = run("top -bn1 | head -n5")
    # Example line: "Cpu(s): 12.3%us  2.4%sy  0.0%ni 85.0%id ..."
    for line in top_out.splitlines():
        if "%Cpu" in line:
            parts = line.split()
            # Look for the first numeric value followed by a '%' that isn't "us", "sy", etc.
            cpu_line = next((float(p) for p in parts if p.endswith('%')), None)
            return float(cpu_line) if cpu_line else 0.0
    raise RuntimeError("Could not locate CPU usage line")

def get_mem_usage_percent() -> float:
    """
    Returns RAM used as a percentage of total memory.
    Uses `free -m` and extracts the second column (used MB).
    """
    free_out = run("free -m | awk 'NR==2 {print $3}'")
    try:
        return float(free_out)
    except ValueError:
        raise RuntimeError("Failed to parse RAM usage")

def monitor():
    while True:
        cpu_pct   = get_cpu_usage_percent()
        mem_used  = get_mem_usage_percent()          # MB used
        total_mem_mb = os.sysconf('SC_PAGE_SIZE') * os.sysconf('SC_PHYS_PAGES') / (1024*1024)
        mem_pct   = (mem_used / total_mem_mb) * 100

        print(f"🔎 CPU: {cpu_pct:.1f}% | MEM: {mem_used:.0f}MiB used ({mem_pct:.1f}% of total)")

        if cpu_pct > CPU_THRESHOLD or mem_pct > MEM_THRESHOLD:
            alert = "⚠️ ALERT – "
            if cpu_pct > CPU_THRESHOLD:
                alert += f"CPU={cpu_pct:.1f}% (threshold {CPU_THRESHOLD}%)"
            if mem_pct > MEM_THRESHOLD:
                alert += (" and RAM usage is also high")
            print(alert)

        # Sleep a bit – adjust as needed
        import time; time.sleep(1)   # 1‑second interval

if __name__ == "__main__":
    monitor()
```

