## 3️⃣ Go (`monitor.go`)

```go
package main

import (
	"bufio"
	"fmt"
	"io/ioutil"
	"os"
	"strconv"
	"strings"
	"time"
)

const (
	cpuThreshold   = 80.0 // percent
	memThreshold   = 85.0 // percent of total RAM used
	checkInterval  = time.Second * 1 // sleep interval between checks
)

// -----------------------------------------------------------

func getCpuUsage() (float64, error) {
	out, err := ioutil.ReadFile("/proc/stat")
	if err != nil {
		return 0, fmt.Errorf("read /proc/stat: %w", err)
	}
	lines := strings.Split(string(out), "\n")

	var idle float64
	var total float64
	for _, line := range lines[:4] { // first few lines contain CPU info
		parts := strings.Fields(line)
		if len(parts) >= 5 && parts[0] == "cpu" {
			total = 0.0
			idle = 0.0
			for i := 1; i < len(parts); i++ {
				v, err := strconv.ParseFloat(parts[i], 64)
				if err != nil {
					continue
				}
				total += v
				if parts[i] == "idle" {
					idle = v
				}
			}
			cpuPct := (total - idle) / total * 100.0
			return cpuPct, nil
		}
	}

	return 0, fmt.Errorf("no CPU usage line found")
}

func getMemUsage() (float64, error) {
	out, err := ioutil.ReadFile("/proc/meminfo")
	if err != nil {
		return 0, fmt.Errorf("read /proc/meminfo: %w", err)
	}
	lines := strings.Split(string(out), "\n")

	var totalMB float64
	var usedMB float64
	for _, line := range lines {
		parts := strings.Fields(line)
		if len(parts) < 2 {
			continue
		}
		val, err := strconv.ParseFloat(strings.TrimSpace(parts[0]), 64)
		if err != nil {
			continue
		}
		unit := parts[1]
		switch unit {
		case "kB":
			totalMB += val / 1024.0
			break
		case "MB":
			totalMB = val
			break
		default:
			continue // unknown format – ignore for simplicity
		}

		if len(parts) >= 3 && parts[1] == "MemAvailable:" {
			val, err := strconv.ParseFloat(strings.TrimSpace(parts[2]), 64)
			if err != nil {
				continue
			}
			if unit := strings.TrimSuffix(parts[3], "kB"); unit == "MB" {
				usedMB = val - val/1024.0 // approximate used (total - available)
			} else if unit == "GB" {
				usedMB = val / 1024.0
			}
		}
	}

	if totalMB <= 0 || usedMB < 0 {
		return 0, fmt.Errorf("failed to parse memory info")
	}
	memPct := (usedMB / totalMB) * 100.0
	return memPct, nil
}

// -----------------------------------------------------------

func alert(msg string) {
	fmt.Printf("\x1b[31m⚠️ ALERT – %s\x1b[0m\n", msg)
	// In a real system you might send an email/webhook here.
}

func monitor() {
	for {
		cpuPct, err := getCpuUsage()
		if err != nil {
			fmt.Printf("error getting CPU: %v\n", err)
			time.Sleep(checkInterval)
			continue
		}
		memPct, err := getMemUsage()
		if err != nil {
			fmt.Printf("error getting memory: %v\n", err)
			time.Sleep(checkInterval)
			continue
		}

		fmt.Printf("🔎 CPU: %.1f%% | MEM: %.0fMiB used (%.1f%% of total)\n",
			cpuPct, memPct/100*os.GetMemStats().Total, memPct)

		if cpuPct > cpuThreshold || memPct > memThreshold {
			alert(fmt.Sprintf("CPU=%g%% (threshold %g%%), or RAM=%.0fMiB used (threshold %.0fMiB)",
				cpuPct, cpuThreshold, memPct/100*os.GetMemStats().Total, memThreshold))
		}

		time.Sleep(checkInterval)
	}
}

func main() {
	if err := monitor(); err != nil {
		fmt.Printf("monitor exited with error: %v\n", err)
		os.Exit(1)
	}
}
```

