```bash
#!/usr/bin/env bash
# monitor.sh – simple CPU & RAM usage monitor for Linux/macOS.

CPU_THRESHOLD=80   # percent
MEM_THRESHOLD=85   # percent of total RAM used
INTERVAL=1         # seconds between checks

function get_cpu_usage() {
  # top -bn1 | awk '{print $10}' gives "%Cpu(s)"
  cpu=$(top -bn1 | awk '/%Cpu\(s\):/ {print $10; exit}')
  echo "${cpu%%.*}"
}

function get_mem_used_mb() {
  # free -m prints "Mem:" line, second column is used MB.
  mem_used=$(free -m | awk 'NR==2 {print $3}')
  echo "$mem_used"
}

while true; do
  cpu_pct=$(get_cpu_usage)
  mem_used=$(get_mem_used_mb)

  total_kb=$(grep MemTotal /proc/meminfo | awk '{print $2}')
  total_mb=$((total_kb/1024))
  mem_pct=$(awk "BEGIN {printf \"%.1f\", ($mem_used/$total_mb)*100}")
  echo -n "🔎 CPU: ${cpu_pct}%% | MEM: ${mem_used}MiB used ("
  echo "${mem_pct}% of total) "

  if (( $(echo "$cpu_pct > $CPU_THRESHOLD" | bc -l) )) || \
     (( $(echo "$mem_pct > $MEM_THRESHOLD" | bc -l) )); then
    alert="⚠️ ALERT – CPU=${cpu_pct}%% (threshold ${CPU_THRESHOLD}%) or RAM=${mem_used}MiB used (${mem_pct}% of total)"
    echo -e "\x1b[31m${alert}\x1b[0m"
  fi

  sleep "$INTERVAL"
done
```

