## 1️⃣ TypeScript implementation

```ts
/**
 * SlidingWindowMetrics – aggregates count, sum, min, max and avg over a fixed‑size sliding window.
 *
 * @template T The type of values being aggregated. Must be comparable (≤ ≥) for min/max,
 *            numeric for addition/subtraction used in average.
 */
export class SlidingWindowMetrics<T> {
  /** Maximum size of the sliding window – once exceeded, oldest items are dropped. */
  private readonly maxSize: number;

  /** Circular buffer holding the values currently inside the window. */
  private readonly buffer: T[];

  /** Running total (used for avg). */
  private total: number | bigint = BigInt(0);

  /** Current number of elements in the window – always ≤ maxSize. */
  private count: number = 0;

  /** Minimum value ever seen inside the window. */
  private min?: T;

  /** Maximum value ever seen inside the window. */
  private max?: T;

  /**
   * Create a new sliding‑window aggregator.
   *
   * @param maxSize – maximum number of items to keep in the buffer (the “window size”).
   */
  constructor(maxSize: number) {
    if (maxSize <= 0) throw new Error('maxSize must be > 0');
    this.maxSize = maxSize;
    this.buffer = [];
  }

  /** Add a single value to the window. */
  public add(value: T): void {
    // ---- update circular buffer -------------------------------------------------
    const idx = this.count % this.maxSize;          // where we would insert next
    this.buffer[idx] = value;

    // ---- numeric aggregates ----------------------------------------------------
    if (this.count === 0) {
      // first element → set min / max and total
      this.min = value;
      this.max = value;
      this.total = BigInt(value);
    } else {
      const v = Number(value);   // works for numbers; for bigint use `value as unknown as bigint`
      this.total += BigInt(v);

      if (v < Number(this.min!)) this.min = value;
      if (v > Number(this.max!)) this.max = value;
    }

    // ---- keep count up‑to‑date ----------------------------------------------------
    ++this.count;

    // ---- enforce window size – drop oldest element and adjust aggregates ----------
    if (this.count > this.maxSize) {
      const removedIdx = (idx - 1 + this.maxSize) % this.maxSize; // previous index
      const removed = this.buffer[removedIdx];

      // Remove total contribution of the removed item
      this.total -= BigInt(Number(removed));

      // If that removed item was the current min or max, recompute them from buffer.
      if (Number(this.min!) === Number(removed)) {
        let newMin = value;   // start with most recent element as candidate
        for (const v of this.buffer) {
          const n = Number(v);
          if (n < Number(newMin!)) newMin = v;
        }
