## 1️⃣ TypeScript (Node.js)

```ts
// wal.ts --------------------------------------------------------------
import { promises as fs } from 'fs';
import path from 'path';

export interface LogEntry {
    timestamp: Date;
    operationId: string;   // e.g. UUID or monotonically increasing index
    payload?: any;         // whatever you need to replay (JSON‑serialisable)
}

// ---------------------------------------------------------------
const WAL_PATH = path.resolve(__dirname, 'log.txt');

/**
 * Append a new entry.
 *
 * @param payload – anything serialisable as JSON (or plain string)
 */
export async function append(payload: unknown): Promise<void> {
    const id = `${Date.now()}-${Math.random().toString(36).substring(2)}`;
    const entry: LogEntry = {
        timestamp: new Date(),
        operationId: id,
        payload
    };
    // Write as JSON line – easy to read back later.
    await fs.appendFile(WAL_PATH, JSON.stringify(entry) + '\n');
}

/**
 * Replay the log from disk. Returns an array of LogEntry objects in order.
 *
 * @throws if file cannot be opened or parsed.
 */
export async function replay(): Promise<LogEntry[]> {
    const lines = await fs.readFile(WAL_PATH, 'utf8');
    // Split on newline – ignore empty trailing line
    return (lines.trim().split('\n') as string[])
        .map((line) => JSON.parse(line))
        .filter(Boolean);
}
// -----------------------------------------------------------------
```

**Usage**

```ts
import { append, replay } from './wal';

async function demo() {
    await append({ type: 'createUser', userId: '123' });
    await append({ type: 'updatePassword', userId: '123', oldHash: '…' });

    const log = await replay();
    console.log('Replayed WAL →', log);
}

demo().catch(console.error);
```

**Key points**

* **Immutable**: each call appends a newline‑separated JSON line.
* **Deterministic order**: `append` always adds at the end, so replay is just reading sequentially.
* No explicit transaction log; if you need durability across crashes you can sync after every write (`await fs.appendFile(...).then(fs.fsync)`).

