## 2️⃣ Python

```python
# wal.py --------------------------------------------------------------
import json
from pathlib import Path
from datetime import datetime

WAL_PATH = Path(__file__).parent / "log.txt"

def append(payload: dict) -> None:
    """
    Append a JSON‑serialisable dictionary to the WAL.
    The payload can be any serialisable object (dict, list, scalar).
    """
    entry_id = f"{datetime.utcnow().isoformat()}_{int(1000*hash(str(datetime.now())) % 1e6)}"
    entry = {
        "timestamp": datetime.utcnow(),
        "operationId": entry_id,
        "payload": payload
    }
    # Write as a single JSON line.
    with WAL_PATH.open("a", encoding="utf-8") as f:
        f.write(json.dumps(entry) + "\n")
        # Optional: os.sync() for extra durability (not required by spec)

def replay() -> list[dict]:
    """
    Read the whole file, parse each JSON line and return a list of entries.
    The order is guaranteed because we read sequentially from disk.
    """
    lines = WAL_PATH.read_text(encoding="utf-8").splitlines()
    # Strip empty trailing line if any
    return [json.loads(line) for line in lines if line.strip()]
```

**Usage**

```python
from wal import append, replay

