// wal.go --------------------------------------------------------------
package main

import (
	"encoding/json"
	"fmt"
	"io/ioutil"
	"os"
	"path/filepath"
	"time"

	logEntry struct {
		Timestamp time.Time `json:"timestamp"`
		ID        string    `json:"operationId"`
		Payload   interface{}`json:"payload,omitempty"` // can be any Go type
	}
)

const walPath = "log.txt"

// Append a new entry.
func Append(payload interface{}) error {
	id := fmt.Sprintf("%s_%d", time.Now().UTC().Format(time.RFC3339Nano), hash(payload))
	entry := logEntry{
		Timestamp: time.Now(),
		ID:        id,
		Payload:   payload,
	}
	data, err := json.Marshal(entry)
	if err != nil {
		return fmt.Errorf("marshal entry: %w", err)
	}
	data = append(data, '\n')
	return ioutil.WriteFile(walPath, data, 0o600) // mode rw‑r-----
}

// Replay returns all entries in order.
func Replay() ([]logEntry, error) {
	bts, err := ioutil.ReadFile(walPath)
	if os.IsNotExist(err) {
		return nil, nil
	}
	if err != nil {
		return nil, fmt.Errorf("read file: %w", err)
	}
	lines := bytes.Split(bts, []byte{'\n'})
	var entries []logEntry
	for _, line := range lines {
		if len(line) == 0 {
			continue // skip empty trailing line
		}
		var e logEntry
		if err := json.Unmarshal(line, &e); err != nil {
			return nil, fmt.Errorf("parse entry: %w", err)
		}
		entries = append(entries, e)
	}
	return entries, nil
}

// Helper – simple integer hash for demo purposes.
func hash(v interface{}) uint64 {
	switch vv := v.(type) {
	case string:
		return uint64(len(vv))
	case int:
		return uint64(vv)
	default:
		b := make([]byte, 32)
		json.MarshalToSafely(vv, b[:0])
		return binary.BigEndian.Uint64(b)
	}
}

// -----------------------------------------------------------------
