// ------------------------------------------------------------
// VectorClock.ts – minimal vector‑clock implementation
// ------------------------------------------------------------

/**
 * A single node identifier.
 */
type NodeId = string;

/**
 * The vector clock itself: a map from NodeId → integer timestamp.
 */
export type VectorClock = Record<NodeId, number>;

/**
 * Increment the counter for a given node and return the updated clock.
 *
 * @param vc – current vector clock
 * @param nodeId – identifier of the node that performed the event
 */
function increment(vc: VectorClock, nodeId: NodeId): VectorClock {
  // If we have never seen this node before, start at 0 then +1.
  if (!(nodeId in vc)) {
    return { ...vc, [nodeId]: 1 };
  }
  // Otherwise bump the existing counter.
  return { ...vc, [nodeId]: vc[nodeId]! + 1 };
}

/**
 * Compare two vector clocks to decide “happened‑before” relationships.
 *
 * Returns:
 *   true  – clockA happened before clockB
 *   false – either they are concurrent or clockB happened before A
 */
function happensBefore(clockA: VectorClock, clockB: VectorClock): boolean {
  // For every node in B we must have seen it at least as often (or more)
  // and there must be at least one node where B is strictly ahead.
  for (const [node, bVal] of Object.entries(clockB)) {
    const aVal = clockA[node];
    if (aVal === undefined) return false;               // A never saw this node
    if (bVal > aVal) continue;                         // B > A → not happened‑before yet
    // If we reach here, either they are equal or B <= A.
  }
  // The loop finished without finding any violation → clockA < clockB.
  return true;
}

/**
 * Merge two vector clocks: the maximum value for each node is taken.
 *
 * @param a – first vector clock
 * @param b – second vector clock
 */
function merge(a: VectorClock, b: VectorClock): VectorClock {
  const result: Record<NodeId, number> = {};
  // Union of all nodes present in either clock.
  for (const [node, val] of Object.entries({ ...a, ...b })) {
    result[node] = Math.max((a as any)[node] || 0, (b as any)[node] || 0);
  }
  return result;
}

// ------------------------------------------------------------
// Example usage
// ------------------------------------------------------------

if (require.main === module) {
  // Simulate a tiny gossip protocol:
  const nodes: NodeId[] = ['A', 'B', 'C'];

  let vcA = increment({}, nodes[0]);   // A's first event → {A:1}
  console.log('After A:', vcA);

  vcA = increment(vcA, nodes[0]);      // second event from A → {A:2}
  console.log('After another A:', vcA);

  const clockB = increment({}, nodes[1]);   // B's first event → {B:1}
  console.log('After B:', clockB);

  // Gossip round‑trip:
  const mergedAB = merge(vcA, clockB);
  console.log('Merge(A,B):', mergedAB);     // A still ahead of B

  const mergedBA = merge(clockB, vcA);
  console.log('Merge(B,A):', mergedBA);    // Concurrency – neither happened‑before the other
}

// ------------------------------------------------------------
// Exported API (so it can be imported elsewhere)
// ------------------------------------------------------------

export {
  VectorClock,
  increment,
  happensBefore,
  merge,
};
