  NodeId = str   # simple string identifier for a node
  
  
  def increment(vc: Dict[NodeId, int], node_id: NodeId) -> Dict[NodeId, int]:
      """
      Increment the counter for *node_id* and return the updated clock.
  
      If the node is not present yet we start at 1.
      """
      vc = dict(vc)                     # make a mutable copy
      if node_id in vc:
          vc[node_id] += 1
      else:
          vc[node_id] = 1
      return vc
  
  
  def happens_before(clock_a: Dict[NodeId, int],
                     clock_b: Dict[NodeId, int]) -> bool:
      """
      Return True iff *clock_a* happened before *clock_b*.
  
      The rule is:
        - For every node that appears in B we must have seen it at least as often,
          and there must be **at least one** node where B's count is strictly larger.
      """
      for nid, b_val in clock_b.items():
          a_val = clock_a.get(nid)
          if a_val is None:                     # A never saw this node → not happened‑before
              return False
          if b_val > a_val:
              continue                         # B's count higher → still possible but need more checks
      # If we get here, every comparison passed; therefore clock_a < clock_b.
      return True
  
  
  def merge(clock_a: Dict[NodeId, int],
            clock_b: Dict[NodeId, int]) -> Dict[NodeId, int]:
      """
      Merge two vector clocks by taking the maximum value for each node.
  
      This operation is commutative and idempotent – it satisfies the
      *convergence* property required for distributed causal tracking.
      """
      result = {}
      # Union of all nodes present in either clock
      all_nids = set(clock_a.keys()) | set(clock_b.keys())
      for nid in all_nids:
          a_val = clock_a.get(nid, 0)
          b_val = clock_b.get(nid, 0)
          result[nid] = max(a_val, b_val)
      return result
  
  
  # ------------------------------------------------------------
  # Simple demonstration (can be run as a script or imported elsewhere)
  # ------------------------------------------------------------
  
  if __name__ == "__main__":
      # Example gossip protocol using the three nodes A, B, C
      vc_a = increment({}, "A")          # { 'A': 1 }
      print("After A:", vc_a)
  
      vc_b = increment(vc_a, "B")        # { 'A': 2, 'B': 1 } – node B sees A's event once before its own
      print("After B (from A):", vc_b)
  
      vc_c = increment({}, "C")          # { 'C': 1 }
      print("After C:", vc_c)
  
      # Merge two clocks that have seen each other’s events
      merged_ab = merge(vc_a, vc_b)
      print("Merge(A,B):", merged_ab)   # A still ahead of B
  
      # Compare two clocks for happened‑before relationship
      before = happens_before(merged_ab, vc_c)
      after  = happens_before(vc_c, merged_ab)
  
      print(f"Is {vc_a} < {vc_b}? → {before}")
      print(f"Is {vc_c} < {vc_a}? → {after}")
  
