     * Starts a two‑phase commit for the given transaction `payload`.
     *
     * Returns a Promise that resolves to an object:
     *   { success: true, details?: any }  – on successful commit
     *   { success: false, error: string } – on abort or failure
     */
    async run(payload: T): Promise<{ success: boolean; details?: T }> {
        // ---- PHASE 1: PREPARE -------------------------------------------------
        const preparePromises = Object.values(this.participants).map(p => this.prepare(p.id));
        const preparedResults = await Promise.all(preparePromises);

        if (preparedResults.some(r => !r.ready)) {
            // At least one participant said NO → abort everything
