import asyncio
from typing import Any, Dict, Tuple

class Participant:
    """Abstract base for a two‑phase commit participant."""
    def __init__(self, pid: str):
        self.id = pid

    async def prepare(self) -> bool:
        raise NotImplementedError

    async def commit(self, payload: Any) -> None:
        raise NotImplementedError


# -----------------------------------------------------------------
# Simple in‑memory worker that stores a “committed” flag
# -----------------------------------------------------------------
class Worker(Participant):
    """Worker holds a dict to simulate DB persistence."""
    def __init__(self, pid: str):
        super().__init__(pid)
        self.db = {}   # placeholder for actual storage

    async def prepare(self) -> bool:
        print(f"[Worker] PREPARE received")
        return True          # always ready in this demo

    async def commit(self, payload: Any) -> None:
        print(f"[Worker] COMMIT called with {payload}")
        self.db[payload['id']] = {'status': 'committed'}


# -----------------------------------------------------------------
# Coordinator orchestrates the 2PC flow
# -----------------------------------------------------------------
class Coordinator:
    """Coordinator runs a two‑phase commit across any participants."""
    def __init__(self, participants: Dict[str, Participant]):
        self.participants = {p.id: p for p in participants}

    async def run(self, payload: Any) -> Tuple[bool, dict]:
        # ---- Phase 1 – PREPARE -------------------------------------------------
        prepare_tasks = [participant.prepare() for participant in self.participants.values()]
        prepared_results = await asyncio.gather(*prepare_tasks)

        if any(not ready for ready in prepared_results):
            print("[Coordinator] Transaction aborted (any NO)")
            return False, {}

        # ---- Phase 2 – COMMIT -------------------------------------------------
        commit_tasks = [participant.commit(payload) for participant in self.participants.values()]
        await asyncio.gather(*commit_tasks)

        print("[Coordinator] Transaction successfully committed")
        return True, payload


# -----------------------------------------------------------------
# Example usage (async main)
# -----------------------------------------------------------------
async def main():
    # ---------- Worker implementation -----------------------------------
    worker1 = Worker('worker-1')
    
    # In a real system you could have more workers:
    # workers = [Worker('worker-2'), Worker('worker-3')]
    
    coordinator = Coordinator([worker1])
    
    # ---------- Transaction payload --------------------------------------
    tx: Dict[str, Any] = {
        'id':   'txn-001',
        'from': 'Alice',
        'to':   'Bob',
        'amount': 150,
    }
    
    try:
        success, details = await coordinator.run(tx)
        print("Result:", {"success": success})
    except Exception as exc:
        print("Transaction aborted!", exc)

# Run the example
if __name__ == "__main__":
    asyncio.run(main())
