  # Coordinator orchestrates the 2PC flow
  # -----------------------------------------------------------------
  class Coordinator:
      """Coordinator runs a two‑phase commit across any participants."""
      def __init__(self, participants: Dict[str, Participant]):
          self.participants = {p.id: p for p in participants}
  
