          # ---- Phase 1 – PREPARE -------------------------------------------------
          prepare_tasks = [participant.prepare() for participant in self.participants.values()]
          prepared_results = await asyncio.gather(*prepare_tasks)
  
          if any(not ready for ready in prepared_results):
              print("[Coordinator] Transaction aborted (any NO)")
              return False, {}
  
          # ---- Phase 2 – COMMIT -------------------------------------------------
          commit_tasks = [participant.commit(payload) for participant in self.participants.values()]
          await asyncio.gather(*commit_tasks)
  
          print("[Coordinator] Transaction successfully committed")
