## 1️⃣ TypeScript (Node.js)

```ts
// file: openai-stream.ts
import { RequestInit, Response } from "node-fetch";

/**
 * Streams the OpenAI LLM completion token‑by‑token.
 *
 * @param model   The model identifier (e.g., `gpt-4o-mini`).
 * @param prompt  Prompt text to send.
 * @param opts    Optional request options (headers, body, timeout …)
 */
export async function* streamCompletion(
  model: string,
  prompt: string,
  init?: RequestInit
): AsyncGenerator<string> {
  const url = new URL("https://api.openai.com/v1/chat/completions");
  url.searchParams.set("model", model);
  // For streaming we send an empty `choices` array – the API will still return a stream of `"content"` chunks.
  init ??= { method: "POST", headers: {} };
  if (init.headers) {
    init.headers["Authorization"] = `Bearer ${process.env.OPENAI_API_KEY}`;
    init.headers["Content-Type"] = "application/json";
  } else {
    init.headers = {
      Authorization: `Bearer ${process.env.OPENAI_API_KEY}`,
      "Content-Type": "application/json",
    };
  }
  const body = JSON.stringify({
    model,
    messages: [{ role: "user", content: prompt }],
    // Empty choices makes the API return only streaming chunks.
    choices: [],
  });
  init.body = body;

  const response = await fetch(url, init);
  if (!response.ok) {
    throw new Error(`OpenAI error ${response.status}: ${await response.text()}`);
  }

  // The OpenAI streaming spec returns a JSON object with a top‑level `"choices"` array.
  // Each element of that array contains an empty `"index"` and a `"content"` string for every token.
  const reader = new ResponseStream(response);
  let chunk: string | null;
  while ((chunk = await reader.read()) !== null) {
    try {
      const jsonChunk = JSON.parse(chunk);
      // The streaming chunks are stored under the top‑level key "content".
      if (jsonChunk.content && typeof jsonChunk.content === "string") {
        yield jsonChunk.content;   // <-- token by token
      }
    } catch (_) {
      // In case of malformed chunk we just ignore it.
    }
  }
}

/**
 * Tiny wrapper around a Node.js Response that yields its body as strings.
 */
class ResponseStream implements AsyncIterable<string> {
  private readonly _response: Response;

  constructor(response: Response) {
    this._response = response;
  }

  async *[Symbol.asyncIterator]() {
    const reader = this._response.body?.getReader();
    if (!reader) throw new Error("No readable stream available");
    const decoder = new TextDecoder();

    while (true) {
      const { done, value } = await reader.read();
      if (done) break;
      // Each chunk is a UTF‑8 string.
      yield decoder.decode(value);
    }
  }

  async read(): Promise<string | null> {
    try {
      return (await this[Symbol.asyncIterator]()).next().value;
    } catch (_) {
      return null; // end of stream
    }
  }
}
```

