## 2️⃣ Python

```python
# file: openai_stream.py
import os
import json
from typing import AsyncGenerator, Iterator, Optional

import requests

OPENAI_API_KEY = os.getenv("OPENAI_API_KEY")
if OPENAI_API_KEY is None:
    raise RuntimeError("Set the OPENAI_API_KEY environment variable")

def stream_completion(
    model: str,
    prompt: str,
) -> Iterator[str]:
    """
    Generator that streams OpenAI LLM completion tokens one‑by‑one.

    Parameters
    ----------
    model : str
        Model identifier (e.g., "gpt-4o-mini").
    prompt : str
        Prompt text to send.

    Yields
    ------
    str :
        A single token from the streaming response.
    """
    url = "https://api.openai.com/v1/chat/completions"
    payload = {
        "model": model,
        "messages": [{"role": "user", "content": prompt}],
        # Empty choices disables the final JSON wrapper and returns only content chunks.
        "choices": [],
    }

    headers = {
        "Authorization": f"Bearer {OPENAI_API_KEY}",
        "Content-Type": "application/json",
    }
    response = requests.post(url, json=payload, headers=headers)
    response.raise_for_status()

    # The streaming spec returns a JSON object with top‑level key `"content"` for each token.
    resp_iter: Iterator[dict] = iter(response.json().get("choices", []))
    for chunk in resp_iter:
        if isinstance(chunk, dict) and "content" in chunk:
            yield chunk["content"]   # <-- one token per iteration
```

