## 3️⃣ Go

```go
// file: openai_stream.go
package main

import (
	"bytes"
	"context"
	"encoding/json"
	"fmt"
	"io"
	"net/http"

	"golang.org/x/net/context/ctxhttp" // for streaming client transport
)

const (
	openAIBaseURL = "https://api.openai.com/v1/chat/completions"
)

// StreamCompletion returns a channel that receives individual tokens (strings)
// from the OpenAI LLM completion stream.
func StreamCompletion(model, prompt string) <-chan string {
	ch := make(chan string, 10) // bounded buffer – adjust as needed

	go func() {
		defer close(ch)

		ctx, cancel := context.WithCancel(context.Background())
		defer cancel()

		payload := struct {
			Model        string   `json:"model"`
			Messages     []struct{ Role, Content string } `json:"messages"`
			Choices      []      `json:"choices"`         // empty disables final wrapper
		}{
			Model: model,
			Messages: []struct{ Role, Content string }{
				{"user", prompt},
			},
			Choices: nil,
		}

		body, err := json.Marshal(payload)
		if err != nil {
			ch <- ""
			return // malformed payload – abort
		}

		req, err := http.NewRequest(http.MethodPost, openAIBaseURL, bytes.NewBuffer(body))
		if err != nil {
			ch <- ""
			return
		}
		req.Header.Set("Authorization", "Bearer "+os.Getenv("OPENAI_API_KEY"))
		req.Header.Set("Content-Type", "application/json")

		resp, err := ctxhttp.Get(ctx, req)
		if err != nil {
			ch <- ""
			return
		}
		defer resp.Body.Close()

		if resp.StatusCode != http.StatusOK {
			ch <- fmt.Sprintf("OpenAI error %d: %s", resp.StatusCode, resp.Status)
			return
		}

		// The streaming spec returns a JSON object with top‑level key "content"
		var outer struct {
			Choices []struct{ Index int `json:"index"` } `json:"choices"`
		}
		if err := json.NewDecoder(resp.Body).Decode(&outer); err != nil {
			ch <- fmt.Sprintf("JSON decode error: %v", err)
			return
		}

		for _, elem := range outer.Choices {
			if content, ok := elem.Index.(int); ok && content == 0 { // first element of each chunk
				var token struct {
					Content string `json:"content"`
				}
				if err := json.NewDecoder(bytes.NewReader([]byte(fmt.Sprintf(`"%s"`, resp.Body.(*chunkReader).buf)))) /* simplified */; err != nil {
					ch <- ""
					return
				} else if ok, _ := json.Unmarshal([]byte(token.Content), &token); !ok {
					ch <- ""
					return
				} else {
					ch <- token.Content // <-- one token per iteration
				}
			}
		}

	}()
	return ch
}

// Helper type to read the body in chunks (used internally by StreamCompletion)
type chunkReader struct{ buf string }

func (cr *chunkReader) Read(p []byte) (int, error) {
	n := copy(p, cr.buf)
	cr.buf = cr.buf[n:]
	if n == 0 {
		return 0, io.EOF
	}
	return n, nil
}

// --------------------------------------------------------------------
// Example usage (run as a standalone program)

func main() {
	model := "gpt-4o-mini"
	prompt := `Explain the difference between a synchronous and an asynchronous function in JavaScript.`

	ch := StreamCompletion(model, prompt)
	for token := range ch {
		fmt.Println(token) // each line = one token
	}
}
```

**Explanation**

* The request body contains `{ "model": "...", "messages": [{...}], "choices": [] }`. This disables the outer `"choices"` array and forces OpenAI to stream only `"content"` chunks.
* We use `ctxhttp.Get` with a context so we can cancel if needed; the underlying transport is an HTTP client that reads in small buffers (`chunkReader`).
* Each chunk (a UTF‑8 string) is yielded via the channel. The consumer can treat each element as a single token.
* No external libraries beyond Go’s standard `net/http`, `encoding/json`, and `golang.org/x/net/context/ctxhttp` are required.

