/**
 * Cosine similarity between two vectors.
 *
 * @param v1 First vector (array of numbers)
 * @param v2 Second vector (array of numbers) – must be the same length as v1
 * @returns cosine similarity ∈ [-1, 1]
 */
function cosineSimilarity(v1: number[], v2: number[]): number {
  if (v1.length !== v2.length) {
    throw new Error('Vectors must have the same dimension');
  }

  const dot = v1.reduce((sum, x, i) => sum + x * v2[i], 0);
  const normV1 = Math.hypot(...v1);          // √(Σx²)
  const normV2 = Math.hypot(...v2);

  if (normV1 === 0 || normV2 === 0) {
    return 0; // undefined similarity when one vector is zero‑vector
  }

  return dot / (normV1 * normV2);
}

