// ---------------------------------------------------
// registry.ts – Tool Registry for Node / TS projects
// ---------------------------------------------------
import { ArgumentParser } from 'argparse';

/** Helper: JSON‑encode a value safely */
function safeJSON(value: any): string {
  try {
    return JSON.stringify(value);
  } catch (e) {
    throw new Error(`Cannot serialize ${value}`);
  }
}

/**
 * Registry entry – name → function + optional help.
 *
 * The functions must accept:
 *   - `args` : parsed CLI arguments (or a plain object)
 *   - `opts` : extra JSON‑encoded options supplied by the caller
 */
type ToolFn = (
  args: Record<string, unknown>,
  opts?: string,
) => Promise<unknown>;

/** Central registry – name → {fn, help} */
const registry: Map<string, { fn: ToolFn; help?: string }> = new Map();

/**
 * Register a tool.
 *
 * @param name   Unique identifier (used as CLI sub‑command)
 * @param fn     The callable function
 * @param help   Optional short description shown in `--help`
 */
export function registerTool(name: string, fn: ToolFn, help?: string): void {
  if (registry.has(name)) throw new Error(`Tool '${name}' already registered`);
  registry.set(name, { fn, help });
}

/**
 * Invoke a tool by name with JSON‑encoded arguments.
 *
 * @param name   The tool’s identifier
 * @param argv   Parsed CLI args (used for `args` param)
 * @param opts   Optional extra options supplied as JSON string
 */
export async function invokeTool(name: string, argv: Record<string, unknown>, opts?: string): Promise<unknown> {
  const entry = registry.get(name);
  if (!entry) throw new Error(`No tool registered with name '${name}'`);
  return await entry.fn(argv, opts ?? undefined);
}

/* ---------------------------------------------------
   Example tools (just for demo – replace with real code)
   --------------------------------------------------- */
