  const { message } = args;
  console.log('🔹 Echo:', safeJSON(message));
  return message;
}

async function reverse(args: Record<string, unknown>, _opts?: string): Promise<unknown> {
  const { text } = args;
  const rev = [...text].reverse().join('');
  console.log('🔹 Reverse:', safeJSON(rev));
  return rev;
}

