	if *toolName == "" {
		fmt.Fprintln(os.Stderr, "❌ Missing required --tool flag")
		os.Exit(1)
	}

	var opts map[string]interface{}
	if *optsJSON != "" {
		err := json.Unmarshal([]byte(*optsJSON), &opts)
		if err != nil {
			fmt.Fprintf(os.Stderr, "❌ Invalid JSON for options: %v\n", err)
			os.Exit(1)
		}
	} else if optsJSON == "" && len(fs.Args()) > 0 {
		// If no explicit opts flag but extra positional args are present,
		// treat them as a single JSON string.
		optsJSON = fs.Arg(0) // first non‑flag argument
		err := json.Unmarshal([]byte(optsJSON), &opts)
		if err != nil {
			fmt.Fprintf(os.Stderr, "❌ Invalid JSON for options: %v\n", err)
			os.Exit(1)
		}
	}

	fn, ok := registry[*toolName]
	if !ok {
		fmt.Fprintf(os.Stderr, "❌ No tool registered with name '%s'\n", *toolName)
		os.Exit(1)
	}

	var args map[string]interface{}
	err := json.Unmarshal([]byte(argsJSONFlag), &args)
	if err != nil {
		fmt.Fprintf(os.Stderr, "❌ Invalid JSON for arguments: %v\n", err)
		os.Exit(1)
	}

	err = fn(args, (*json.RawMessage)(&opts))
	if err != nil {
		fmt.Fprintln(os.Stderr, "❌ Tool error:", err)
		os.Exit(1)
	}
}
