  #!/usr/bin/env python3
  """
  registry.py – Tool Registry for Python projects.
  """
  
  import json
  import sys
  from typing import Callable, Dict, Any
  
  # ----------------------------------------------------------------------
  # Core registry: name -> (function, optional help string)
  # ----------------------------------------------------------------------
  _registry: Dict[str, tuple[Callable[[Dict[str, Any]], Optional[str]], str]] = {}
  
  def register_tool(name: str,
                    fn: Callable[[Dict[str, Any]], Optional[str]],
                    help_: str | None = None) -> None:
      """
      Register a callable tool.
  
      `fn` receives two arguments:
          - args (dict): parsed CLI arguments for this tool.
          - opts  (str|None): optional JSON‑encoded options supplied by caller.
      Returns whatever the caller expects (usually the output string).
      """
      if name in _registry:
          raise ValueError(f"Tool '{name}' already registered")
      _registry[name] = fn, help_
  
  def invoke_tool(name: str,
                  argv: Dict[str, Any],
                  opts_json: Optional[str] | None = None) -> Any:
      """
      Invoke a previously‑registered tool.
  
      `argv` – dict coming from argparse (or any similar mapping).
      `opts_json` – string like '"{\"key\":\"value\"}"' or None.
      Returns the result of calling fn(argv, opts_json).
      """
      if name not in _registry:
          raise ValueError(f"No tool registered with name '{name}'")
      fn, help_ = _registry[name]
      opts: Optional[str] = json.loads(opts_json) if opts_json else None
      return fn(argv)
  
  # ----------------------------------------------------------------------
  # Example tools (replace with real implementations)
  # ----------------------------------------------------------------------
  def echo_tool(args: Dict[str, Any]) -> str:
      """Echo back the supplied JSON payload."""
      msg = args.get("message", "no message")
      print(f"🔹 Echo: {msg}")
      return msg
  
  def reverse_tool(args: Dict[str, Any]) -> str:
      """Reverse a string stored under key 'text'."""
      txt = args.get("text", "")
      rev = txt[::-1]
      print(f"🔹 Reverse: {rev}")
      return rev
  
  # ----------------------------------------------------------------------
  # Simple CLI driver (demo only)
  # ----------------------------------------------------------------------
  def main():
      import argparse
      parser = argparse.ArgumentParser(description="Tool Registry Demo")
      parser.add_argument("--tool",
                          required=True,
                          help="Name of the tool to run")
      parser.add_argument("--args", type=str, default='{}')
      parser.add_argument("--opts", type=str, default=None)
  
      args = parser.parse_args()
  
      # Convert stringified JSON into a dict
      opts: Optional[str] = json.loads(args.opts) if args.opts else None
  
      try:
          result = invoke_tool(args.tool,
                               {"args": json.loads(args.args)},
                               opts)
          print("Result:", result)
      except Exception as exc:
          sys.stderr.write(f"❌ Error: {exc}\n")
          sys.exit(1)
  
  if __name__ == "__main__":
      main()
