  package main
  
  import (
  	"encoding/json"
  	"flag"
  	"fmt"
  	"os"
  
  	"github.com/spf13/pflag" // optional, can use std lib too
  )
  
  // ------------------------------------------------------------------
  // Registry definition -------------------------------------------------
  //   name -> (func(args map[string]interface{}, opts *json.RawMessage) error)
  type ToolFn func(args map[string]interface{}, opts *json.RawMessage) error
  
  var registry = make(map[string]ToolFn)
  
  func Register(name string, fn ToolFn, help string) {
  	if _, exists := registry[name]; exists {
  		panic("tool already registered")
  	}
  	registry[name] = fn
  }
  
  // ------------------------------------------------------------------
  // Helper to marshal Go map → JSON bytes (used for CLI args & opts)
  func mapToJson(m map[string]interface{}) ([]byte, error) {
  	return json.Marshal(m)
  }
  
  // ------------------------------------------------------------------
  // Example tools ------------------------------------------------------
  func echoTool(args map[string]interface{}, _ *json.RawMessage) error {
  	msg := args["message"]
  	fmt.Printf("🔹 Echo: %v\n", msg)
  	return nil
  }
  func reverseTool(args map[string]interface{}, _ *json.RawMessage) error {
  	txt, ok := args["text"].(string)
  	if !ok {
  		return fmt.Errorf("'text' argument missing or not string")
  	}
  	reversed := string([]rune(txt)[::-1])
  	fmt.Printf("🔹 Reverse: %s\n", reversed)
  	return nil
  }
  
  // ------------------------------------------------------------------
  // CLI driver ---------------------------------------------------------
  func main() {
  	fs := pflag.NewFlagSet(os.Args[0], pflag.ContinueOnError)
  
  	var toolName, argsJSON, optsJSON string
  
  	toolNameFlag := fs.StringP("tool",
  		"t",
  		"",
  		"name of the tool to run")
  	argsJSONFlag := fs.StringP("args",
  		"a",
  		`{"message":"default"}`,
  		"JSON‑encoded arguments for the selected tool (as string)")
  	optsJSONFlag = fs.StringP("opts",
  		"o",
  		"",
  		"Optional extra JSON options supplied to the tool")
  
  	fs.Parse(os.Args[1:])
  
  	if *toolName == "" {
  		fmt.Fprintln(os.Stderr, "❌ Missing required --tool flag")
  		os.Exit(1)
  	}
  
  	var opts map[string]interface{}
  	if *optsJSON != "" {
  		err := json.Unmarshal([]byte(*optsJSON), &opts)
  		if err != nil {
  			fmt.Fprintf(os.Stderr, "❌ Invalid JSON for options: %v\n", err)
  			os.Exit(1)
  		}
  	} else if optsJSON == "" && len(fs.Args()) > 0 {
  		// If no explicit opts flag but extra positional args are present,
  		// treat them as a single JSON string.
  		optsJSON = fs.Arg(0) // first non‑flag argument
  		err := json.Unmarshal([]byte(optsJSON), &opts)
  		if err != nil {
  			fmt.Fprintf(os.Stderr, "❌ Invalid JSON for options: %v\n", err)
  			os.Exit(1)
  		}
  	}
  
  	fn, ok := registry[*toolName]
  	if !ok {
  		fmt.Fprintf(os.Stderr, "❌ No tool registered with name '%s'\n", *toolName)
  		os.Exit(1)
  	}
  
  	var args map[string]interface{}
  	err := json.Unmarshal([]byte(argsJSONFlag), &args)
  	if err != nil {
  		fmt.Fprintf(os.Stderr, "❌ Invalid JSON for arguments: %v\n", err)
  		os.Exit(1)
  	}
  
  	err = fn(args, (*json.RawMessage)(&opts))
  	if err != nil {
  		fmt.Fprintln(os.Stderr, "❌ Tool error:", err)
  		os.Exit(1)
  	}
  }
