```ts
// ------------------------------------------------------------
// conversation-history-manager.ts
// ------------------------------------------------------------

import { OpenAI } from "openai";

/**
 * Simple token estimator – uses the same logic that ChatGPT‑4 uses internally.
 *
 * @param text   The raw user / assistant message (no JSON wrapper).
 * @returns      Approximate number of tokens (rounded up to nearest whole number).
 */
function estimateTokens(text: string): number {
  // OpenAI's internal tokenizer is used by the SDK when you call createCompletion
  // with `response_format`. Here we mimic that behaviour.
  //
  // For a quick approximation we can use:
  //   - ~4 tokens per English word (average)
  //   - Add a small overhead for punctuation / markdown formatting.
  const WORDS = text.trim().split(/\s+/).length;
  return Math.ceil(WORDS * 4);
}

/**
 * ConversationHistory – a thread‑safe in‑memory store that respects the token budget.
 */
export class ConversationHistory {
  /** Maximum total tokens allowed per conversation. */
  private readonly MAX_TOKENS: number;

  /** List of messages ordered oldest → newest. Each entry is {user?, assistant?}. */
  private history: Array<{ user?: string; assistant?: string }>;

  constructor(maxTokens: number = 4096) {
    this.MAX_TOKENS = maxTokens;
    this.history = [];
