    // While adding the new message would exceed budget, pop oldest entries.
    while (
      this.history.length > 0 &&
      (this.totalTokenCount() + tokenCost) > this.MAX_TOKENS
    ) {
      const removed = this.history.shift();
      if (!removed) throw new Error("History unexpectedly empty after eviction");
    }

    // Append the new message
    this.history.push({ user: role === "user" ? text : undefined,
                        assistant: role === "assistant" ? text : undefined });
