  private totalTokenCount(): number {
    return this.history.reduce((sum, msg) => {
      const user = msg.user?.trim() || "";
      const ass = msg.assistant?.trim() || "";
      return sum + estimateTokens(user) + estimateTokens(ass);
    }, 0);
