// react-loop.ts -------------------------------------------------------------
import { exec } from 'child_process';   // simple shell command runner

/**
 * The "thinking" step – decide what to do next.
 * In a real system you would inspect `state` and perhaps call an LLM,
 * but here we just return the name of the action.
 */
function think(state: string): Promise<string> {
    console.log(`\n🧠 THINK – ${state}`);
    // Example decision logic (replace with your own):
    if (state.includes('done')) {
        return Promise.resolve('DONE');
    }
    // Simple deterministic choice for demo:
    return Promise.resolve('SLEEP');   // pretend we need to wait a bit
}

/**
 * The "acting" step – perform the chosen action.
 */
async function act(action: string): Promise<string> {
    console.log(`\n⚙️ ACT  – ${action}`);
    // Example actions:
    if (action === 'SLEEP') {
        await new Promise(r => setTimeout(r, 2000));   // pretend we did something
        return `Result of SLEEP`;
    }
    // Add more cases here…
    throw new Error(`Unsupported action: ${action}`);
}

/**
 * The "observing" step – capture whatever the act function returns.
 */
function observe(result: string): void {
    console.log(`\n🔎 OBSERVE – ${result}`);
}

/**
 * Main ReAct loop
 */
async function runReActLoop(initialState: string) {
    let state = initialState;

    while (true) {
        const action = await think(state);
        if (action === 'DONE') break;   // stop condition

        const result = await act(action);
        observe(result);

        // Update the internal state – here we just echo back what we observed
        state = result;
    }

    console.log('\n✅ Loop finished.');
}

// ---------------------------------------------------------------------
(async () => {
    try {
        await runReActLoop('START');
    } catch (e) {
        console.error('❌ Error:', e);
    }
})();
