// ──────────────────────────────────────────────────────
// validator.ts – JSON‑Schema validation for tool calls
// ──────────────────────────────────────────────────────

import Ajv, { ValidateFunction } from "ajv";
import addFormats from "ajv-formats";

const ajv = new Ajv({ allErrors: true });
addFormats(ajv);

/**
 * Compile a JSON‑Schema once and reuse it.
 *
 * @param schema – the expected shape of the tool call arguments
 */
export function compileValidator(schema: Record<string, unknown>): ValidateFunction {
  return ajv.compile(schema);
}

/**
 * Validates that `payload` conforms to `schema`.
 *
 * @throws Error if validation fails (you can catch and handle it)
 * @param payload – raw object coming from the caller
 * @param schema – compiled validator function or a plain JSON‑Schema object
 */
export async function validatePayload<T>(payload: Record<string, unknown>, schema: ValidateFunction | Record<string, unknown>): Promise<T> {
  const validator = typeof schema === "function" ? schema : compileValidator(schema);
  const valid = await validator(payload); // returns true/false

  if (!valid) {
    throw new Error(
      `Tool call argument validation failed:\n${validator.errors?.map(e => `- ${e.message}`).join("\n") ?? ""}`
    );
  }

  return payload as T;   // TypeScript knows the shape now
}
```

