# ──────────────────────────────────────────────────────
# validator.py – JSON‑Schema validation for tool calls
# ──────────────────────────────────────────────────────

import jsonschema
from typing import Any, Dict, TypeVar, Generic

T = TypeVar("T")

def compile_validator(schema: Dict[str, Any]) -> jsonschema.Draft7Validator:
    """
    Compile a schema once – returns a validator that can be reused.
    """
    return jsonschema.Draft7Validator(schema)

def validate_payload(payload: Dict[str, Any], schema: Dict[str, Any]) -> T:
    """
    Validates `payload` against the given JSON‑Schema.

    Raises:
        jsonschema.exceptions.ValidationError – if validation fails
    Returns:
        payload cast to type ``T`` (the caller must match the schema)
    """
    validator = compile_validator(schema)
    errors = list(validator.iter_errors(payload))
    if errors:
        raise ValueError(
            f"Tool call argument validation failed:\n"
            + "\n".join(f"- {str(e)}" for e in errors)
        )
    # The payload matches – cast to the generic type (the caller must enforce it)
    return payload  # <-- you could also use TypedDict / dataclasses if desired
```

