## 3️⃣ Go

```go
// ──────────────────────────────────────────────────────
// validator.go – JSON‑Schema validation for tool calls (Go)
// ──────────────────────────────────────────────────────

package main

import (
	"encoding/json"
	"errors"

	"github.com/xeipuuv/gojsonschema"
)

type Validator struct {
	schemaLoader gojsonschema.JSONLoader
}

func NewValidator(schema []byte) (*Validator, error) {
	return &Validator{
		schemaLoader: gojsonschema.NewBytesLoader(schema),
	}, nil
}

// Validate validates `payload` against the compiled schema.
// Returns an error if validation fails; otherwise returns nil (so callers can just check).
func (v *Validator) Validate(payload []byte) error {
	instance := gojsonschema.NewBytesLoader(payload)
	result, err := v.schemaLoader.Validate(instance)
	if err != nil {
		return errors.Wrap(err, "schema evaluation")
	}
	if !result.Valid() {
		var msgs []string
		for _, err := range result.Errors() {
			msgs = append(msgs, err.String())
		}
		return errors.New(strings.Join(msgs, "\n"))
	}
	return nil // no error → validation passed
}

// Example helper that marshals a struct into JSON bytes:
func marshal(v interface{}) ([]byte, error) {
	b, err := json.Marshal(v)
	if err != nil {
		return nil, err
	}
	return b, nil
}
```

