## 1️⃣ TypeScript (Node.js)

```ts
// repl.ts --------------------------------------------------------------
import * as readline from 'readline';
import { v4 as uuidv4 } from 'uuid';

const rl = readline.createInterface({
    input: process.stdin,
    output: process.stdout,
});

let history: string[] = [];          // simple in‑memory history buffer
let currentHistoryIndex = -1;        // points to the next entry

function evalInput(line: string): any {
    // Very naive evaluator – only supports:
    //   * arithmetic expressions (e.g. "2 + 3")
    //   * variable assignment (e.g. "x = 5")
    line = line.trim();

    if (!line) return undefined;          // blank line → nothing

    const parts = line.split('=');
    if (parts.length === 2) {
        const [varName, valueStr] = parts;
        const varNameTrimmed = varName.trim();
        const valueTrimmed = valueStr.trim();

        // Simple type inference: numbers first, then strings
        let val: any;
        if (/^-?\d+(\.\d+)?$/.test(valueTrimmed)) {
            val = parseFloat(valueTrimmed);
        } else {
            // Try JSON‑like parsing (handles booleans, null)
            try {
                val = JSON.parse(valueTrimmed);
            } catch (_) {
                val = valueTrimmed;          // fallback – treat as string
            }
        }

        globalThis[varNameTrimmed] = val;   // attach to the top‑level scope
        console.log(`var ${varNameTrimmed} = ${val}`);
    } else {
        const result = eval(line);         // simple eval for arithmetic, etc.
        if (result === undefined) return;
        console.log(result);
    }
}

// ---------- History handling ----------
function addHistory(cmd: string): void {
    history.push(cmd);
    currentHistoryIndex = history.length - 1;   // newest command is at end
}
function getPrev(): string | null {
    if (currentHistoryIndex < 0) return null;
    const prev = history[currentHistoryIndex];
    currentHistoryIndex -= 1;
    return prev;
}
function getNext(): string | null {
    if (currentHistoryIndex >= history.length - 1) return null;
    currentHistoryIndex += 1;
    return history[currentHistoryIndex] ?? '';
}

// ---------- REPL loop ----------
rl.setPrompt('repl> ');
rl.prompt();

rl.on('line', async (input: string) => {
    const trimmed = input.trim();
    if (!trimmed) return;                     // ignore empty lines

    addHistory(trimmed);                       // store for history
    evalInput(trimmed);
    rl.prompt();                               // next prompt
}).on('close', () => {
    console.log('\nGoodbye!');
    process.exit(0);
});
// --------------------------------------------------------------------
