package main

import (
	"bufio"
	"fmt"
	"os"
	"strings"
)

var history []string          // simple in‑memory history buffer
var currentIdx = -1           // points to next insertion position


// ----- Simple evaluator -------------------------------------------------
func evalInput(line string) (result interface{}, err error) {
	line = strings.TrimSpace(line)
	if line == "" {
		return nil, nil
	}

	// ----- Variable assignment -----
	parts := strings.SplitN(line, "=", 2)
	if len(parts) == 2 {
		varName := strings.TrimSpace(parts[0])
		valueStr := strings.TrimSpace(parts[1])

		switch {
		case valueStr == "":
			result = nil
		case isNumber(valueStr):
			fval, _ := strconv.ParseFloat(valueStr, 64)
			result = fval
		default:
			var parsed interface{}
			if err := json.Unmarshal([]byte(valueStr), &parsed); err == nil {
				result = parsed
			} else {
				result = valueStr // fallback string
			}
		}

		globalVars[varName] = result          // inject into package‑level map (simulating globals)
		fmt.Printf("var %s = %v\n", varName, result)
		return nil, nil
	}

	// ----- Arithmetic evaluation -----
	if isNumber(line) {
		fval, _ := strconv.ParseFloat(line, 64)
		result = fval
	} else {
		var parsed interface{}
		err = json.Unmarshal([]byte(line), &parsed)
		if err == nil {
			result = parsed
		}
	}

	fmt.Println(result)
	return result, nil
}

// ----- Helper: detect numeric strings ------------------------------------
import (
	"strconv"
)

func isNumber(s string) bool {
	_, err := strconv.ParseFloat(s, 64)
	return err == nil
}

// ----- Global namespace (package‑level map) ----------------------------
var globalVars = make(map[string]interface{})


// ----- REPL loop --------------------------------------------------------
func main() {
	reader := bufio.NewReader(os.Stdin)

	fmt.Print("repl> ")
	if _, err := reader.ReadString('\n'); err != nil { // prime read
		return
	}

	for {
		line, _ := reader.ReadString('\n')
		cmd := strings.TrimSpace(line)
		if cmd == "" {
			continue
		}
		addHistory(cmd)

		result, err := evalInput(cmd)
		if err != nil {
			fmt.Printf("Error: %v\n", err)
			continue
		}

		currentIdx++
		history = append(history[:currentIdx], history[currentIdx:]...)
		if currentIdx >= len(history) {
			currentIdx = len(history) - 1
		}
	}
}

// ----- History helpers --------------------------------------------------
func addHistory(cmd string) {
	history = append(history, cmd)
	if len(history) > 100 { // keep last ~100 commands (adjust as needed)
		history = history[:100]
	}
}

func getPrev() string {
	if currentIdx < 0 || currentIdx <= 0 {
		return ""
	}
	return history[currentIdx-1]
}

func getNext() string {
	if currentIdx >= len(history)-1 {
		return ""
	}
	currentIdx++
	return history[currentIdx]
}

// ----- Simple CLI helpers ------------------------------------------------
func mainExit(msg string) {
	fmt.Println("\nGoodbye!")
	os.Exit(0)
}

