  import sys
  from collections import deque
  
  history: deque[str] = deque(maxlen=100)   # keep last ~100 commands (adjust as needed)
  current_idx: int = -1                     # points to next insertion position
  
  
  def eval_input(line: str):
      line = line.strip()
      if not line:
          return None
  
      # ----- Variable assignment -----
      if '=' in line and len(line.split('=')) == 2:
          var_name, value_str = (part.strip() for part in line.split('=', 1))
          try:
              # Simple type inference: numbers first
              if isinstance(value_str, str):
                  val = float(value_str) if '.' in value_str else int(value_str)
              else:
                  import json
                  val = json.loads(value_str)
          except Exception:
              val = value_str
  
          globals()[var_name] = val          # inject into global namespace
          print(f"var {var_name} = {val}")
          return
  
      # ----- Arithmetic evaluation -----
      try:
          result = eval(line, {}, globals())
          if result is None:
              return
          print(result)
      except Exception as e:
          print("Error:", e)
  
  
  def add_history(cmd: str):
      history.append(cmd)          # deque automatically drops oldest when full
  
  
  def get_prev():
      global current_idx
      if not history or current_idx < 0:
          return None
      current_idx -= 1
      return history[current_idx]
  
  
  def get_next():
      global current_idx, history
      if current_idx >= len(history) - 1:
          return None
      current_idx += 1
      return history[current_idx]
  
  
  # ----- REPL loop -----
  print("Type 'exit' or press Ctrl+D (EOF) to quit")
  while True:
      try:
          user_input = input("\nrepl> ")
      except EOFError:   # Ctrl+D / ^Z on Windows
          break
  
      if not user_input.strip():
          continue
  
      add_history(user_input)
      result = eval_input(user_input)
  
  if current_idx >= 0:
      print(history[current_idx])   # show last recalled command (optional)
  
  print("\nGoodbye!")
