  	}
  
  	// ----- Arithmetic evaluation -----
  	if isNumber(line) {
  		fval, _ := strconv.ParseFloat(line, 64)
  		result = fval
  	} else {
  		var parsed interface{}
  		err = json.Unmarshal([]byte(line), &parsed)
