// cmd/server/main.go
package main

import (
	"context"
	"fmt"
	"log"
	"net"

	pb "github.com/yourusername/pingpong/internal/proto" // <-- adjust import path accordingly
	"google.golang.org/grpc"
)

type server struct {
	pb.UnimplementedPingPongServer
}

// Ping implements the gRPC RPC.
func (s *server) Ping(ctx context.Context, req *pb.PingRequest) (*pb.PingResponse, error) {
	return &pb.PingResponse{Echo: req.Message}, nil
}

func main() {
	lis, err := net.Listen("tcp", ":50051")
	if err != nil {
		log.Fatalf("failed to listen: %v", err)
	}
	svr := grpc.NewServer()
	pb.RegisterPingPongServer(svr, &server{})
	fmt.Println("🟢 gRPC Ping‑Pong server listening on :50051")
	if err := svr.Serve(lis); err != nil {
		log.Fatalf("serve failed: %v", err)
	}
}
```

