// src/client/ping.ts
import { Client, GrpcWebClient } from 'grpc-web';
import * as grpcWeb from '@improbable-eng/grpc-web';

// Import the generated TS definitions (they are in ./generated)
import { PingPongService } from '../generated/pingpong_pb_service'; // adjust path

export async function pingMessage(message: string): Promise<string> {
  const channel = new Client('localhost', 50051, grpcWeb.WebProto);
  const client = new PingPongService(channel);

  // The gRPC‑web client expects a protobuf message object.
  const req = new PingPongService.PingRequest();
  req.setMessage(message);   // setter matches the proto field name

  try {
    const resp: PingPongService.PingResponse = await client.ping(req);
    return resp.getEcho();     // <-- echo back what we sent
  } catch (err) {
    console.error('❌ gRPC error:', err);
    throw new Error('Failed to ping server');
  }
}

// Example usage:
