## 1️⃣ TypeScript (Express + multer)

```ts
// server.ts --------------------------------------------------------------
import express, { Request, Response } from 'express';
import multer   from 'multer';

const app = express();
app.use(express.json());               // for JSON bodies

// ──────  Multer configuration ────────────────────────────────────────
// • storage: write files to disk (temporary folder)
// • limits: max file size, total post body size, etc.
// • fileFilter: optional – restrict allowed MIME types / extensions
const upload = multer({
  dest: 'tmp/',                     // where uploaded parts are stored temporarily
  limits: {
    fileSize: 10 * 1024 * 1024,     // max 10 MiB per part (adjust as needed)
    fields:   Infinity,
  },
  fileFilter(req, file, cb) {
    const mimeType = req.get('content-type')?.split(';')[0] ?? '';
    if (
      mimeType === 'image/jpeg' ||
      mimeType === 'image/png' ||
      mimeType === 'application/pdf'
    ) {
      return cb(null, true);
    }
    // reject unsupported types
    return cb(new Error('Unsupported file type'));
  },
});

// ──────  POST /upload route (multipart/form-data) ───────────────────────
app.post('/upload', upload.single('file'), (req: Request, res: Response) => {
  if (!req.file || !req.file.buffer) {
    return res.status(400).json({ error: 'No file part received' });
  }

  // `req.file` contains the raw buffer and metadata (`originalName`, `mimetype`, …)
  const { originalName, mimetype } = req.file;

  // Example: move the temporary buffer to a permanent location
  const targetPath = `uploads/${encodeURIComponent(originalName)}`;
  // (implementation omitted – e.g. fs.renameSync)

  res.json({
    success: true,
    file: {
      name: originalName,
      type: mimetype,
      sizeBytes: req.file.buffer.length,
      path: targetPath,   // optional
    },
  });
});

// ──────  Start server ----------------------------------------------------
const PORT = process.env.PORT ?? 3000;
app.listen(PORT, () => console.log(`🚀 Server listening on http://localhost:${PORT}`));
```

**Key points**

| Feature | Why it matters |
|---------|----------------|
| `multer` (Node) / equivalent libraries in other languages handle the multipart boundary parsing automatically. |
| `dest` stores each part temporarily; you can move them to permanent storage later. |
| `limits.fileSize` protects against DoS attacks by capping individual file sizes. |
| Optional `fileFilter` lets you whitelist MIME types or extensions before saving. |

