## 2️⃣ Python (Flask)

```python
# app.py ---------------------------------------------------------------
from flask import Flask, request, jsonify
import os
import uuid

app = Flask(__name__)

UPLOAD_FOLDER = 'uploads'
os.makedirs(UPLOAD_FOLDER, exist_ok=True)
ALLOWED_MIMETYPES = {'image/jpeg', 'image/png', 'application/pdf'}

@app.route('/upload', methods=['POST'])
def upload_file():
    if 'file' not in request.files:
        return jsonify({'error': 'No file part'}), 400

    file = request.files['file']

    # Basic sanity checks
    if file.filename == '':
        return jsonify({'error': 'No selected file'}), 400
    if file and allowed_file(file):
        filename = f"{uuid.uuid4()}_{file.filename}"
        filepath = os.path.join(UPLOAD_FOLDER, filename)
        # Move the uploaded bytes to permanent storage (here just a rename for demo)
        try:
            with open(filepath, 'wb') as out_f:
                out_f.write(file.stream.read())
            return jsonify({
                "success": True,
                "file": {
                    "name": file.filename,
                    "type": file.mimetype,
                    "size_bytes": os.path.getsize(filepath),
                    "path": filepath
                }
            }), 200
        except Exception as e:
            return jsonify({"error": str(e)}), 500

    return jsonify({'error': 'Unsupported MIME type'}), 415


def allowed_file(f: object) -> bool:
    # `file.stream` is a Flask BytesIO stream; read the first few bytes to guess mime
    content_type = f.mimetype or request.headers.get('content-type')
    if not content_type:
        return False
    return content_type.split(';')[0].strip() in ALLOWED_MIMETYPES


if __name__ == '__main__':
    app.run(host='0.0.0.0', port=5000, debug=True)
```

**Highlights**

* `request.files` contains the parsed multipart body; you access it via `'file'`.
* The helper `allowed_file()` mimics what many frameworks do (`werkzeug.utils.secure_filename`, etc.) – you can also use a whitelist of MIME types.
* Files are written to disk under an `uploads/` folder. In production you’d typically stream directly to object storage (S3, GCS) or move the temporary file.

