## 3️⃣ Go

```go
// main.go ---------------------------------------------------------------
package main

import (
	"encoding/json"
	"fmt"
	"io/ioutil"
	"log"
	"net/http"
	"os"
	"path/filepath"

	"github.com/gorilla/mux" // optional: use standard net/http + mux for simplicity
)

const uploadDir = "uploads/"
var allowedMIMETypes = map[string]bool{
	"image/jpeg": true,
	"image/png":  true,
	"application/pdf": true,
}

func init() {
	os.MkdirAll(uploadDir, os.ModePerm)
}

// Helper: check if filename contains a dot (basic sanity)
func isValidFilename(name string) bool { return len(filepath.Ext(name)) > 0 }

// POST /upload – expects multipart/form-data with field "file"
func uploadHandler(w http.ResponseWriter, r *http.Request) {
	if r.Header.Get("Content-Type") != "multipart/form-data" {
		http.Error(w, "Expected multipart/form-data", http.StatusBadRequest)
		return
	}

	fileHeader, err := mux.FromContext(r.Context()).FileByName(r, "file")
	if err != nil || fileHeader == nil {
		http.Error(w, `{"error":"No file part"}`, http.StatusBadRequest)
		return
	}
	defer fileHeader.Close()

	data, err := ioutil.ReadAll(fileHeader)
	if err != nil {
		http.Error(w, fmt.Sprintf(`{"error":"%v"}`, err), http.StatusInternalServerError)
		return
	}

	filename := uuid.New().String() + filepath.Ext(string(data))
	targetPath := filepath.Join(uploadDir, filename)

	err = ioutil.WriteFile(targetPath, data, 0644)
	if err != nil {
		http.Error(w, fmt.Sprintf(`{"error":"%v"}`, err), http.StatusInternalServerError)
		return
	}

	resp := map[string]interface{}{
		"success": true,
		"file": map[string]string{
			"name":    fileHeader.Filename,
			"type":    r.Header.Get("Content-Type"),
			"size_bytes": fmt.Sprintf("%d", len(data)),
			"path":    targetPath,
		},
	}
	w.Header().Set("Content-Type", "application/json")
	json.NewEncoder(w).Encode(resp)
}

func main() {
	http.HandleFunc("/upload", uploadHandler)

	fmt.Println("🚀 Server listening on :8080")
	log.Fatal(http.ListenAndServe(":8080", nil))
}
```

**What’s happening**

* `mux` (or the standard library) parses the raw request body manually because Go doesn’t have a built‑in multipart parser like Flask or Express.
* The handler validates that the `Content-Type` header matches `multipart/form-data`.
* It reads the file contents (`ioutil.ReadAll`) and writes them to disk under an UUID‑prefixed name (you could also use `os.CreateTemp` for temporary storage).
* JSON response mirrors what the TypeScript/Python examples return.

