   * @param owner      Repository owner (e.g., "octocat")
   * @param repo       Repository name (e.g., "Hello-World")
   * @param headBranch Branch you want to merge into the base branch
   * @param baseBranch The default branch of the repository (usually "main" or "master")
   * @param title      Title for the PR
   * @param body       Optional description for the PR
   * @param reviewers  Array of GitHub usernames / team slug strings that should be reviewers
   */
  async function createPullRequestAndReviewers(
    owner: string,
    repo: string,
    headBranch: string,
    baseBranch: string,
    title: string,
    body?: string,
    reviewers?: string[]
  ): Promise<void> {
    const octokit = new Octokit({
      auth: process.env.GITHUB_TOKEN!, // <-- set this env var with your PAT
    });
  
    // -------------------------------------------------
    // STEP 1 – Create the pull request (open)
    // -------------------------------------------------
    const prResponse = await octokit.pulls.create({
      owner,
      repo,
      head: `${owner}:${headBranch}`,
      base: baseBranch,
      title,
      body,
    });
    if (!prResponse.data.html_url) {
      throw new Error('Failed to create pull request');
    }
    console.log(`✅ PR created! ${prResponse.data.html_url}`);
  
    // -------------------------------------------------
    // STEP 2 – (Optional) Add reviewers
    // -------------------------------------------------
    if (reviewers?.length > 0) {
      const reviewerPromises = reviewers.map((reviewer) => {
        return octokit.pulls.requestReviewers({
          owner,
          repo,
          pull_number: prResponse.data.number,
          reviewers: [reviewer],
          team_reviewers: [], // we only request *individual* reviewers here
        });
      });
  
      await Promise.all(reviewerPromises);
    }
  }
  
  // -------------------------------------------------
  // Example usage (run as a script)
  // -------------------------------------------------
  if (require.main === module) {
    const args = process.argv.slice(2);
    if (
      !args.length ||
      !(args[0] && args[1] && args[2] && args[3] && args[4])
    ) {
      console.error(
        'Usage: node create-pr-and-reviewer.ts <owner> <repo> <headBranch> <baseBranch> "<title>"'
      );
      process.exit(1);
    }
  
    const [_, owner, repo, headBranch, baseBranch, title] = args;
    // You can pass an array of reviewer strings; omit for none.
    createPullRequestAndReviewers(
      owner,
      repo,
      headBranch,
      baseBranch,
      title
    ).catch((e) => {
      console.error('❌ Error:', e);
      process.exit(1);
    });
  }
