  ```python
  #!/usr/bin/env python3
  """
  create_pr_and_reviewer.py – Create a PR and add reviewers via GitHub REST API.
  
  Prerequisites:
      pip install requests
  """
  
  import os
  import sys
  import json
  from typing import List, Optional
  
  import requests
  
  
  GITHUB_TOKEN = os.getenv("GITHUB_TOKEN")  # <-- set this env var with your PAT
  
  
  def create_pull_request_and_reviewers(
      owner: str,
      repo: str,
      head_branch: str,
      base_branch: str,
      title: str,
      body: Optional[str] = None,
      reviewers: Optional[List[str]] = None,
  ) -> None:
      """
      Creates a PR and adds one or more reviewers.
  
      Parameters
      ----------
      owner : str
          Repository owner (e.g., "octocat").
      repo   : str
          Repository name (e.g., "Hello-World").
      head_branch : str
          Branch you want to merge into the base branch.
      base_branch : str
          Default/base branch of the repository (usually "main" or "master").
      title  : str
          PR title.
      body   : Optional[str]
          PR description; defaults to None → empty body.
      reviewers : Optional[List[str]]
          List of GitHub usernames / team slugs that should be reviewers.
      """
      api_url = f"https://api.github.com/repos/{owner}/{repo}"
      headers = {
          "Accept": "application/vnd.github.v3+json",
          "Authorization": f"token {GITHUB_TOKEN}",
      }
  
      # -------------------------------------------------
      # STEP 1 – Create the pull request (open)
      # -------------------------------------------------
      payload = {
          "head": head_branch,
          "base": base_branch,
          "title": title,
          "body": body or "",
      }
      response = requests.post(f"{api_url}/pulls", headers=headers, json=payload)
  
      if not response.ok:
          print("❌ Failed to create PR:", response.status_code, response.text)
          sys.exit(1)
      pr_data = response.json()
      html_url = pr_data["html_url"]
      print(f"✅ PR created! {html_url}")
  
      # -------------------------------------------------
      # STEP 2 – (Optional) Add reviewers
      # -------------------------------------------------
      if reviewers:
          for reviewer in reviewers:
              payload_reviewer = {
                  "reviewers": [reviewer],
                  # `team_reviewers` is ignored when you request individuals;
                  # set to an empty list.
              }
              r = requests.post(
                  f"{api_url}/pulls/{pr_data['number']}/requested_reviewers",
                  headers=headers,
                  json=payload_reviewer,
              )
              if not r.ok:
                  print(f"❌ Failed to add reviewer '{reviewer}':", r.status_code, r.text)
          # The API returns a 202 Accepted for each successful request;
          # we just log any failures.
      else:
          print("No reviewers requested.")
  
  
  if __name__ == "__main__":
      if len(sys.argv) < 6:
          print(
              "Usage: python create_pr_and_reviewer.py "
              "<owner> <repo> <head_branch> <base_branch> \"<title>\""
          )
          sys.exit(1)
  
      owner, repo, head_branch, base_branch, title = (
          sys.argv[1], sys.argv[2], sys.argv[3], sys.argv[4], sys.argv[5]
      )
  
      # Optional reviewers – pass as a space‑separated list; we'll split it.
      reviewer_arg = " ".join(sys.argv[6:]) if len(sys.argv) > 6 else None
      try:
          reviewers_list = [r.strip() for r in reviewer_arg.split()] if reviewer_arg else []
      except Exception:
          print("Error parsing reviewers – they must be quoted or omitted.")
          sys.exit(1)
  
      create_pull_request_and_reviewers(
          owner, repo, head_branch, base_branch, title, None, reviewers_list
      )
