## 1️⃣ TypeScript (Node.js + libgit2)

```ts
// clone-and-push.ts
import { Repository, RemoteCallbacks } from 'libgit2';

async function clonePush(
    repoUrl: string,
    branchName = 'main',
    commitMsg = 'Add/modify file'
): Promise<void> {
  // -------------------------------------------------
  // 1️⃣ Clone the repository (shallow by default)
  // -------------------------------------------------
  const repoPath = '/tmp/cloned-repo';          // change as you wish
  await new Repository.init(repoPath);         // creates a fresh bare repo

  const cloneOpts = {
    url: repoUrl,
    checkoutBranch: branchName,
    fetchOpt: { depth: 1 }                     // shallow – only latest commit
  };
  await Repository.clone(cloneOpts, repoPath);

  // -------------------------------------------------
  // 2️⃣ Open the repository and add a new file (or modify an existing one)
  // -------------------------------------------------
  const repo = await Repository.open(repoPath);
  let tree: libgit2.Tree;
  try {
    tree = await repo.getTreeAsync('HEAD');
    // Example: create a new file `README.md` with some content
    const readmeEntry = tree.lookup('README') ?? tree.addEntry(
      'README',
      Buffer.from(`# ${branchName}\n\nCloned repository – commit added on ${new Date().toISOString()}`)
    ) as libgit2.Blob;
    await repo.writeTreeAsync(readmeEntry);
  } finally {
    if (repo) await repo.release();
  }

  // -------------------------------------------------
  // 3️⃣ Stage the change, create a new commit and push it
  // -------------------------------------------------
  const index = await repo.readIndexAsync()!;
  const id = await repo.writeTreeAsync(index);
  const author = new libgit2.Signature('Your Name', 'you@example.com');
  const committer = author; // same for this demo

  const treeId = Buffer.from(id.toString());
  const commitMessage = `${commitMsg}\n\nCloses: ${branchName}`;
  const signature = await repo.createSignatureAsync(author, committer);

  const oid = await repo.createCommitAsync(
    'HEAD',
    signature,
    committer,
    commitMessage,
    treeId,
    []
  );

  // -------------------------------------------------
  // 4️⃣ Push the new commit
  // -------------------------------------------------
  const remoteName = 'origin';
  const pushOpts = {
    callbacks: new RemoteCallbacks({
      onRemoteCallback: (url, hasAuth) => console.log('Pushing to', url)
    })
  };
  await repo.pushAsync(
    [remoteName],
    Buffer.from(oid.toString()),
    pushOpts,
    // optional – abort if remote refuses
    libgit2.PUSH_UPDATE_REF_ABORT_IF_MISSING |
      libgit2.PUSH_UPDATE_REF_NO_DELETE
  );

  console.log('✅ Done! Commit pushed to', repoUrl);
}

// -----------------------------------------------------------------
// Example usage (run via `ts-node clone-and-push.ts`)
// -----------------------------------------------------------------
if (require.main === module) {
  // Replace with any public or private repo you own / have write access to.
  const REPO_URL = 'https://github.com/your‑org/repo-name.git';
  clonePush(REPO_URL).catch(console.error);
}
```

### What the code does

| Step | libgit2 API (Node) | Purpose |
|------|-------------------|---------|
| **Clone** | `Repository.clone` with `{depth:1}` | Creates a shallow copy of the remote repo. |
| **Open**   | `Repository.open` | Lets us read/write objects in‑memory (`Tree`, `Blob`). |
| **Modify** | `tree.addEntry` → `writeTreeAsync` | Adds/overwrites a file (here, `README.md`). |
| **Commit** | `repo.createCommitAsync` + signature creation | Produces a new commit with the supplied message. |
| **Push**   | `repo.pushAsync` using `RemoteCallbacks` | Sends the commit to the remote branch (`origin/main`). |

> **Prerequisites**
> * Node ≥ 18 (for native async/await support)
> * Install libgit2 via npm: `npm i libgit2`
> * Ensure you have write access to the target repository.

