## 2️⃣ Python (using **GitPython**)

```python
# clone_and_push.py
import os
from pathlib import Path

from git import Repo, GitCommandError


def clone_push(
    repo_url: str,
    branch_name: str = "main",
    commit_msg: str = "Add/modify file",
) -> None:
    """
    Clone a repository, create (or modify) `README.md`, commit and push.
    """

    # -------------------------------------------------
    # 1️⃣ Clone shallowly
    # -------------------------------------------------
    clone_dir = Path("/tmp/cloned_repo")   # change as needed
    clone_dir.mkdir(parents=True, exist_ok=True)

    try:
        repo = Repo.clone_from(repo_url, clone_dir, depth=1)
    except GitCommandError as e:
        print("❌ Failed to clone:", e)
        return

    # -------------------------------------------------
    # 2️⃣ Open the working tree and modify a file
    # -------------------------------------------------
    readme_path = repo.working_tree_dir / "README.md"
    if not readme_path.exists():
        readme_path.touch()

    with open(readme_path, "a", encoding="utf-8") as f:
        f.write(f"\n# {branch_name}\n\nCloned repository – commit added on {__import__('datetime').datetime.now().isoformat()}")

    # -------------------------------------------------
    # 3️⃣ Stage → Commit → Push
    # -------------------------------------------------
    repo.index.add(["README.md"])          # add the changed file(s)
    index = repo.index

    author = "Your Name <you@example.com>"
    committer = author
    commit_message = f"{commit_msg}\n\nCloses: {branch_name}"

    try:
        tree_id = index.write_tree()
        signature = repo.create_signature(
            name=author,
            email="you@example.com",
            timestamp=__import__("datetime").datetime.utcnow(),
            timezone_offset=0,
        )
        commit_oid = repo.commit(commit_message, author=signature, committer=signature)
    except Exception as exc:
        print("❌ Failed to create commit:", exc)
        return

    # -------------------------------------------------
    # 4️⃣ Push the new commit
    # -------------------------------------------------
    remote_name = "origin"
    try:
        origin_remote = repo.remotes[remote_name]
        origin_remote.push([commit_oid], refs={"HEAD": f"refs/heads/{branch_name}"})
        print("✅ Commit pushed to", remote_name)
    except Exception as exc:
        print("❌ Push failed:", exc)


if __name__ == "__main__":
    # Replace with any public/private repo you have write access to.
    REPO_URL = "https://github.com/your-org/repo-name.git"
    clone_push(REPO_URL)
```

