## 3️⃣ Go (using **libgit2** bindings)

```go
// clone_push.go
package main

import (
	"bytes"
	"context"
	"fmt"
	"io/ioutil"
	"log"
	"os"
	"path/filepath"

	git "github.com/libgit2/git2go/v33"
	"github.com/libgit2/git2go/v33/indexdiff"
)

func clonePush(repoURL, branchName, commitMsg string) error {
	tmpDir := filepath.Join(os.TempDir(), "cloned_repo")
	if err := os.MkdirAll(tmpDir, 0o755); err != nil {
		return fmt.Errorf("mkdir: %w", err)
	}

	ctx := context.Background()

	// -------------------------------------------------
	// 1️⃣ Clone shallowly
	// -------------------------------------------------
	repo, err := git.Clone(ctx, tmpDir, &git.CloneOptions{
		URL:          repoURL,
		Bare:         false,
		CheckoutBranch: branchName,
		FetchOptions: git.FetchOptions{Depth: 1},
	})
	if err != nil {
		return fmt.Errorf("clone: %w", err)
	}

	workdir := repo.Workdir()
	if workdir == "" {
		return fmt.Errorf("repository has no working directory")
	}

	// -------------------------------------------------
	// 2️⃣ Open the repository and modify a file
	// -------------------------------------------------
	readmePath := filepath.Join(workdir, "README.md")
	if _, err := os.Stat(readmePath); os.IsNotExist(err) {
		f, err := os.Create(readmePath)
		if err != nil {
			return fmt.Errorf("create README: %w", err)
		}
		defer f.Close()
	}

	err = ioutil.WriteFile(readmePath, []byte(fmt.Sprintf("# %s\n\nCloned repository – commit added on %s", branchName, os.Args[0])), 0644)
	if err != nil {
		return fmt.Errorf("write README: %w", err)
	}

	// -------------------------------------------------
	// 3️⃣ Stage → Commit → Push
	// -------------------------------------------------
	index, err := git.IndexFromFile(workdir + "/.git/index")
	if err != nil {
		return fmt.Errorf("open index: %w", err)
	}
	diff, err := index.Diff(nil)
	if err != nil {
		return fmt.Errorf("diff: %w", err)
	}

	treeBuilder := git.NewTreeBuilder()
	for _, entry := range diff.Entries() {
		mode := git.Mode(entry.Flags())
		path := string(entry.OldPath())
		blobID, err := entry.Blob().Id()
		if err != nil {
			return fmt.Errorf("get blob id: %w", err)
		}
		treeBuilder.AddEntry(mode, path, blobID)
	}

	newTree, err := treeBuilder.Write(ctx)
	if err != nil {
		return fmt.Errorf("write new tree: %w", err)
	}

	sig := git.NewSignature(
		fmt.Sprintf("%s <%s>", "Your Name", "you@example.com"),
		nil,
	)

	treeIDBuf := bytes.Buffer{}
	copy(treeIDBuf[:], newTree.Id().Bytes())
	treeIDStr := string(treeIDBuf.Bytes())

	newCommit, err := repo.CreateCommit(
		git.NewSignature("HEAD", sig),
		sig,
		sig,
		fmt.Sprintf("%s\n\nCloses: %s", commitMsg, branchName),
		newTree,
		nil)
	if err != nil {
		return fmt.Errorf("create commit: %w", err)
	}

	pushOpts := git.PushOptions{
		CreateUpdateRefFlags: git.PUSH_CREATE_UPDATE_REF |
			git.PUSH_NO_DELETE,
	}
	err = repo.Push(ctx, []string{git.RemoteNameOrigin}, &pushOpts, newCommit.Oid())
	if err != nil {
		return fmt.Errorf("push commit: %w", err)
	}

	fmt.Println("✅ Commit pushed to", repoURL)

	return nil
}

func main() {
	if len(os.Args) < 2 {
		log.Fatal("Usage: go run clone_push.go https://github.com/your-org/repo-name.git")
	}
	repoURL := os.Args[1]
	err := clonePush(repoURL, "main", "Add/modify file via libgit2 in Go")
	if err != nil {
		log.Fatalf("error: %v", err)
	}
}
```

