// ---------------------------------------------------------------
// openapi-generator.ts
// ---------------------------------------------------------------
import { v4 as uuidv4 } from "uuid";

/**
 * A minimal definition for each endpoint.
 *
 * In a real‑world generator you would expose richer types (paths,
 * security, servers, etc.) but the core idea is the same:
 *   - `path` – string like "/users"
 *   - `method` – one of GET/POST/PUT/PATCH/DELETE/etc.
 *   - `summary`, `description`, `operationId`
 *   - request/response bodies & schemas (here we just use a placeholder)
 */
export type RouteDefinition = {
  path: string;
  method: "GET" | "POST" | "PUT" | "PATCH" | "DELETE";
  summary?: string;
  description?: string;
  operationId?: string; // optional unique identifier for the spec
  requestBody?: { content: Record<string, any> };   // placeholder only
};

/**
 * Generates a full OpenAPI 3.0 document from an array of route definitions.
 *
 * The generated spec contains:
 *   • `openapi": "3.0.0"`
 *   • `info` (title, version)
 *   • `servers`
 *   • `paths` – each path maps to the OpenAPI operation objects
 *   • optional security & tags sections for illustration.
 */
export function generateOpenApiSpec(routeDefs: RouteDefinition[]): any {
  const spec: any = {
    openapi: "3.0.0",
    info: {
      title: "Generated API (TypeScript)",
      version: "1.0.0",
    },
    servers: [{ url: "/" }], // default server
    paths: {} as Record<string, Record<string, any>>,
  };

  // Helper to add a security requirement block if needed.
  const applySecurity = (securitySchemes: Record<string, any>[]) => {
    spec.components ??= {};
    spec.components.securitySchemas ??= {};
    for (const scheme of securitySchemes) {
      const name = Object.keys(scheme)[0];
      spec.components.securitySchemas![name] = scheme[name];
    }
  };

  // Helper to create a simple operation object.
  const makeOperation = ({
    summary,
    description,
    requestBody,
    responses = { "200": { description: "OK" } },
  }: {
    summary?: string;
    description?: string;
    requestBody?: any;   // placeholder
    responses?: Record<string, any>;
  }): any => {
    return {
      operationId: requestBody?.operationId ?? uuidv4(),
      summary,
      description,
      requestBody,
      responses,
    };
  };

  routeDefs.forEach((def) => {
    const pathKey = def.path;
    if (!spec.paths[pathKey]) spec.paths[pathKey] = {};

    // Build the OpenAPI operation object.
    const op: any = makeOperation({
      summary: def.summary ?? `Create ${pathKey}`,
      description: def.description ??
        (def.method === "POST" && `Add a new ${pathKey}`) ??
        undefined,
      requestBody: {
        content: {},
      },
      responses: { ...def.requestBody?.content, ...def.responses },
    });

    // Map HTTP method → operation object.
    spec.paths[pathKey][def.method.toLowerCase()] = op;
  });

  return spec;
}

// -----------------------------------------------------------------
// Example usage (you can drop this into a .ts file and run with ts-node)
// -----------------------------------------------------------------
if (require.main === module) {
  const routes: RouteDefinition[] = [
    {
      path: "/users",
      method: "GET",
      summary: "List all users",
      description:
        "Returns an array of user objects. Supports pagination via `?page=` and `?limit=` query parameters.",
    },
    {
      path: "/users/{id}",
      method: "GET",
      operationId: "getUserById", // optional unique id
      summary: "Get a single user by ID",
      requestBody: { content: {} }, // placeholder – OpenAPI does not require body for GET unless you document it explicitly
    },
    {
      path: "/orders",
      method: "POST",
      summary: "Create an order",
      description:
        "Creates a new order. The request body must contain `items` (array of {sku, quantity}) and optionally `customerId`.",
      requestBody: {
        content: {
          "application/json": {
            schema: {
              type: "object",
              required: ["items"],
              properties: {
                items: {
                  type: "array",
                  items: { type: "string" },
                },
                customerId: { type: "string" },
              },
            },
          },
        },
      },
    },
  ];

  const openApi = generateOpenApiSpec(routes);
  console.log(JSON.stringify(openApi, null, 2));
}
