## 2️⃣ Python version  

```python
# ---------------------------------------------------------------
# openapi_generator.py
# ---------------------------------------------------------------
import json
from typing import List, Dict, Any

def generate_openapi_spec(route_defs: List[Dict[str, Any]]) -> Dict[str, Any]:
    """
    Generate a full OpenAPI 3.0 document from a list of route definitions.

    Each definition should be a dict with at least:
        - path (str): e.g. "/users"
        - method (str): one of "GET", "POST", etc.
        - summary (optional str)
        - description (optional str)
        - operationId (optional str) – used for idempotent operations
        - requestBody (optional dict with a `content` key)
        - responses (optional dict, default {"200": {"description":"OK"}})

    The function returns the OpenAPI spec as a Python dict which can be
    serialised to JSON/YAML.
    """
    spec: Dict[str, Any] = {
        "openapi": "3.0.0",
        "info": {
            "title": "Generated API (Python)",
            "version": "1.0.0",
        },
        "servers": [{"url": "/"}],  # default server
        "paths": {},
    }

    def make_operation(op_data: Dict[str, Any]) -> Dict[str, Any]:
        """
        Helper that builds an OpenAPI operation object.
        """
        return {
            "operationId": op_data.get("operationId") or str(uuid.uuid4()),
            "summary": op_data.get("summary"),
            "description": op_data.get("description"),
            "requestBody": op_data.get("requestBody", {}),
            "responses": {**op_data.get("responses", {"200": {"description": "OK"}})}
        }

    # Build the paths dictionary.
    for defn in route_defs:
        path_key = defn["path"]
        if path_key not in spec["paths"]:
            spec["paths"][path_key] = {}

        op_name = make_operation({
            "summary": defn.get("summary"),
            "description": defn.get("description"),
            "requestBody": defn.get("requestBody", {}),
            "responses": defn.get("responses", {"200": {"description": "OK"}}),
        })

        # Map HTTP method (lower‑cased) → operation object.
        spec["paths"][path_key][defn["method"].lower()] = op_name

    return spec


# -----------------------------------------------------------------
# Example usage – you can run this file directly or import `generate_openapi_spec`
# into another module.  The example below prints a JSON string to stdout.
# -----------------------------------------------------------------
if __name__ == "__main__":
    from uuid import UUID
    routes: List[Dict[str, Any]] = [
        {
            "path": "/users",
            "method": "GET",
            "summary": "List all users",
            "description":
                "Returns an array of user objects. Supports pagination via `?page=` and `?limit=` query parameters.",
        },
        {
            "path": "/users/{id}",
            "method": "GET",
            "operationId": lambda: str(UUID()),  # optional unique id
            "summary": "Get a single user by ID",
            "description":
                "Returns the full representation of a user identified by `id`.",
        },
        {
            "path": "/orders",
            "method": "POST",
            "summary": "Create an order",
            "description":
                """Creates a new order. The request body must contain `items`
               (array of `{sku, quantity}`) and may optionally include
               `customerId`.""",
            "requestBody": {
                "content": {"application/json": {"schema": {
                    "type": "object",
                    "required": ["items"],
                    "properties": {
                        "items": {"type": "array", "items": {"type": "string"}},
                        "customerId": {"type": "string"},
                    },
                    }},
            },
            # Default response – you can add more status codes here.
        },
    ]

    spec = generate_openapi_spec(routes)
    print(json.dumps(spec, indent=2))
```

