import yaml from 'js-yaml';
import Ajv, { JSONSchemaType } from 'ajv';

const ajk = new Ajv({ strict: true });
/**
 * The shape of the expected config.
 *
 * Extend this object if your YAML contains extra keys.
 */
export interface Config {
  /** Required – project name (used for logging) */
  projectName: string;
  /** Optional – version number, defaults to "1.0" */
  version?: string;
  /** Required – list of enabled modules (must be an array of strings) */
  enabledModules: Array<string>;
}

/**
 * AJV JSONSchema that validates the Config.
 *
 * The `required` keyword guarantees all top‑level keys are present.
 */
const configSchema = ajk.compile<Config>({
  type: 'object',
  required: ['projectName', 'enabledModules'],
  additionalProperties: false,
  properties: {
    projectName: { type: 'string' },
    version:   { type: 'string', default: '1.0' },
    enabledModules: {
      type: 'array',
      items: { type: 'string' },
