// file: pkg/config/config.go -------------------------------------------------
package config

import (
	"encoding/csv"
	"fmt"
	"io/fs"
	"os"

	yaml "gopkg.in/yaml.v2" // standard library has encoding/yaml but v2 adds better error handling
)

// Config mirrors the YAML structure we expect.
type Config struct {
	ProjectName string            `yaml:"projectName"`          // required
	Version     string            `yaml:"version,omitempty"`   // optional, defaults to "1.0"
	EnabledModules []string      `yaml:"enabledModules"`       // required slice
}

// Validate returns nil if the config satisfies our schema; otherwise an error.
func (c Config) Validate() error {
	if c.ProjectName == "" {
		return fmt.Errorf("missing required field 'projectName'")
	}
	if len(c.EnabledModules) == 0 {
		return fmt.Errorf("empty or missing 'enabledModules' slice")
	}
	for _, m := range c.EnabledModules {
		if m == "" {
			return fmt.Errorf("empty module name in enabledModules")
		}
	}
	return nil
}

// ParseAndValidate reads a YAML file, parses it with yaml.Unmarshal,
// then validates against the Config struct.
func ParseAndValidate(filePath string) (Config, error) {
	f, err := os.Open(filePath)
	if err != nil {
		return Config{}, fmt.Errorf("failed to open config: %w", err)
	}
	defer f.Close()

	var cfg Config
	if err = yaml.Unmarshal(f, &cfg); err != nil {
		return Config{}, fmt.Errorf("yaml unmarshal error: %w", err)
	}

	if err := cfg.Validate(); err != nil {
		return Config{}, fmt.Errorf("validation error: %w", err)
	}
	return cfg, nil
}
