```go
// hotreload.go -------------------------------------------------------------
package main

import (
	"encoding/json"
	"fmt"
	"io/ioutil"
	"log"
	"os"
	"path/filepath"
	"sync"
	"time"

	yaml "gopkg.in/yaml.v2" // optional – works with go.mod
)

type ConfigSource struct {
	Path string `json:"path"` // relative to project root (or absolute)
}

// HotReload watches a file and notifies via channel when it changes.
type HotReload struct {
	path      string          // full path on disk
	config    interface{}     // latest parsed config; nil until first change
	mu        sync.RWMutex   // protects config & lastModTime
	lastMod   time.Time       // modification timestamp of the file
	stopCh    chan bool      // signals stop()
	chanNotify chan ConfigSource // optional channel to push new config elsewhere
}

func NewHotReload(cfgPath string, cfgPtr interface{}) *HotReload {
	h := &HotReload{
		path:     cfgPath,
		config:   cfgPtr,
		stopCh:   make(chan bool),
		chanNotify: make(chan ConfigSource), // optional pub/sub if you need external listeners
	}
	return h
}

// Start the watcher (runs in its own goroutine).
func (h *HotReload) Start() {
	go func() {
		for {
			select {
			case <-h.stopCh:
				log.Println("hotreload stopped")
				return

			default:
				stat, err := os.Stat(h.path)
				if err != nil {
					log.Printf("⚠️  %s stat error: %v", h.path, err)
					time.Sleep(200 * time.Millisecond)
					continue
				}

				modTime := stat.ModTime()
				if modTime.Equal(h.lastMod) {
					time.Sleep(200 * time.Millisecond)
					continue // unchanged
				}
				h.lastMod = modTime

				data, err := ioutil.ReadFile(h.path)
				if err != nil {
					log.Printf("⚠️  %s read error: %v", h.path, err)
					time.Sleep(200 * time.Millisecond)
					continue
				}

				var newCfg interface{}
				switch filepath.Ext(h.path) {
				case ".json":
					err = json.Unmarshal(data, &newCfg)
				case ".yaml", ".yml":
					err = yaml.Unmarshal(data, &newCfg)
				default:
					newCfg = string(data) // raw text – no parsing
				}
				if err != nil {
					log.Printf("⚠️  %s parse error: %v", h.path, err)
					time.Sleep(200 * time.Millisecond)
					continue
				}

				h.mu.Lock()
				defer h.mu.Unlock()
				h.config = newCfg
				h.lastMod = modTime

				// push to optional channel if set
				if h.chanNotify != nil {
					h.chanNotify <- ConfigSource{Path: h.path}
				}
			}
		}
	}()
}

// Stop cleanly.
func (h *HotReload) Stop() {
	close(h.stopCh)
}

/* Example usage ----------------------------------------------------------*/
func main() {
	cfg := struct {
		Port int `json:"port"`
	}{}
	h := NewHotReload("/etc/myapp/config.json", &cfg)

	go h.Start()
	time.Sleep(1 * time.Second) // give watcher a moment to start

	// Simulate change by editing the file (or use another process)
	fmt.Println("Current config:", cfg.Port)

	// Stop on interrupt
	ch := make(chan os.Signal, 1)
	signal.Notify(ch, os.Interrupt)
	go func() {
		<-ch
		h.Stop()
		os.Exit(0)
	}()
	select {} // block forever until signal
}
```

**Why it works**

* `os.Stat` + `ModTime()` detects a change; we re‑read the whole file each time.
* Parsing is delegated to language‑specific libraries (`json`, optional `yaml`). Extend with more extensions as needed.
* The watcher runs in its own goroutine, allowing hot‑reload while your program stays responsive.
* Optional channel (`chanNotify`) lets other parts of a larger system react without polling.

