  ## 1️⃣ TypeScript (Node.js)
  
  ```ts
  // hotreload.ts -------------------------------------------------------------
  import fs from 'fs';
  import path from 'path';
  import { EventEmitter } from 'events';
  
  /**
   * Configuration source – a file on disk.
   */
  export interface ConfigSource {
    /** Path to the config file. */
    readonly filePath: string;
  }
  
  /** Event emitted when the configuration changes. */
  type ReloadEvent = {};
  
  /**
   * Hot‑reload manager for a single config source.
   *
   * Usage:
   *   const reload = new HotReload({filePath:'/etc/myapp/config.json'});
   *   reload.on('change', (newCfg) => console.log('reloaded:', newCfg));
   */
  export class HotReload extends EventEmitter {
    private readonly watcher: fs.FSWatcher;
    private lastKnownConfig?: unknown; // will hold the parsed config
  
    constructor(private source: ConfigSource) {
      super();
      this.watcher = fs.watch(source.filePath, (eventType, filename) => {
        if (eventType === 'change') {
          try {
            const raw = fs.readFileSync(source.filePath, 'utf8');
            let newCfg: unknown;
            // Detect format by extension – you can extend with more parsers
            switch (path.extname(source.filePath)) {
              case '.json':
                newCfg = JSON.parse(raw);
                break;
              case '.yaml':
              case '.yml':
                const yaml = require('js-yaml');
                newCfg = yaml.safeLoad(raw);
                break;
              default:
                // fall‑through – treat as raw text (no parsing)
                newCfg = raw;
            }
            this.lastKnownConfig = newCfg;               // keep for later callers
            this.emit('change', newCfg as ReloadEvent);  // bubble up the fresh config
          } catch (err) {
            console.error(`❌ Failed to reload ${source.filePath}:`, err);
          }
        }
      });
    }
  
    /** Stop watching and clean‑up. */
    public destroy() {
      this.watcher.close();
    }
  
    /** Return the most recent parsed configuration (undefined until first change). */
    public get config(): unknown | undefined {
      return this.lastKnownConfig;
    }
  }
  // --------------------------------------------------------------------------
  
  /* Example usage ----------------------------------------------------------*/
  if (require.main === module) {
    // Simple demo: watch ./config.json and print changes
    const reload = new HotReload({filePath: path.join(__dirname, 'config.json')});
    reload.on('change', (cfg) => console.log('🔄 reloaded config →', cfg));
  }
  ```
  
  **Why it works**
  
  * `fs.watch` fires only when the file is **modified**, not on creates/deletes.
  * The parser (`JSON.parse`, optional `js-yaml`) guarantees a typed object that callers can safely destructure.
  * No external dependencies beyond Node’s core modules.
  
