  ## 2️⃣ Python (3.8+)
  
  ```python
  # hotreload.py -------------------------------------------------------------
  import os
  import json
  from pathlib import Path
  from typing import Any, Optional
  
  class HotReload:
      """
      Watch a configuration file and reload it when the on‑disk content changes.
      
      The class exposes `config` which holds the parsed Python object (dict/list/etc.).
      It also emits an internal ``'change'`` event with the new value.
      """
  
      def __init__(self, path: Path):
          self.path = path
          if not path.is_file():
              raise ValueError(f"{path} is not a regular file")
          self._last_config: Optional[Any] = None
  
          # internal emitter – callers can subscribe to `hotreload.change`
          import threading
          self._lock = threading.Lock()
          self._event = threading.Event()
  
      @property
      def config(self) -> Any:
          """Current parsed configuration (may be ``None`` until first change)."""
          return self._last_config
  
      def _watcher_loop(self):
          while True:
              try:
                  # `stat` returns the file’s metadata; if it changed we re‑read
                  stat = self.path.stat()
                  if stat.st_mtime != getattr(self, '_mtime', 0):
                      self._mtime = stat.st_mtime
                      with open(self.path, 'r') as f:
                          raw = f.read()
  
                      # Detect format by extension – extendable later
                      ext = self.path.suffix.lower()
                      if ext == '.json':
                          self._last_config = json.loads(raw)
                      elif ext in ('.yaml', '.yml'):
                          import yaml  # lazy‑import to avoid dependency on all apps
                          self._last_config = yaml.safe_load(raw)
                      else:
                          # treat as raw text (no parsing)
                          self._last_config = raw
  
                      # fire the event – other threads can safely read `config`
                      with self._lock:
                          self._event.set()
              except Exception as exc:          # catch permission errors, etc.
                  print(f"⚠️  {self.path} watcher error:", exc)
              finally:
                  # Sleep a short interval to avoid busy‑loop
                  import time
                  time.sleep(0.2)
  
      def start(self):
          """Begin watching the file."""
          self._thread = threading.Thread(target=self._watcher_loop, daemon=True)
          self._thread.start()
  
      def stop(self):
          """Gracefully shut down the watcher (call on program exit)."""
          # Force a change event so we can break out of loop
          with open(self.path, 'a') as f:
              pass   # dummy write to trigger stat check
          self._event.set()
