## 1️⃣ TypeScript (`node`)

```ts
// src/config.ts -------------------------------------------------------------
import * as fs from "fs";
import * as path from "path";

export interface Config {
  /** Database host */
  dbHost?: string;
  /** Port for the HTTP server (default: 8080) */
  httpPort?: number;
  /** Enable verbose logging */
  logLevel?: "info" | "debug" | "error";
}

/** Load config from CLI flags, then env vars, finally a JSON file. */
export function loadConfig(): Config {
  // ---------- CLI flags ----------
  const args = process.argv.slice(2);
  const cli: Config = {};
  for (let i = 0; i < args.length; ) {
    const key = args[i++];
    let value: string | undefined;
    if (i < args.length) value = args[i++];
    else throw new Error(`Missing value after flag ${key}`);
    switch (key.toLowerCase()) {
      case "--db-host":
        cli.dbHost = value;
        break;
      case "--http-port":
        const portVal = parseInt(value ?? "", 10);
        if (!isNaN(portVal)) cli.httpPort = portVal;
        else throw new Error(`Invalid HTTP port: ${value}`);
        break;
      case "--log-level":
        const logLevel = (value?.toLowerCase() as unknown) as Config["logLevel"];
        if (["info", "debug", "error"].includes(logLevel))
          cli.logLevel = logLevel;
        else throw new Error(`Invalid log level: ${value}`);
        break;
      default:
        // ignore unknown flags
    }
  }

  // ---------- Environment variables ----------
  const env: Config = {};
  for (const [k, v] of Object.entries(process.env)) {
    if (
      k.startsWith("CONFIG_") &&
      ["DB_HOST", "HTTP_PORT", "LOG_LEVEL"].includes(k.replace(/^CONFIG_/i, ""))
    ) {
      switch (k) {
        case "CONFIG_DB_HOST":
          env.dbHost = v;
        case "CONFIG_HTTP_PORT":
          const portEnv = parseInt(v ?? "", 10);
          if (!isNaN(portEnv)) env.httpPort = portEnv;
        case "CONFIG_LOG_LEVEL":
          const logEnv = (v as unknown) as Config["logLevel"];
          if (["info", "debug", "error"].includes(logEnv))
            env.logLevel = logEnv;
      }
    }
  }

  // ---------- Configuration file ----------
  const configFile = path.resolve(process.cwd(), "config.json");
  let cfgFile: Config | undefined;
  try {
    const raw = fs.readFileSync(configFile, "utf8");
    cfgFile = JSON.parse(raw);
  } catch (err) {
    // ignore malformed files – they are optional
  }

  // ---------- Merge precedence ----------
  const merged: Config = { ...cfgFile ?? {}, ...env, ...cli };

  return merged;
}

// ---------------------------------------------------------------------
export default loadConfig;

// Example usage:
/* 
import config from "./config";
console.log(config);
*/
```

### How it works

| Source | Order of lookup |
|--------|-----------------|
| **CLI flags** (`--db-host`, `--http-port`, `--log-level`) | Highest – they replace any value that already exists. |
| **Environment variables** (`CONFIG_DB_HOST`, `CONFIG_HTTP_PORT`, `CONFIG_LOG_LEVEL`) | Middle – used only if the corresponding config key is missing or explicitly overridden by a flag/env var. |
| **JSON file** (`config.json`) | Lowest – provides defaults; can be partially overwritten later, but never overrides flags directly unless you add extra logic (not shown). |

You can extend this pattern to support YAML via `js-yaml` if needed.

