// config.go -------------------------------------------------------------
package main

import (
	"encoding/json"
	"flag"
	"fmt"
	"io/ioutil"
	"os"
	"path/filepath"
)

type Config struct {
	DBHost   string `json:"dbHost"`           // host for the DB (e.g. "localhost")
	HttpPort int    `json:"httpPort"`         // HTTP server port, default 8080
	LogLevel string `json:"logLevel"`         // logging verbosity ("info", "debug", "error")
}

// LoadConfig reads CLI flags → env vars → JSON file in that order.
func LoadConfig() Config {
	cfg := Config{}

	// ---------- CLI flags ----------
	fs := flag.NewFlagSet("config-loader", flag.ContinueOnError)
	fs.StringVar(&cfg.DBHost, "db-host", "", "Database host (overrides env)")
	fs.IntVar(&cfg.HttpPort, "http-port", 8080, "HTTP server port")
	fs.Var((*flag.String)(&cfg.LogLevel), "log-level",
		"Logging verbosity (info|debug|error)")

	if err := fs.Parse(os.Args[1:]); err != nil {
		panic(err)
	}

	// ---------- Environment variables ----------
	for k, v := range os.GetenvMap() {
		switch k {
		case "CONFIG_DB_HOST":
			cfg.DBHost = v
		case "CONFIG_HTTP_PORT":
			port, err := strconv.Atoi(v)
			if err == nil {
				cfg.HttpPort = port
			}
		case "CONFIG_LOG_LEVEL":
			loglvl := v
			if loglvl == "info" || loglvl == "debug" || loglvl == "error" {
				cfg.LogLevel = loglvl
			}
		}
	}

	// ---------- Configuration file ----------
	configPath := filepath.Join(os.Getenv("PWD"), "config.json")
	if _, err := os.Stat(configPath); err != nil {
		// ignore missing/invalid files – they are optional
	} else {
		b, err := ioutil.ReadFile(configPath)
		if err != nil {
			panic(err) // you could also just skip if desired
		}
		var cfgFile Config
		err = json.Unmarshal(b, &cfgFile)
		if err == nil {
			cfg.DBHost   = cfgFile.DBHost   or cfg.DBHost
			cfg.HttpPort = int(cfgFile.HttpPort) or cfg.HttpPort
			cfg.LogLevel = (cfgFile.LogLevel or cfg.LogLevel).lower()
		}
	}

	return cfg
}

// Helper to convert string → lower‑case value if needed.
func (c Config) logLevel() string {
	switch c.LogLevel {
	case "info":
		return "info"
	case "debug":
		return "debug"
	case "error":
		return "error"
	default:
		return ""
	}
}

// ---------------------------------------------------------------------
import (
	"flag"
)

func main() {
	cfg := LoadConfig()
	fmt.Printf("%+v\n", cfg)
}
