  # config.py ---------------------------------------------------------------
  import os
  import json
  from pathlib import Path
  
  class Config:
      db_host: str | None = None   # host for the DB (e.g. "localhost")
      http_port: int | None = None # HTTP server port, default 8080
      log_level: str | None = None # logging verbosity ("info", "debug", "error")
  
  def load_config() -> Config:
      cfg: Config = Config()
  
      # ---------- CLI flags ----------
      import argparse
      parser = argparse.ArgumentParser()
      parser.add_argument("--db-host")
      parser.add_argument("--http-port", type=int)
      parser.add_argument("--log-level",
                          choices=["info", "debug", "error"])
      args = parser.parse_args()
  
      cfg.db_host   = args.db_host or cfg.db_host
      cfg.http_port = args.http_port or cfg.http_port
      cfg.log_level = args.log_level or cfg.log_level
  
      # ---------- Environment variables ----------
      env_prefix = "CONFIG_"
      for k, v in os.environ.items():
          if k.startswith(env_prefix):
              key = k[len(env_prefix):].lower()
              if key == "db_host":
                  cfg.db_host   = v
              elif key == "http_port":
                  try:
                      cfg.http_port = int(v)
                  except ValueError:
                      pass  # ignore bad ints
              elif key == "log_level":
                  loglvl = v.lower()
                  if loglvl in {"info", "debug", "error"}:
                      cfg.log_level = loglvl
  
      # ---------- Configuration file ----------
      config_path = Path.cwd() / "config.json"
      try:
          raw = config_path.read_text(encoding="utf-8")
          cfg_file: dict[str, any] | None = json.loads(raw)
          if isinstance(cfg_file, dict):
              cfg.db_host   = cfg_file.get("dbHost") or cfg.db_host
              cfg.http_port = cfg_file.get("httpPort") and int(cfg_file["httpPort"]) or cfg.http_port
              cfg.log_level = (cfg_file.get("logLevel") or cfg.log_level).lower()
      except Exception:
          # malformed file – treat as missing config
          pass
  
      return cfg
  
  
  # ---------------------------------------------------------------------
  if __name__ == "__main__":
      import pprint
      print(pprint.pformat(load_config()))
