import * as admin from 'firebase-admin';

// -------------------------------------------------------------------
// 1️⃣ Initialise the Admin SDK with your service‑account key.
//    You can either:
//
// • Set the environment variable GOOGLE_APPLICATION_CREDENTIALS to point
//   at a JSON key file (recommended for serverless functions).
// • Or load it directly from a string/Buffer as shown below.
//
// Example: export GOOGLE_APPLICATION_CREDENTIALS="/path/to/key.json"
admin.initializeApp({
  credential: admin.credential.applicationDefault(),
});

const fcm = admin.messaging();

/**
 * Sends a push notification to one or more FCM registration tokens.
 *
 * @param payload   JSON‑encoded message body (can include data, title,
 *                  notification, etc.).
 * @param tokens    Array of FCM registration token strings.
 */
export async function sendFcmNotification(
  payload: Record<string, unknown>,
  tokens: string[]
): Promise<void> {
  const message = admin.messaging().message(payload);

  // Optional – limit to specific platforms or topics
  // message.options?.apns?.badge = /* … */;
  // message.topic = 'all';   // broadcast

  try {
    const response = await fcm.sendMultiple(tokens, message);
    console.log(`Sent ${response.successful} messages`);
    if (response.failed.length) {
      console.warn('Failed tokens:', response.failed.map((f) => f.token));
    }
  } catch (err: any) {
    // Network / SDK errors are thrown synchronously here.
    throw new Error(`FCM send failed: ${err.message}`);
  }
}

