import json
from typing import List, Dict

import firebase_admin
from firebase_admin import messaging


def send_fcm_notification(payload: Dict[str, any],
                          tokens: List[str]) -> None:
    """
    Sends a push notification to the supplied FCM registration tokens.

    Args:
        payload (dict): JSON‑encoded message body. Can contain `data`,
                        `notification`, etc.
        tokens (list of str): List of FCM token strings.
    """
    # Initialise the Admin SDK – you can also pass a service‑account path
    if not firebase_admin._apps:
        credentials = messaging.Certificate('/path/to/serviceAccountKey.json')
        firebase_admin.initialize_app(
            options={'credential': credentials},
            name='fcm-client'
        )
    else:
        # If already initialised, we reuse the default app.
        pass

    fcm = messaging.messaging()

    message = fcm.message(**payload)

    try:
        response = fcm.send_multiple(tokens, message=message)
        print(f"Sent {response.successful} messages")
        if response.failed:
            failed_tokens = [f.token for f in response.failed]
            print("Failed tokens:", failed_tokens)
    except Exception as exc:  # network / SDK errors
        raise RuntimeError(f"FCM send failed: {exc}") from exc


# -------------------------------------------------------------------
# Example usage – you can call this from a Flask/Django view,
# an AWS Lambda (Python), or any script.
if __name__ == "__main__":
    payload = {
        "data": {"url": "https://example.com/news"},
        # Optional notification for richer UI:
        # "notification": {"title": "New Message", "body": "Check out the latest update!"}
    }
    tokens = [
        "<YOUR_FCM_REGISTRATION_TOKEN>",
        # …more token strings
    ]
    send_fcm_notification(payload, tokens)
