## 1️⃣ TypeScript / Node.js version  

> **Prerequisites**
> ```bash
> npm i chromadb @chakra-db/chroma-node openai node-fetch dotenv
> ```
> *(If you prefer another vector DB, replace `chromadb` with the appropriate SDK.)*

```ts
// src/rag.ts --------------------------------------------------------------
import { Chroma } from "chromadb";
import fetch from "node-fetch";
import * as dotenv from "dotenv";

// -----------------------------------------------------------------------
// 1️⃣ Load environment variables (API keys, etc.)
dotenv.config();

const chroma = new Chroma({
  url: process.env.CHROMA_URL!,
  apiKey: process.env.CHROMA_API_KEY!,
});

// -----------------------------------------------------------------------
// 2️⃣ Helper – chunk text into overlapping pieces
function chunkText(text: string, size: number = 256, overlap: number = 64): string[] {
  const chunks: string[] = [];
  for (let i = 0; i < text.length; i += size - overlap) {
    // ensure we don't go past the end of the string
    const start = Math.max(0, i);
    const end   = Math.min(text.length, i + size);
    chunks.push(text.slice(start, end));
  }
  return chunks;
}

// -----------------------------------------------------------------------
// 3️⃣ Helper – embed a chunk with OpenAI’s text‑embedding model
async function embedChunk(chunk: string): Promise<number[]> {
  const resp = await fetch("https://api.openai.com/v1/embeddings", {
    method: "POST",
    headers: {
      Authorization: `Bearer ${process.env.OPENAI_API_KEY!}`,
      "Content-Type": "application/json"
    },
    body: JSON.stringify({
      model: "text-embedding-3-large",
      input: chunk,
    })
  });
  const data = await resp.json();
  return (data as any).embeddings[0];
}

// -----------------------------------------------------------------------
// 4️⃣ Store a chunk in ChromaDB
async function storeChunk(chunk: string, id?: string): Promise<void> {
  // We'll use the chunk itself as an ID for simplicity.
  await chroma.add({ collectionName: "rag-chunks", documents: [{ text: chunk, id }] });
}

// -----------------------------------------------------------------------
// 5️⃣ Retrieve relevant chunks given a query
async function retrieve(query: string): Promise<string[]> {
  const results = await chroma.query({
    collectionName: "rag-chunks",
    queries: [query],
    k: 10               // top‑k retrieval (tweak as needed)
  });
  return results.docs.map(d => d.text);
}

// -----------------------------------------------------------------------
// 6️⃣ Generate a response using the retrieved context
async function generate(prompt: string, query?: string): Promise<string> {
  const resp = await fetch("https://api.openai.com/v1/chat/completions", {
    method: "POST",
    headers: {
      Authorization: `Bearer ${process.env.OPENAI_API_KEY!}`,
      "Content-Type": "application/json"
    },
    body: JSON.stringify({
      model: "gpt-4o-mini",
      messages: [
        { role: "system", content: "You are a helpful assistant that follows instructions precisely." },
        { role: "user",   content: prompt }
      ],
      temperature: 0.2,
      max_tokens: 800
    })
  });
  const data = await resp.json();
  return (data as any).choices[0].message.content;
}

// -----------------------------------------------------------------------
// --------------------------------------------------------------
export async function runRag(
  rawText: string,               // source documents you want to index
  userQuery: string              // the question / prompt from a user
): Promise<string> {
  // ---- Step A – Chunk & embed -----------------------------------------
  const chunks = chunkText(rawText);
  const embeddings = await Promise.all(chunks.map(embedChunk));

  // ---- Step B – Store ---------------------------------------------------
  for (let i = 0; i < chunks.length; i++) {
    await storeChunk(chunks[i], `chunk-${i}`);
  }

  // ---- Step C – Retrieve -----------------------------------------------
  const retrievedChunks = await retrieve(userQuery);

  // Build a prompt that mixes the user question with the relevant context.
  let prompt = `You are an expert. Answer the following question using ONLY the provided text.\n\n`
               + `Question: ${userQuery}\n\n` +
               "Context:\n";
  retrievedChunks.forEach((c, idx) => {
    const i = parseInt(c.match(/chunk-\d+/)?.[0]?.split("-")[1] ?? "-1", 10);
    prompt += `\n--- Chunk ${i+1} ---\n${c}\n`;
  });

  // ---- Step D – Generate -------------------------------------------------
  return await generate(prompt, userQuery);
}
