## 🐍 Python version  

> **Prerequisites**
> ```bash
> pip install chromadb openai python-dotenv requests tqdm
> ```
> *(You can swap `chromadb` for any other vector DB; the logic stays identical.)*

```python
# rag.py ---------------------------------------------------------------
import os, json, sys
from typing import List, Tuple

import chromadb
from chromadb.config import Settings
import openai
import requests
from tqdm import tqdm

openai.api_key = os.getenv("OPENAI_API_KEY")
chroma_url    = os.getenv("CHROMA_URL")
chroma_apikey = os.getenv("CHROMA_API_KEY")

# -----------------------------------------------------------------------
def chunk_text(text: str, size: int = 256, overlap: int = 64) -> List[str]:
    """Split text into overlapping chunks."""
    chunks = []
    step = size - overlap
    for i in range(0, len(text), step):
        start = max(0, i)
        end   = min(len(text), i + size)
        chunks.append(text[start:end])
    return chunks

# -----------------------------------------------------------------------
def embed_chunk(chunk: str) -> List[float]:
    """Return a list of floats – the embedding vector."""
    resp = requests.post(
        "https://api.openai.com/v1/embeddings",
        json={"model": "text-embedding-3-large", "input": chunk},
        headers={"Authorization": f"Bearer {openai.api_key}"}
    )
    resp.raise_for_status()
    return resp.json()["embeddings"]

# -----------------------------------------------------------------------
def store_chunk(chunk: str, idx: str = None) -> None:
    """Add a chunk to ChromaDB (collection name is hard‑coded)."""
    client = chromadb.Client(Settings(
        url=chroma_url,
        api_key=chroma_apikey
    ))
    collection = client.get_collection("rag-chunks")
    if idx is None:
        idx = f"chunk-{len(collection.documents)}"
    collection.add({"text": chunk, "id": idx})

# -----------------------------------------------------------------------
def retrieve(query: str) -> List[str]:
    """Return IDs of the top‑k most similar chunks."""
    client = chromadb.Client(Settings(
        url=chroma_url,
        api_key=chroma_apikey
    ))
    collection = client.get_collection("rag-chunks")
    results = collection.query({"queries": [query]}, k=10)
    # Chroma returns dicts with `text` field.
    return [r["text"] for r in results.docs]

# -----------------------------------------------------------------------
def generate(prompt: str, query: str) -> str:
    """Call the Chat Completion endpoint."""
    resp = requests.post(
        "https://api.openai.com/v1/chat/completions",
        json={
            "model": "gpt-4o-mini",
            "messages": [
                {"role": "system", "content": "You are a helpful assistant that follows instructions precisely."},
                {"role": "user",   "content": prompt}
            ],
            "temperature": 0.2,
            "max_tokens": 800
        },
        headers={"Authorization": f"Bearer {openai.api_key}"}
    )
    resp.raise_for_status()
    return resp.json()["choices"][0]["message"]["content"]

# -----------------------------------------------------------------------
def run_rag(raw_text: str, user_query: str) -> Tuple[List[str], str]:
    """
    Full RAG pipeline.
    
    Returns:
        (retrieved_chunks, generated_answer)
    """
    # 1️⃣ Chunk & embed
    chunks = chunk_text(raw_text)
    embeddings = [embed_chunk(c) for c in tqdm(chunks, desc="Embedding")]

    # 2️⃣ Store
    client = chromadb.Client(Settings(
        url=chroma_url,
        api_key=chroma_apikey
    ))
    collection = client.get_collection("rag-chunks")
    for i, emb in enumerate(tqdm(embeddings, desc="Storing")):
        collection.add({"text": chunks[i], "id": f"chunk-{i}"})

    # 3️⃣ Retrieve
    retrieved_ids = retrieve(user_query)
    
    # Re‑embed the IDs to get their vectors (Chroma can fetch by id directly).
    retrieved_texts = [collection.get(id=id_).to_dict()["text"] for id_ in retrieved_ids]

    # Build prompt that mixes query + context.
    prompt = (
        "You are an expert. Answer the following question using ONLY the provided text.\n\n"
        f"Question: {user_query}\n\nContext:\n"
    )
    for i, txt in enumerate(retrieved_texts):
        prompt += f"\n--- Chunk {i+1} ---\n{txt}\n"

    # 4️⃣ Generate
    answer = generate(prompt, user_query)
    return retrieved_texts, answer

# -----------------------------------------------------------------------
if __name__ == "__main__":
    source = """
      The quick brown fox jumps over the lazy dog.
      A fast brown fox leaped above a sleepy canine.
      Dogs are often depicted as loyal companions.
    """
    query   = "What animal is described jumping?"
    
    retrieved, generated = run_rag(source, query)
    print("\n🔎 Retrieved chunks:")
    for c in retrieved:
        print("•", c[:120], "...")  # preview
    print("\n💬 Generated answer:", generated)
```

### How it works

| Step | What happens | Key code |
|------|--------------|----------|
| **Chunk** | `chunk_text` splits the source document into overlapping pieces (default 256 tokens, overlap 64). | `chunkText()` / list‑comprehension |
| **Embed** | Each chunk is sent to OpenAI’s `/embeddings` endpoint; vectors are collected. | `embed_chunk()` |
| **Store** | Vectors + IDs (`chunk-0`, …) are inserted into ChromaDB collection *rag-chunks*. | `store_chunk()` / client.add() |
| **Retrieve** | Query the same vector DB with the user’s question → top‑k chunk IDs. | `retrieve()` |
| **Generate** | Prompt = “You are an expert… Answer … Question: … Context:” + retrieved chunks → call Chat Completion (`gpt-4o-mini`). | `generate()` |

