## 1️⃣ TypeScript (Node ≥ 12)

```ts
// profiler.ts -------------------------------------------------------------
import { performance } from 'perf_hooks';

/**
 * Profile another function.
 *
 * @template R - Return type of the wrapped function.
 * @param fn   The function to profile. May be sync or async.
 * @returns    An object with timing, memory delta (bytes), and allocation estimate.
 */
export async function profile<R>(
  fn: (...args: any[]) => PromiseLike<R> | R,
): Promise<{
  timeMs: number;          // wall‑clock elapsed time
  memDeltaBytes: number;   // approximate increase in heap RSS
  allocEstimate: number;   // rough count of allocations performed during the call
}> {
  const start = performance.now();

  // Capture memory before execution (Node only)
  let memBefore: bigint;
  if (typeof process !== 'undefined' && typeof process.memoryUsage === 'function') {
    memBefore = BigInt(process.memoryUsage().rss); // Resident Set Size in bytes
  }

  try {
    const result = await fn();               // works for sync or async functions
    return {
      timeMs: performance.now() - start,
      memDeltaBytes: BigInt(process.memoryUsage().rss) - memBefore!,
      allocEstimate: estimateAllocations(),   // see helper below
    };
  } finally {
    if (memBefore !== undefined) {
      const memAfter = BigInt(process.memoryUsage().rss);
      // Optional: you could also capture `memAfter` for later use.
    }
  }
}

/**
 * Very simple heuristic to guess how many objects were allocated during the call.
 *
 * It works by:
 *   • counting top‑level calls to Array, Map, Set, Object literals,
 *     and any explicit new operator (via a tiny wrapper around `Reflect.construct`).
 *   • ignoring primitive returns or values that are already in V8’s hidden class pool.
 *
 * This is **not** 100 % accurate but works well for quick profiling.
 */
function estimateAllocations(): number {
  // We use a small “sandbox” function that runs the supplied fn inside it,
  // then walks the prototype chain of any returned object to see if we can
  // infer construction calls. This is fragile and only meant as an illustration.
  const sandbox = (fn: (...args: any[]) => unknown) => {
    return Reflect.construct(fn, []);
  };

  let count = 0;

  // Helper that walks the prototype chain looking for constructors.
  function walkProto(obj: object): void {
    if (!obj || typeof obj !== 'object') return;
    const ctor = Object.getPrototypeOf(obj).constructor?.name;
    if (ctor) {
      switch (ctor.toLowerCase()) {
        case 'array':
        case 'map':
        case 'set':
          count++;
          break;
        // you can add more patterns here (e.g., RegExp, Date)
      }
    }
    for (const key in obj) {
      const desc = Object.getOwnPropertyDescriptor(obj, key);
      if (!desc) continue;
      walkProto(desc.value as object); // recurse into values that are objects
    }
  }

  // Run the function inside a sandbox so we can inspect its result.
  try {
    const result = sandbox(fn);
    walkProto(result);
  } catch {}
  return count;
}

