    Returns
    -------
    dict
        {
            "time_ms": float,
            "mem_delta_bytes": int,
            "alloc_estimate": int   # rough count of allocations performed during the call
        }
    """
    tracemalloc.start()
    start = time.perf_counter()

    try:
        result = fn()               # works for sync or async functions (see wrapper below)
        return {
            "time_ms": (time.perf_counter() - start) * 1000,
            "mem_delta_bytes": tracemalloc.get_traced_memory()[1] -
                               tracemalloc.get_traced_memory(start=tracemalloc.TRACEMALLOC_START)[1],
            # The above double‑call is needed because get_traced_memory resets the counter.
            "alloc_estimate": estimate_allocations(),
        }
    finally:
