## 1️⃣ TypeScript (Node.js)

```ts
// benchmark.ts --------------------------------------------------------------
import { performance } from 'perf_hooks';

/**
 * Runs `fn` N times and returns an array of elapsed milliseconds for each run.
 *
 * @template T – type returned by fn()
 * @param fn – function to be measured; takes no arguments and may return anything
 * @param n   – number of iterations (must be ≥ 1)
 * @returns latency in ms for each iteration, sorted ascending
 */
function benchmark<T>(fn: () => T, n: number): Promise<number[]> {
  const results = new Array(n);
  // Run synchronously; you could also use `await` inside fn if it returns a promise.
  return new Promise((resolve) => {
    for (let i = 0; i < n; ++i) {
      const start = performance.now();
      fn();               // run the function
      results[i] = performance.now() - start;
    }
    resolve(results);
  });
}

/**
 * Compute a percentile from an already‑sorted array.
 *
 * @param sorted – numeric values in ascending order
 * @param p     – desired percentile (0‑100)
 */
function percentile(sorted: number[], p: number): number {
  const idx = Math.floor((p / 100) * (sorted.length - 1));
  return sorted[idx];
}

/**
 * Public API that prints the three requested percentiles.
 *
 * @param fn   – function to benchmark
 * @param n    – how many times to run it
 */
export async function bench<T>(fn: () => T, n = 1000) {
  const timings = await benchmark(fn, n);
  // Sort for percentile calculation (stable sort is fine)
  const sorted = [...timings].sort((a, b) => a - b);

  const median   = Math.round(percentile(sorted, 50));
  const p95      = Math.round(percentile(sorted, 95));
  const p99      = Math.round(percentile(sorted, 99));

  console.log(`p50 : ${median} ms`);
  console.log(`p95 : ${p95}   ms`);
  console.log(`p99 : ${p99}   ms`);
}

// -----------------------------------------------------------------------
// Example usage ---------------------------------------------------------
if (require.main === module) {
  // A tiny dummy function to demonstrate – replace with whatever you need.
  const heavyWork = () => {
    let sum = 0;
    for (let i = 0; i < 1_000_000; ++i) {
      sum += Math.random();
    }
    return sum;
  };

  // Run the benchmark once per second, repeat it 1000 times.
  bench(heavyWork);
}
```

