import time, statistics, sys

def bench(fn: callable, n: int = 1000) -> None:
    """Run `fn` N times and print p50 / p95 / p99 latencies."""
    timings = [time.perf_counter() for _ in range(n)]
    # Call the function once to get a fresh timing baseline (optional)
    fn()
    for _ in range(n - 1):
        fn()

    sorted_timings = sorted(timings)

    median   = round(statistics.median(sorted_timings))
    p95       = round(statistics.quantiles(sorted_timings, n=100)[19])
    # statistics.quantiles returns a tuple; index 19 corresponds to the 95‑th percentile.
    p99       = round(statistics.quantiles(sorted_timings, n=100)[98])

