package main

import (
	"bufio"
	"fmt"
	"io/ioutil"
	"math/rand"
	"os"
	"sort"
	"time"

	"golang.org/x/exp/slices"
)

// bench runs `fn` n times and prints p50 / p95 / p99.
func bench(fn func() float64, n int) {
	var timings []float64
	for i := 0; i < n; i++ {
		start := time.Now()
		fn()
		timings = append(timings, time.Since(start).Seconds())
	}

	sort.Float64s(timings)

	midIdx := n / 2
	p50 := int(round(timings[midIdx]))
	p95Idx := int(float64(n)*0.95)
	p95 = int(round(timings[p95Idx]))
	p99Idx := int(float64(n)*0.99)
	p99 = int(round(timings[p99Idx]))

	fmt.Printf("p50 : %.3f s\n", float64(p50)/1000)
	fmt.Printf("p95 : %.3f s\n", float64(p95)/1000)
	fmt.Printf("p99 : %.3f s\n", float64(p99)/1000)
}

// Helper round (half‑up) – used for integer conversion.
func round(x float64) int {
	if x < 0 {
		return int(-x + .5)
	}
	return int(x + .5)
}

// -----------------------------------------------------------------------
func main() {
	// Example heavy workload: allocate a slice and fill it with random floats.
	rand.Seed(time.Now().UnixNano())
	fn := func() float64 {
		var total float64
		for i := 0; i < 1_000_000; i++ {
			total += rand.Float64()
		}
		return total
	}

	bench(fn, 1000)
}
