## 4️⃣ Rust

Rust’s standard library lacks a built‑in percentile function, so we compute it manually.

```rust
// Cargo.toml -------------------------------------------------------------
// [dependencies]
// (none required – only stdlib)

use std::time::{Duration, Instant};
use std::vec;

fn bench<F>(mut f: F, n: usize) -> Result<(), Box<dyn std::error::Error>>
where
    F: FnMut(),
{
    let mut timings = Vec::with_capacity(n);
    for _ in 0..n {
        let start = Instant::now();
        f();
        // Convert nanoseconds to seconds as a float.
        let elapsed = Duration::now().elapsed().as_secs_f64();
        timings.push(elapsed);
    }

    // Sort the timings (stable sort is fine)
    timings.sort_by(|a, b| a.partial_cmp(b).unwrap());

    // Helper: linear interpolation for percentile
    fn percentile(sorted: &[f64], p: f64) -> f64 {
        let idx = (p / 100.0) * (sorted.len() as f64 - 1.0);
        let lower = idx.floor() as usize;
        let upper = lower + 1;
        if upper >= sorted.len() {
            return sorted[lower];
        }
        let t = idx - idx.floor();
        sorted[lower] * (1.0 - t) + sorted[upper] * t
    }

    let median   = percentile(&timings, 50.0);
    let p95      = percentile(&timings, 95.0);
    let p99      = percentile(&timings, 99.0);

    println!("p50 : {:.3} s", median);
    println!("p95 : {:.3} s", p95);
    println!("p99 : {:.3} s", p99);
    Ok(())
}

// -----------------------------------------------------------------------
fn main() -> Result<(), Box<dyn std::error::Error>> {
    // Example workload: sum a large vector of random numbers.
    let mut rng = rand::thread_rng();
    let heavy_work = || {
        let mut total: f64 = 0.0;
        for _ in 0..1_000_000 {
            total += rng.gen::<f64>();
        }
        total
    };

    bench(heavy_work, 1000)?;
    Ok(())
}
```

