    beforeSnapshot: string,
    afterSnapshot: string,
): Promise<{
    leaks: Record<string, { name: string; sizeDiff: number }>;
    shrinks: Record<string, { name: string; sizeDiff: number }>;
    summary: {
        totalRootsExamined: number;
        overallSizeDeltaBytes?: bigint | null; // may be undefined if snapshots differ in format
    };
}> {
    const before = JSON.parse(beforeSnapshot);
    const after  = JSON.parse(afterSnapshot);

    // Helper to walk the snapshot tree and collect root names + sizes.
    const collectRoots = (node: any, pathParts: string[] = []): Record<string, number> => {
        let size = node.size ?? 0;               // raw bytes reported by Chrome
        if ('children' in node) {
            for (const child of node.children) {
                Object.assign(size, collectRoots(child, [...pathParts, String(child.id)]));
            }
        }
        return { [node.name || 'root']: size };
    };

    const beforeRoots = collectRoots(before);
    const afterRoots  = collectRoots(after);

    // Normalise keys (some snapshots use numeric ids as strings)
    const normBefore = Object.fromEntries(
        Object.entries(beforeRoots).map(([k, v]) => [String(k), v])
    );
    const normAfter  = Object.fromEntries(
        Object.entries(afterRoots).map(([k, v]) => [String(k), v])
    );

    // Compare each root
    const leaks: Record<string, { name: string; sizeDiff: number }> = {};
    const shrinks: Record<string, { name: string; sizeDiff: number }> = {};

    Object.keys(normBefore).forEach((id) => {
        const beforeSize = normBefore[id] ?? 0;
        const afterSize  = normAfter[id]?.toString() ?? 'N/A';
        if (afterSize === 'N/A') return; // root missing → treat as leak
        const diff = Number(afterSize) - beforeSize;
        if (diff > 0) leaks[String(id)] = { name: id, sizeDiff: diff };
    });

    Object.keys(normAfter).forEach((id) => {
        if (!normBefore[id]) return; // new root → treat as leak
        const afterSize = normAfter[id] ?? 0;
        const beforeSize = normBefore[id]?.toString() ?? 'N/A';
        if (beforeSize === 'N/A') return; // disappeared from both snapshots?
        const diff = afterSize - Number(beforeSize);
        if (diff > 0) leaks[String(id)] = { name: id, sizeDiff: diff };
    });

    Object.keys(normAfter).forEach((id) => {
        if (!normBefore[id]) return;
        const beforeSize = normBefore[id] ?? 0;
        const afterSize  = normAfter[id]?.toString() ?? 'N/A';
        // If the root is gone from after snapshot but present in before → shrink
        if (afterSize === 'N/A') {
            shrinks[String(id)] = { name: id, sizeDiff: -Number(beforeSize) };
        }
    });

    const totalRootsExamined = Object.keys(normBefore).length + Object.keys(normAfter).length;
    // Chrome may report `null` for some roots; treat as 0.
    const overallDeltaBytes =
        beforeSnapshot.includes('totalHeapSizeLimitMb') &&
        afterSnapshot.includes('totalHeapSizeLimitMb')
            ? BigInt(beforeSnapshot.match(/"totalHeapSizeLimitMb"\s*:\s*(\d+)/)?.[1] ?? '0')
              - BigInt(afterSnapshot.match(/"totalHeapSizeLimitMb"\s*:\s*(\d+)/)?.[1] ?? '0')
            : null;

    return {
        leaks,
        shrinks,
        summary: { totalRootsExamined, overallSizeDeltaBytes },
    };
}
