    Compare two heap snapshots (JSON strings) and report leaks & shrinks.

    Returns a dict with three keys:
      - `leaks`:   { id_str : {"name": "<path>", "sizeDiff": delta_bytes} }
      - `shrinks`: { id_str : {"name": "<path>", "sizeDiff": delta_bytes} }
      - `summary` : {
            "totalRootsExamined": int,
            "overallSizeDeltaBytes": Optional[bigint]   # may be None if formats differ
        }

    The function assumes Chrome DevTools Protocol snapshots (same schema).
    """
    before = json.loads(before_snapshot)
    after  = json.loads(after_snapshot)

    def norm(root: dict) -> dict:
        """Normalize keys to strings."""
        return {str(k): v for k, v in root.items()}

    b_norm = norm(collect_roots(before))
    a_norm = norm(collect_roots(after))

    leaks = {}
    shrinks = {}

    # Compare each existing root
    for id_str, before_size in b_norm.items():
        after_size = str(a_norm.get(id_str, "N/A"))
        if after_size == "N/A":
            continue  # disappeared → leak
        diff = int(after_size) - before_size
        if diff > 0:
            leaks[id_str] = {"name": id_str, "sizeDiff": diff}

    for id_str, after_size in a_norm.items():
        if id_str not in b_norm:
            continue  # new root → leak (already handled above)
        before_size = float(b_norm[id_str])
        after_size_float = float(after_size) if isinstance(after_size, str) else int(after_size)
        diff = after_size_float - before_size
        if diff > 0:
