// workerPool.ts -------------------------------------------------------------
import { Worker } from 'worker_threads';
import * as fs from 'fs';

/**
 * Configuration for the auto‑scaling pool.
 */
export interface AutoScaleConfig {
    /** Maximum queue depth before we start adding workers. */
    maxDepth: number;
    /** Minimum number of workers to keep running (useful when many short jobs). */
    minWorkers?: number;
    /** Workers are considered idle if they have not received a task in this ms. */
    idleTimeoutMs?: number;

    /**
     * Optional callback that receives the current queue depth and worker count.
     * Useful for logging or UI updates.
     */
    onMetrics?(depth: number, workers: Worker[]): void;
}

/**
 * AutoScalingWorkerPool – monitors a shared task queue and scales workers up/down.
 *
 * The pool works as follows:
 *   • Workers pull tasks from a **shared** `Array` (the “queue”).
 *   • If the length of that array exceeds `maxDepth`, new Worker threads are spawned
 *     until either the queue shrinks or we hit `minWorkers`.
 *   • When the queue empties for longer than `idleTimeoutMs`, workers are terminated.
 */
export class AutoScalingWorkerPool<T> {
    private readonly tasks: T[] = [];               // shared task array (queue)
    private readonly config: Required<AutoScaleConfig>;
    private workers: Worker[] = [];
    private lastTaskTime?: number;                 // timestamp of the most recent push

    constructor(config: AutoScaleConfig) {
        this.config = Object.freeze({
            maxDepth: config.maxDepth ?? 10,
            minWorkers: config.minWorkers ?? Math.ceil(Math.sqrt(process.cpuCount())),
            idleTimeoutMs: config.idleTimeoutMs ?? 30000,
            onMetrics: config.onMetrics
        });
        // Ensure at least the minimum number of workers are alive.
        this._ensureMinWorkers();
    }

    /** Push a new task onto the queue. */
    enqueue(task: T): void {
        this.tasks.push(task);
        this.lastTaskTime = Date.now();

        // If we just added a task and the depth exceeds our limit, try to add workers.
        if (this.tasks.length > this.config.maxDepth) {
            this._maybeAddWorker();
        }
    }

    /** Remove all workers – called when shutting down. */
    async shutdown(): Promise<void> {
        await Promise.all(this.workers.map(w => w.terminate()));
        this.workers = [];
    }

    // --------------------------------------------------------------------------

    private _ensureMinWorkers(): void {
        const needed = Math.max(
            this.config.minWorkers,
            Math.ceil(this.tasks.length / (this.config.maxDepth ?? 1))
        );
        while (this.workers.length < needed) {
            this._maybeAddWorker();
        }
    }

    private async _maybeAddWorker(): Promise<void> {
        if (
            // Queue is long enough AND
            this.tasks.length > this.config.maxDepth &&
            // Not already at the maximum number of workers we’d like to run.
            (this.config.minWorkers === undefined ||
                this.workers.length < (this.config.minWorkers ?? 10))
        ) {
            const worker = new Worker(__filename, { /* optional args */ });
            worker.on('message', msg => {
                // Forward any messages back to the main thread – e.g. metrics.
                if (typeof msg === 'object' && msg !== null) {
                    this.config.onMetrics?.(this.tasks.length, this.workers);
                }
            });
            worker.on('error', err => console.error('Worker error:', err));
            worker.on('exit', code => {
                console.log(`Worker exited with code ${code}`);
                // If we just lost the last worker while idle, start a new one.
                if (this.workers.length === 0 && this.tasks.length === 0) {
                    setTimeout(() => this._maybeAddWorker(), this.config.idleTimeoutMs);
                }
            });
            this.workers.push(worker);
        }
    }

    // --------------------------------------------------------------------------

    /** Helper – called internally when a worker finishes its current task. */
    private _removeIdleWorkers(): void {
        const now = Date.now();
        if (this.lastTaskTime === undefined) return; // never had any tasks yet

        const idleSince = this.lastTaskTime!;
        if (now - idleSince > this.config.idleTimeoutMs) {
            while (
                this.workers.length > 0 &&
                !this.tasks.length &&               // queue is empty
                now - idleSince >= this.config.idleTimeoutMs
            ) {
                const w = this.workers.pop()!;
                w.terminate();
            }
        }
    }

    /** Internal – called by each worker when it finishes a task. */
    private _workerDone(): void {
        // Nothing else to do here; the pool will call _removeIdleWorkers on its own.
    }
}
// ---------------------------------------------------------------------------

/* Example usage -----------------------------------------------------------*/
if (require.main === module) {
    const config: AutoScaleConfig = {
        maxDepth: 20,
        minWorkers: 2,
        idleTimeoutMs: 30000,
        // optional: console.log each time metrics change
        onMetrics(depth, workers) {
            console.log(`Queue depth=${depth}, active workers=${workers.length}`);
        }
    };

    const pool = new AutoScalingWorkerPool<number>(config);

    // Simulate work – push many tasks quickly to trigger scaling up.
    for (let i = 0; i < 50; i++) {
        setTimeout(() => pool.enqueue(i), i * 200);   // staggered pushes
    }

    // After a while, let the system idle and watch workers disappear.
    setTimeout(() => {
        console.log('Idle > idleTimeoutMs – draining workers');
        process.exit(0);
    }, config.idleTimeoutMs + 5000);
}
