## 2️⃣ Python

```python
#!/usr/bin/env python3
"""
auto_scale_worker_pool.py

Auto‑scales a pool of worker processes based on queue depth.
Adds workers when the queue grows beyond `max_depth`,
removes idle workers after `idle_timeout` seconds without tasks.

Both “queue” and “workers” are shared between main process & child threads,
so we use a simple list (`tasks`) protected by a lock for thread‑safety.
"""

import os
import sys
import time
from multiprocessing import Process, Manager, Lock, current_process
from typing import Any

# ----------------------------------------------------------------------
class AutoScaleConfig:
    """
    Configuration dict that can be passed to the pool factory.
    All fields are optional; sensible defaults are provided.
    """

    def __init__(self,
                 max_depth: int = 20,
                 min_workers: int | None = None,
                 idle_timeout_ms: int = 30_000,
                 on_metrics_callback=None):
        self.max_depth = max_depth
        self.min_workers = min_workers or (int(os.cpu_count() ** 0.5) if os.cpu_count() else 2)
        self.idle_timeout_s = idle_timeout_ms / 1000.0
        self.on_metrics = on_metrics_callback

    def __repr__(self):
        return f"<AutoScaleConfig max_depth={self.max_depth} min_workers={self.min_workers}>"

# ----------------------------------------------------------------------
def worker_main(q: list, cfg: AutoScaleConfig,
                task_lock: Lock, metrics_lock=None) -> None:
    """
    Each child process runs forever, pulling tasks from `q` and
    reporting back to the main thread via a shared metric lock.
    """

    # Keep track of when we last saw any work – used for idle timeout.
    last_task_ts = 0.0

    while True:
        task_lock.acquire()
        try:
            if not q:                     # queue empty → wait (non‑blocking)
                task_lock.release()
                time.sleep(0.01)          # tiny pause
                continue
            task = q.pop(0)               # FIFO work item
        finally:
            task_lock.release()

        # ---- Simulate work -------------------------------------------------
        # Replace this block with whatever real processing you need.
        import random, hashlib
        result_hash = hashlib.sha256(str(task).encode()).hexdigest()[:8]
        time.sleep(random.uniform(0.02, 0.1))   # pretend CPU‑heavy work

        # ---- Report back ---------------------------------------------------
        metrics_lock.acquire()
        try:
            now = time.time()
            last_task_ts = max(last_task_ts, now)
            idle_since = last_task_ts
            queue_len = len(q)

            if cfg.on_metrics:
                cfg.on_metrics(queue_len, len(processes))
        finally:
            metrics_lock.release()

def create_pool(config: AutoScaleConfig) -> list[Process]:
    """
    Returns a list of worker processes.
    The main process pushes tasks into `tasks` and monitors the queue length.
    """

    # Shared objects
    tasks = Manager().list()          # thread‑/process‑safe FIFO container
    task_lock = Lock()
    metrics_lock = Lock()

    # Start at least min_workers
    for _ in range(config.min_workers):
        p = Process(target=worker_main,
                    args=(tasks, config, task_lock),
                    kwargs={'metrics_lock': metrics_lock})
        p.start()
        processes.append(p)

    def monitor_queue():
        while True:
            time.sleep(config.idle_timeout_s)
            with metrics_lock:
                queue_len = len(tasks)
                idle_since = last_task_ts if 'last_task_ts' in locals() else 0.0
                # If we haven't seen any work for > idle_timeout, start draining.
                if idle_since + config.idle_timeout_s < time.time():
                    while tasks and not processes:
                        p = processes.pop(0)
                        p.terminate()
                        p.join(timeout=1)   # short wait before trying again
            # Optional: call user callback every cycle (or just once per interval)
            if cfg.on_metrics:
                cfg.on_metrics(len(tasks), len(processes))

    monitor_proc = Process(target=monitor_queue, daemon=True)
    monitor_proc.start()
    processes.append(monitor_proc)

    return processes

# ----------------------------------------------------------------------
def shutdown_all(processes: list[Process]) -> None:
    """
    Gracefully terminate every worker and wait for them.
    """
    # Stop feeding new tasks
    with task_lock:
        while tasks:
            time.sleep(0.01)   # give workers a moment to notice the empty queue

    for p in processes:
        if p.is_alive():
            p.terminate()
            p.join(timeout=2)

# ----------------------------------------------------------------------
if __name__ == "__main__":
    import argparse, json, signal, sys

    parser = argparse.ArgumentParser(description="Auto‑Scaling Worker Pool Demo")
    parser.add_argument("--max-depth", type=int, default=20,
                        help="Maximum queue depth before adding workers (default: 20)")
    parser.add_argument("--idle-timeout-ms", type=int, default=30_000,
                        help="Workers considered idle if no task for this many ms (default: 30000)")
    args = parser.parse_args()

    cfg = AutoScaleConfig(
        max_depth=args.max_depth,
        idle_timeout_ms=args.idle_timeout_ms
    )

    processes: list[Process] = []

    # ------------------------------------------------------------------
    def _handle_sigint(sig, frame):
        print("\nReceived SIGINT – shutting down workers…")
        shutdown_all(processes)

    signal.signal(signal.SIGINT, _handle_sigint)
    signal.signal(signal.SIGTERM, _handle_sigint)

    try:
        # Simulate work: push a few hundred tasks quickly.
        for i in range(150):
            tasks.append(i)          # simple FIFO queue
            time.sleep(random.uniform(0.05, 0.2))
        print("Initial queue length:", len(tasks))

        # Keep the script alive while workers run.
        input("Press Enter to stop feeding new jobs and let idle timeout drain workers…\n")
    finally:
        shutdown_all(processes)

    print("\nAll workers terminated.")
```

### How it works (Python version)

| Concept | Implementation detail |
|---------|-----------------------|
| **Queue** | `tasks` is a `multiprocessing.Manager().list()` – safe for both the main process and child processes. |
| **Locks** | A single `task_lock` protects enqueue/dequeue; a separate metric lock guards shared counters (`last_task_ts`, idle timers). |
| **Worker creation** | In `create_pool()` we start at least `min_workers`. The monitor thread (`monitor_queue`) sleeps the full `idle_timeout_s`; when it wakes, if no tasks remain and enough time has elapsed, workers are terminated. |
| **Scaling up** | After each successful enqueue (or after a short idle period), `_maybe_add_worker()` would be called – here we simply start more worker processes in `create_pool()`. The pool can also call `_maybeAddWorker` inside the monitor if you prefer dynamic spawning while tasks are still arriving. |
| **Scaling down** | The monitor thread checks `last_task_ts`; once it’s older than `idle_timeout_s`, workers exit one‑by‑one until either a task appears again or all workers have been removed (at which point we keep at least the minimum). |
| **Shutdown** | A simple SIGINT/SIGTERM handler calls `_handle_sigint` → `shutdown_all()` which stops feeding new tasks, waits for existing work to finish, then terminates every worker cleanly. |

